INSERT INTO target_profiles (id, target_total_score, status, description, created_at, updated_at) VALUES
(1, 450, b'1', 'Mục tiêu Sơ cấp 450 TOEIC - Nắm vững từ vựng cơ bản và cấu trúc ngữ pháp thông dụng.', NOW(), NOW()),
(2, 550, b'1', 'Mục tiêu Tiền trung cấp 550 TOEIC - Nền tảng giao tiếp công sở và đọc hiểu tài liệu ngắn.', NOW(), NOW()),
(3, 650, b'1', 'Mục tiêu Trung cấp 650 TOEIC - Chuẩn đầu ra đại học và giao tiếp công sở tự tin.', NOW(), NOW()),
(4, 750, b'1', 'Mục tiêu Thành thạo 750 TOEIC - Tự tin thuyết trình, xử lý hợp đồng và email chuyên môn.', NOW(), NOW()),
(5, 850, b'1', 'Mục tiêu Nâng cao 850 TOEIC - Làm việc chuyên nghiệp trong môi trường tập đoàn đa quốc gia.', NOW(), NOW());
INSERT INTO parts (id, name, description, sections, created_at, updated_at) VALUES
(1, 'Part 1: Photographs', 'Mô tả hình ảnh: Nghe 4 câu mô tả về một bức tranh và chọn câu chính xác nhất.', 'LISTENING', NOW(), NOW()),
(2, 'Part 2: Question - Response', 'Hỏi - Đáp: Nghe một câu hỏi hoặc phát biểu và chọn 1 trong 3 phản hồi phù hợp.', 'LISTENING', NOW(), NOW()),
(3, 'Part 3: Short Conversations', 'Hội thoại ngắn: Nghe đoạn trao đổi giữa 2-3 người và trả lời 3 câu hỏi liên quan.', 'LISTENING', NOW(), NOW()),
(4, 'Part 4: Short Talks', 'Bài nói ngắn: Nghe bài độc thoại (thông báo, tin nhắn thoại, bản tin) và trả lời 3 câu hỏi.', 'LISTENING', NOW(), NOW()),
(5, 'Part 5: Incomplete Sentences', 'Điền vào câu: Chọn 1 trong 4 từ/cụm từ thích hợp nhất hoàn thành câu văn.', 'READING', NOW(), NOW()),
(6, 'Part 6: Text Completion', 'Điền vào đoạn văn: Điền từ, cụm từ hoặc câu văn vào 4 chỗ trống trong văn bản.', 'READING', NOW(), NOW()),
(7, 'Part 7: Reading Comprehension', 'Đọc hiểu văn bản: Đọc đoạn đơn, đôi, ba (email, hóa đơn, thông báo) và trả lời câu hỏi.', 'READING', NOW(), NOW());
INSERT INTO abilities (id, name, description, sections, part_id, created_at, updated_at) VALUES
(1, 'Human Actions Identification', 'Nhận diện chính xác hành động của con người qua động từ và thì hiện tại tiếp diễn.', 'LISTENING', 1, NOW(), NOW()),
(2, 'Object & Scene Recognition', 'Phân tích vị trí đồ vật, trạng thái tĩnh và bối cảnh không gian trong tranh không người.', 'LISTENING', 1, NOW(), NOW()),
(3, 'Wh-Questions Reflex', 'Phản xạ nhận biết và trả lời trọng tâm các câu hỏi thông tin Who, Where, When, Why, How.', 'LISTENING', 2, NOW(), NOW()),
(4, 'Yes/No & Choice Questions', 'Xử lý câu hỏi xác nhận Yes/No, câu hỏi đuôi và câu hỏi lựa chọn dùng liên từ OR.', 'LISTENING', 2, NOW(), NOW()),
(5, 'Indirect & Evasive Responses', 'Phát hiện câu trả lời gián tiếp, né tránh hoặc chuyển hướng thông tin thực tế.', 'LISTENING', 2, NOW(), NOW()),
(6, 'Specific Details & Keywords Tracking', 'Nghe quét bắt từ khóa (thời gian, địa điểm, số lượng, chi phí) trong hội thoại công sở.', 'LISTENING', 3, NOW(), NOW()),
(7, 'Purpose & Speaker Implication', 'Suy luận mục đích cuộc trò chuyện, nghề nghiệp và hành động tiếp theo của người nói.', 'LISTENING', 3, NOW(), NOW()),
(8, 'Public Announcements Comprehension', 'Nghe hiểu thông báo nơi công cộng (sân bay, siêu thị, nhà máy, sự kiện công ty).', 'LISTENING', 4, NOW(), NOW()),
(9, 'Voicemails & News Reports', 'Nắm bắt nội dung tin nhắn hộp thư thoại kinh doanh, bản tin giao thông và tin tài chính.', 'LISTENING', 4, NOW(), NOW()),
(10, 'Parts of Speech & Word Formation', 'Phân tích cấu trúc câu xác định chính xác vị trí danh từ, động từ, tính từ, trạng từ.', 'READING', 5, NOW(), NOW()),
(11, 'Verb Tenses & Voice Consistency', 'Chia 12 thì tiếng Anh, hòa hợp chủ ngữ - động từ, thể bị động và thức giả định.', 'READING', 5, NOW(), NOW()),
(12, 'Business Lexicon & Collocations', 'Vận dụng chuẩn xác từ vựng chuyên ngành công sở, hợp đồng và cụm từ cố định.', 'READING', 5, NOW(), NOW()),
(13, 'Contextual Sentence Insertion', 'Chiến thuật chọn câu văn hoàn chỉnh điền vào đoạn văn bảo đảm mạch logic toàn bài.', 'READING', 6, NOW(), NOW()),
(14, 'Transitions & Discourse Markers', 'Nhận diện từ nối chuyển tiếp (However, Otherwise, Moreover) và ngữ pháp trong đoạn văn.', 'READING', 6, NOW(), NOW()),
(15, 'Business Emails & Memos Reading', 'Kỹ năng skimming và scanning thư từ thương mại, thông báo nội bộ và hóa đơn.', 'READING', 7, NOW(), NOW()),
(16, 'Cross-referencing Multi-passages', 'Xâu chuỗi, đối chiếu thông tin chéo giữa văn bản đôi và văn bản ba (Email - Lịch - Hóa đơn).', 'READING', 7, NOW(), NOW());
