INSERT INTO modules (id, title, type, sequence, status, default_pass_score, required_completion_rate, descriptions, part_id, created_at, updated_at) VALUES
(1, 'Part 1: Chinh phục bẫy hành động con người', 'THEORY', 1, 'PUBLISHED', 70, 80, 'Nắm vững 50 động từ hành động hay xuất hiện nhất và kỹ thuật loại trừ bẫy thì trong tranh tả người.', 1, NOW(), NOW()),
(2, 'Part 1: Phân tích trạng thái đồ vật & bối cảnh tĩnh', 'PRACTICE', 2, 'PUBLISHED', 70, 80, 'Phân biệt chuẩn xác câu bị động trạng thái với bị động tiếp diễn trong các bức tranh không người.', 1, NOW(), NOW()),
(3, 'Part 2: Phản xạ thần tốc câu hỏi Wh-Questions', 'THEORY', 3, 'PUBLISHED', 70, 80, 'Chiến thuật bắt trọn 3 từ đầu tiên của câu hỏi Who, Where, When, Why, How và triệt tiêu bẫy đồng âm.', 2, NOW(), NOW()),
(4, 'Part 2: Xử lý câu hỏi Yes/No, câu hỏi đuôi & lựa chọn', 'PRACTICE', 4, 'PUBLISHED', 70, 80, 'Kỹ năng phân loại nhanh câu hỏi xác nhận và câu hỏi lựa chọn có liên từ OR.', 2, NOW(), NOW()),
(5, 'Part 2: Giải mã câu trả lời gián tiếp & bẫy né tránh', 'PRACTICE', 5, 'PUBLISHED', 75, 80, 'Chuyên sâu dạng câu hỏi khó nhất Part 2: phản hồi chuyển hướng, câu hỏi tu từ và ngụ ý thực tế.', 2, NOW(), NOW()),
(6, 'Part 3: Kỹ năng đọc trước câu hỏi & bắt Keyword chi tiết', 'THEORY', 6, 'PUBLISHED', 75, 80, 'Tận dụng 8 giây vàng giữa các hội thoại để khoanh vùng từ khóa thời gian, địa điểm và số liệu.', 3, NOW(), NOW()),
(7, 'Part 3: Suy luận mục đích, nghề nghiệp & ngụ ý người nói', 'PRACTICE', 7, 'PUBLISHED', 75, 80, 'Đọc vị hàm ý câu trích dẫn trong ngoặc kép và dự đoán hành động tiếp theo của nhân vật.', 3, NOW(), NOW()),
(8, 'Part 4: Nghe hiểu thông báo công cộng & hướng dẫn sự kiện', 'THEORY', 8, 'PUBLISHED', 75, 80, 'Làm chủ cấu trúc thông báo sân bay, siêu thị, hội thảo doanh nghiệp và hướng dẫn an toàn.', 4, NOW(), NOW()),
(9, 'Part 4: Nắm bắt tin nhắn hộp thư thoại & bản tin kinh doanh', 'PRACTICE', 9, 'PUBLISHED', 75, 80, 'Chiến thuật ghi nhận thông tin người gọi, yêu cầu hành động và số liệu trong bản tin radio.', 4, NOW(), NOW()),
(10, 'Part 5: Công thức nhìn đuôi đoán từ loại trong 5 giây', 'THEORY', 10, 'PUBLISHED', 75, 80, 'Hệ thống hóa hậu tố danh từ, tính từ, trạng từ và quy tắc cấu trúc cụm danh từ TOEIC.', 5, NOW(), NOW()),
(11, 'Part 5: Làm chủ 12 thì, bị động & thức giả định', 'THEORY', 11, 'PUBLISHED', 80, 80, 'Bản đồ tư duy 12 thì, hòa hợp chủ ngữ - động từ, đảo ngữ điều kiện và mệnh đề giả định.', 5, NOW(), NOW()),
(12, 'Part 5: Từ vựng công sở & Collocations ăn điểm tuyệt đối', 'PRACTICE', 12, 'PUBLISHED', 80, 80, 'Tổng hợp các cụm từ cố định kinh điển trong hợp đồng, hậu cần, tài chính và nhân sự.', 5, NOW(), NOW()),
(13, 'Part 6: Chiến thuật từ nối chuyển tiếp & ngữ pháp ngữ cảnh', 'THEORY', 13, 'PUBLISHED', 75, 80, 'Phân tích mạch liên kết đoạn văn bằng từ nối tương phản, nguyên nhân - kết quả và bổ sung.', 6, NOW(), NOW()),
(14, 'Part 6: Tư duy chọn câu hoàn chỉnh điền vào đoạn văn', 'PRACTICE', 14, 'PUBLISHED', 75, 80, 'Kỹ thuật kiểm tra câu trước - câu sau và đại từ thay thế để chọn đúng câu điền đoạn.', 6, NOW(), NOW()),
(15, 'Part 7: Skimming & Scanning Email, Thông báo và Hóa đơn', 'PRACTICE', 15, 'PUBLISHED', 80, 80, 'Phương pháp đọc quét siêu tốc các loại văn bản đơn thương mại, tin nhắn và đánh giá sản phẩm.', 7, NOW(), NOW()),
(16, 'Part 7: Xâu chuỗi thông tin chéo đoạn đôi & đoạn ba nâng cao', 'EXAM', 16, 'PUBLISHED', 80, 80, 'Chiến thuật đối chiếu chéo dữ liệu giữa lịch trình, email, biểu phí và đơn hàng trong đề thật.', 7, NOW(), NOW());
