INSERT INTO lesson_scripts (id, order_no, start_time, end_time, speaker, content_en, content_vi, lesson_id) VALUES
(1, 1, '00:00', '00:18', 'Giảng viên', 'Welcome to Chinh phục bẫy hành động con người. Today we will master the core strategy used by top TOEIC scorers.', 'Chào mừng các bạn đến với chuyên đề Chinh phục bẫy hành động con người. Hôm nay chúng ta sẽ nắm vững chiến thuật cốt lõi của người đạt điểm cao TOEIC.', 1),
(2, 2, '00:18', '00:42', 'Giảng viên', 'First, always identify the key signal words before eliminating distractors with similar sounds or wrong tenses.', 'Đầu tiên, luôn xác định từ khóa tín hiệu trước khi loại trừ các đáp án nhiễu đồng âm hoặc sai thì.', 1),
(3, 3, '00:42', '01:10', 'Giảng viên', 'Let us walk through two real ETS business examples together so you can apply this method under timed pressure.', 'Hãy cùng phân tích hai ví dụ kinh doanh chuẩn ETS để bạn áp dụng phương pháp này dưới áp lực thời gian.', 1),
(4, 1, '00:00', '00:20', 'Giảng viên', 'In this walkthrough, notice how ETS paraphrases key nouns from the audio or passage into synonyms in the correct choice.', 'Trong phần giải đề này, hãy chú ý cách ETS diễn đạt lại danh từ khóa trong bài thành từ đồng nghĩa ở đáp án đúng.', 2),
(5, 2, '00:20', '00:48', 'Giảng viên', 'Avoid selecting an option simply because it repeats an exact word you heard; verify the full meaning in context.', 'Tránh chọn một phương án chỉ vì nó lặp lại nguyên từ bạn nghe thấy; hãy đối chiếu trọn nghĩa trong ngữ cảnh.', 2),
(6, 1, '00:00', '00:05', 'Speaker A', 'Could you confirm the delivery schedule for the regional warehouse?', 'Bạn có thể xác nhận lịch giao hàng cho kho khu vực được không?', 3),
(7, 2, '00:05', '00:11', 'Speaker B', 'Yes, the supplier promised to ship all forty crates before Thursday noon.', 'Vâng, nhà cung cấp hứa sẽ chuyển đủ 40 kiện hàng trước trưa thứ Năm.', 3),
(8, 3, '00:11', '00:17', 'Speaker A', 'Great, please email the revised invoice to the accounting director today.', 'Tuyệt vời, vui lòng gửi email hóa đơn sửa đổi cho giám đốc kế toán trong hôm nay.', 3),
(9, 4, '00:17', '00:24', 'Speaker B', 'I will attach the signed approval addendum right after our team meeting.', 'Tôi sẽ đính kèm bản phụ lục đã ký duyệt ngay sau cuộc họp nhóm.', 3),
(10, 1, '00:00', '00:18', 'Giảng viên', 'Welcome to Phân tích trạng thái đồ vật & bối cảnh tĩnh. Today we will master the core strategy used by top TOEIC scorers.', 'Chào mừng các bạn đến với chuyên đề Phân tích trạng thái đồ vật & bối cảnh tĩnh. Hôm nay chúng ta sẽ nắm vững chiến thuật cốt lõi của người đạt điểm cao TOEIC.', 4),
(11, 2, '00:18', '00:42', 'Giảng viên', 'First, always identify the key signal words before eliminating distractors with similar sounds or wrong tenses.', 'Đầu tiên, luôn xác định từ khóa tín hiệu trước khi loại trừ các đáp án nhiễu đồng âm hoặc sai thì.', 4),
