INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(1, 'SINGLE_CHOICE', 'Part 1: Construction engineers inspecting architectural blueprints', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Some engineers are inspecting a building blueprint."},{"key":"B","text":"(B) The workers are climbing up a metal ladder."},{"key":"C","text":"(C) Tools are being packed into wooden crates."},{"key":"D","text":"(D) Concrete is being poured onto the sidewalk."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) Some engineers are inspecting a building blueprint.\\n(B) The workers are climbing up a metal ladder.\\n(C) Tools are being packed into wooden crates.\\n(D) Concrete is being poured onto the sidewalk.","translation":"Hai kỹ sư đội mũ bảo hộ đang cùng trải và kiểm tra bản vẽ thiết kế trên bàn.","clue":"Hai kỹ sư đội mũ bảo hộ đang cùng trải và kiểm tra bản vẽ thiết kế trên bàn.","analysis":"Động từ ''inspecting a building blueprint'' mô tả chính xác hành động đang diễn ra.","vocabulary":[{"word":"inspect","type":"v","meaning":"kiểm tra, giám định"},{"word":"blueprint","type":"n","meaning":"bản vẽ thiết kế"}]}', NULL, NOW(), NOW()),
(2, 'SINGLE_CHOICE', 'Part 1: Empty conference room with arranged chairs', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) A presentation is being delivered by a manager."},{"key":"B","text":"(B) Chairs are arranged neatly around a conference table."},{"key":"C","text":"(C) Documents are being handed out to attendees."},{"key":"D","text":"(D) The glass windows are currently being washed."}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) A presentation is being delivered by a manager.\\n(B) Chairs are arranged neatly around a conference table.\\n(C) Documents are being handed out to attendees.\\n(D) The glass windows are currently being washed.","translation":"Bức tranh chụp phòng họp tĩnh không có người, ghế xếp ngay ngắn quanh bàn dài.","clue":"Bức tranh chụp phòng họp tĩnh không có người, ghế xếp ngay ngắn quanh bàn dài.","analysis":"Tranh không người loại ngay các câu có bị động tiếp diễn ''is/are being + V3'' (A, C, D). Chọn (B) chỉ trạng thái.","vocabulary":[{"word":"arrange","type":"v","meaning":"sắp xếp ngăn nắp"},{"word":"conference table","type":"n","meaning":"bàn họp hội nghị"}]}', NULL, NOW(), NOW()),
(3, 'SINGLE_CHOICE', 'Part 1: Woman typing on a laptop at an office desk', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) She is adjusting the blinds near the window."},{"key":"B","text":"(B) She is typing on a laptop computer at her desk."},{"key":"C","text":"(C) She is carrying a stack of folders down the hall."},{"key":"D","text":"(D) She is unplugging a cable from the monitor."}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) She is adjusting the blinds near the window.\\n(B) She is typing on a laptop computer at her desk.\\n(C) She is carrying a stack of folders down the hall.\\n(D) She is unplugging a cable from the monitor.","translation":"Người phụ nữ đang ngồi tại bàn làm việc và gõ bàn phím máy tính xách tay.","clue":"Người phụ nữ đang ngồi tại bàn làm việc và gõ bàn phím máy tính xách tay.","analysis":"Hành động ''typing on a laptop computer'' khớp hoàn toàn với hình ảnh trực quan.","vocabulary":[{"word":"adjust","type":"v","meaning":"điều chỉnh"},{"word":"stack","type":"n","meaning":"chồng, xấp tài liệu"}]}', NULL, NOW(), NOW()),
(4, 'SINGLE_CHOICE', 'Part 1: Merchandise displayed on retail store shelves', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Customers are waiting in line at the register."},{"key":"B","text":"(B) A clerk is restocking the bottom shelf."},{"key":"C","text":"(C) Products are displayed in rows along the shelves."},{"key":"D","text":"(D) Boxes have been piled up in the doorway."}]}', '{"selected":"C","key":"C"}', 3, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) Customers are waiting in line at the register.\\n(B) A clerk is restocking the bottom shelf.\\n(C) Products are displayed in rows along the shelves.\\n(D) Boxes have been piled up in the doorway.","translation":"Kệ hàng trong cửa hàng trưng bày ngay ngắn sản phẩm theo từng hàng, không có nhân viên hay khách hàng.","clue":"Kệ hàng trong cửa hàng trưng bày ngay ngắn sản phẩm theo từng hàng, không có nhân viên hay khách hàng.","analysis":"Cấu trúc bị động trạng thái ''are displayed in rows'' mô tả đúng cảnh vật tĩnh.","vocabulary":[{"word":"merchandise","type":"n","meaning":"hàng hóa bày bán"},{"word":"restock","type":"v","meaning":"bổ sung hàng lên kệ"}]}', NULL, NOW(), NOW()),
(5, 'SINGLE_CHOICE', 'Part 1: Chef plating food in a commercial kitchen', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) A chef is placing food onto a serving dish."},{"key":"B","text":"(B) Waiters are clearing empty plates from tables."},{"key":"C","text":"(C) Dishes are stacked inside a drying rack."},{"key":"D","text":"(D) A customer is ordering from a printed menu."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) A chef is placing food onto a serving dish.\\n(B) Waiters are clearing empty plates from tables.\\n(C) Dishes are stacked inside a drying rack.\\n(D) A customer is ordering from a printed menu.","translation":"Đầu bếp mặc đồng phục trắng đang bày món ăn lên đĩa lớn trong bếp nhà hàng.","clue":"Đầu bếp mặc đồng phục trắng đang bày món ăn lên đĩa lớn trong bếp nhà hàng.","analysis":"''Placing food onto a serving dish'' diễn tả đúng thao tác trình bày món ăn.","vocabulary":[{"word":"serving dish","type":"n","meaning":"đĩa đựng món ăn"},{"word":"commercial kitchen","type":"n","meaning":"bếp công nghiệp"}]}', NULL, NOW(), NOW()),
(6, 'SINGLE_CHOICE', 'Part 1: Bicycles parked along a brick walkway', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Several pedestrians are crossing a stone bridge."},{"key":"B","text":"(B) Bicycles are lined up beside a brick building."},{"key":"C","text":"(C) A cyclist is repairing a flat tire on the curb."},{"key":"D","text":"(D) Trees are being trimmed along the boulevard."}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) Several pedestrians are crossing a stone bridge.\\n(B) Bicycles are lined up beside a brick building.\\n(C) A cyclist is repairing a flat tire on the curb.\\n(D) Trees are being trimmed along the boulevard.","translation":"Nhiều xe đạp dựng thành hàng dọc cạnh tường gạch của tòa nhà.","clue":"Nhiều xe đạp dựng thành hàng dọc cạnh tường gạch của tòa nhà.","analysis":"Cụm ''are lined up beside'' chỉ trạng thái xếp thành hàng của đồ vật.","vocabulary":[{"word":"line up","type":"phr v","meaning":"xếp thành hàng"},{"word":"pedestrian","type":"n","meaning":"người đi bộ"}]}', NULL, NOW(), NOW()),
(7, 'SINGLE_CHOICE', 'Part 1: Colleagues shaking hands in a bright lobby', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Two colleagues are exchanging business cards."},{"key":"B","text":"(B) Two professionals are shaking hands in a lobby."},{"key":"C","text":"(C) A receptionist is answering a telephone call."},{"key":"D","text":"(D) Visitors are signing in at the security desk."}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) Two colleagues are exchanging business cards.\\n(B) Two professionals are shaking hands in a lobby.\\n(C) A receptionist is answering a telephone call.\\n(D) Visitors are signing in at the security desk.","translation":"Hai đối tác kinh doanh đang bắt tay chào hỏi tại sảnh tòa nhà.","clue":"Hai đối tác kinh doanh đang bắt tay chào hỏi tại sảnh tòa nhà.","analysis":"Hành động ''shaking hands'' thể hiện trực tiếp cử chỉ trong bức ảnh.","vocabulary":[{"word":"lobby","type":"n","meaning":"sảnh đón tiếp"},{"word":"colleague","type":"n","meaning":"đồng nghiệp"}]}', NULL, NOW(), NOW()),
(8, 'SINGLE_CHOICE', 'Part 1: Outdoor patio dining area with umbrellas', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Diners are seated beneath large patio umbrellas."},{"key":"B","text":"(B) Tables and chairs have been set up outdoors."},{"key":"C","text":"(C) A server is wiping down the counter."},{"key":"D","text":"(D) Potted plants are hanging from the balcony."}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) Diners are seated beneath large patio umbrellas.\\n(B) Tables and chairs have been set up outdoors.\\n(C) A server is wiping down the counter.\\n(D) Potted plants are hanging from the balcony.","translation":"Khu vực ăn uống ngoài trời đã kê sẵn bàn ghế nhưng chưa có thực khách ngồi.","clue":"Khu vực ăn uống ngoài trời đã kê sẵn bàn ghế nhưng chưa có thực khách ngồi.","analysis":"Thì hiện tại hoàn thành bị động ''have been set up'' diễn tả trạng thái chuẩn bị sẵn sàng.","vocabulary":[{"word":"patio","type":"n","meaning":"sân hiên ngoài trời"},{"word":"set up","type":"phr v","meaning":"bố trí, sắp đặt"}]}', NULL, NOW(), NOW()),
(9, 'SINGLE_CHOICE', 'Part 1: Technician examining laboratory equipment', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) A technician is examining equipment at a workbench."},{"key":"B","text":"(B) Safety goggles are resting on a wooden stool."},{"key":"C","text":"(C) Glassware is being washed in a metal sink."},{"key":"D","text":"(D) Two scientists are writing notes on a whiteboard."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) A technician is examining equipment at a workbench.\\n(B) Safety goggles are resting on a wooden stool.\\n(C) Glassware is being washed in a metal sink.\\n(D) Two scientists are writing notes on a whiteboard.","translation":"Kỹ thuật viên đang kiểm tra thiết bị đo tại bàn thí nghiệm.","clue":"Kỹ thuật viên đang kiểm tra thiết bị đo tại bàn thí nghiệm.","analysis":"Động từ ''examining equipment'' diễn đạt chuẩn xác thao tác quan sát, kiểm định.","vocabulary":[{"word":"workbench","type":"n","meaning":"bàn thao tác kỹ thuật"},{"word":"examine","type":"v","meaning":"kiểm tra kỹ lưỡng"}]}', NULL, NOW(), NOW()),
(10, 'SINGLE_CHOICE', 'Part 1: Shipping containers stacked at a cargo port', NULL, '{"text":"Look at the photograph and choose the statement that best describes what you see.","imageUrl":"https://res.cloudinary.com/wgsdldlg/image/upload/v1795594885/leby/b3evj0ardtriy2t3g65b.jpg","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Trucks are being unloaded by warehouse workers."},{"key":"B","text":"(B) Shipping containers are stacked near the waterfront."},{"key":"C","text":"(C) A ferry is boarding passengers at the pier."},{"key":"D","text":"(D) Cranes are being disassembled on the dock."}]}', '{"selected":"B","key":"B"}', 4, 'LISTENING', 'Câu hỏi mô tả hình ảnh TOEIC Part 1.', 1, '{"transcript":"(A) Trucks are being unloaded by warehouse workers.\\n(B) Shipping containers are stacked near the waterfront.\\n(C) A ferry is boarding passengers at the pier.\\n(D) Cranes are being disassembled on the dock.","translation":"Các thùng container hàng hóa được xếp chồng cao gần bờ cảng biển.","clue":"Các thùng container hàng hóa được xếp chồng cao gần bờ cảng biển.","analysis":"Loại trừ ngay các câu có ''being + V3'' vì không có hành động người đang diễn ra.","vocabulary":[{"word":"waterfront","type":"n","meaning":"khu vực ven bờ cảng"},{"word":"cargo","type":"n","meaning":"hàng hóa vận chuyển"}]}', NULL, NOW(), NOW()),
(11, 'SINGLE_CHOICE', 'Part 2: Where is the annual shareholder meeting?', NULL, '{"text":"Where will the annual shareholder meeting be held this year?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) At the Grand Plaza Hotel in Chicago."},{"key":"B","text":"(B) Yes, it was very informative."},{"key":"C","text":"(C) Next Thursday at 9:00 A.M."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Where will the annual shareholder meeting be held this year?\\n(A) At the Grand Plaza Hotel in Chicago.\\n(B) Yes, it was very informative.\\n(C) Next Thursday at 9:00 A.M.","translation":"Từ để hỏi ''Where'' yêu cầu địa điểm cụ thể.","clue":"Từ để hỏi ''Where'' yêu cầu địa điểm cụ thể.","analysis":"Chọn (A) chỉ khách sạn. Loại (B) Yes/No và (C) thời gian.","vocabulary":[]}', NULL, NOW(), NOW()),
(12, 'SINGLE_CHOICE', 'Part 2: Who approved the proposed marketing budget?', NULL, '{"text":"Who approved the proposed budget increase for marketing?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) About fifteen percent more than last quarter."},{"key":"B","text":"(B) Ms. Davis signed off on it yesterday."},{"key":"C","text":"(C) To attract more international clients."}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Who approved the proposed budget increase for marketing?\\n(A) About fifteen percent more than last quarter.\\n(B) Ms. Davis signed off on it yesterday.\\n(C) To attract more international clients.","translation":"Từ để hỏi ''Who'' hỏi người phê duyệt.","clue":"Từ để hỏi ''Who'' hỏi người phê duyệt.","analysis":"(B) nêu rõ tên người ký duyệt ''Ms. Davis''.","vocabulary":[]}', NULL, NOW(), NOW()),
(13, 'SINGLE_CHOICE', 'Part 2: When does the software training session start?', NULL, '{"text":"When does the mandatory software training session begin?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) In Training Room 3B on the second floor."},{"key":"B","text":"(B) Right after the noon lunch break."},{"key":"C","text":"(C) Mr. Patel will lead the workshop."}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"When does the mandatory software training session begin?\\n(A) In Training Room 3B on the second floor.\\n(B) Right after the noon lunch break.\\n(C) Mr. Patel will lead the workshop.","translation":"Từ để hỏi ''When'' yêu cầu mốc thời gian.","clue":"Từ để hỏi ''When'' yêu cầu mốc thời gian.","analysis":"(B) ''Right after the noon lunch break'' trả lời trực tiếp thời điểm.","vocabulary":[]}', NULL, NOW(), NOW()),
(14, 'SINGLE_CHOICE', 'Part 2: Why was the shipment delayed at customs?', NULL, '{"text":"Why was the electronics shipment delayed at customs?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Because one of the export invoices was missing."},{"key":"B","text":"(B) It arrived at the warehouse on Friday."},{"key":"C","text":"(C) Yes, the shipping fee was refunded."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Why was the electronics shipment delayed at customs?\\n(A) Because one of the export invoices was missing.\\n(B) It arrived at the warehouse on Friday.\\n(C) Yes, the shipping fee was refunded.","translation":"Từ để hỏi ''Why'' cần lý do (''Because...'').","clue":"Từ để hỏi ''Why'' cần lý do (''Because...'').","analysis":"(A) giải thích nguyên nhân thiếu hóa đơn xuất khẩu.","vocabulary":[]}', NULL, NOW(), NOW()),
(15, 'SINGLE_CHOICE', 'Part 2: How long will the server maintenance take?', NULL, '{"text":"How long is the scheduled server maintenance expected to take?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Approximately two and a half hours."},{"key":"B","text":"(B) The IT department handles all upgrades."},{"key":"C","text":"(C) About five kilometers from downtown."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"How long is the scheduled server maintenance expected to take?\\n(A) Approximately two and a half hours.\\n(B) The IT department handles all upgrades.\\n(C) About five kilometers from downtown.","translation":"''How long'' hỏi khoảng thời gian kéo dài.","clue":"''How long'' hỏi khoảng thời gian kéo dài.","analysis":"(A) nêu rõ khoảng 2,5 tiếng. Loại (C) hỏi khoảng cách.","vocabulary":[]}', NULL, NOW(), NOW()),
(16, 'SINGLE_CHOICE', 'Part 2: How often do we audit inventory records?', NULL, '{"text":"How often does the operations team audit the inventory records?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Once at the end of every fiscal quarter."},{"key":"B","text":"(B) All items are stored on aisle four."},{"key":"C","text":"(C) The report was emailed to accounting."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"How often does the operations team audit the inventory records?\\n(A) Once at the end of every fiscal quarter.\\n(B) All items are stored on aisle four.\\n(C) The report was emailed to accounting.","translation":"''How often'' hỏi tần suất thực hiện.","clue":"''How often'' hỏi tần suất thực hiện.","analysis":"(A) ''Once at the end of every fiscal quarter'' chỉ rõ tần suất mỗi quý.","vocabulary":[]}', NULL, NOW(), NOW()),
(17, 'SINGLE_CHOICE', 'Part 2: Which supplier offered the lowest quotation?', NULL, '{"text":"Which packaging supplier offered the most competitive quotation?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Apex Containers beat the others by twelve percent."},{"key":"B","text":"(B) They deliver every Monday morning."},{"key":"C","text":"(C) Around five hundred cardboard boxes."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Which packaging supplier offered the most competitive quotation?\\n(A) Apex Containers beat the others by twelve percent.\\n(B) They deliver every Monday morning.\\n(C) Around five hundred cardboard boxes.","translation":"''Which supplier'' hỏi tên nhà cung cấp cụ thể.","clue":"''Which supplier'' hỏi tên nhà cung cấp cụ thể.","analysis":"(A) nêu trực tiếp tên Apex Containers.","vocabulary":[]}', NULL, NOW(), NOW()),
(18, 'SINGLE_CHOICE', 'Part 2: What time does the shuttle leave for the airport?', NULL, '{"text":"What time does the hotel shuttle depart for the airport?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Every thirty minutes on the hour and half-hour."},{"key":"B","text":"(B) Terminal Two for international flights."},{"key":"C","text":"(C) The driver helped with my luggage."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"What time does the hotel shuttle depart for the airport?\\n(A) Every thirty minutes on the hour and half-hour.\\n(B) Terminal Two for international flights.\\n(C) The driver helped with my luggage.","translation":"''What time'' hỏi lịch giờ khởi hành.","clue":"''What time'' hỏi lịch giờ khởi hành.","analysis":"(A) nêu lịch chạy định kỳ mỗi 30 phút.","vocabulary":[]}', NULL, NOW(), NOW()),
(19, 'SINGLE_CHOICE', 'Part 2: Where should I submit my travel expense receipts?', NULL, '{"text":"Where should I submit my travel expense receipts?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Upload scans directly through the finance portal."},{"key":"B","text":"(B) The flight ticket cost four hundred dollars."},{"key":"C","text":"(C) Before the end of next week."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Where should I submit my travel expense receipts?\\n(A) Upload scans directly through the finance portal.\\n(B) The flight ticket cost four hundred dollars.\\n(C) Before the end of next week.","translation":"''Where'' hỏi nơi/kênh nộp chứng từ.","clue":"''Where'' hỏi nơi/kênh nộp chứng từ.","analysis":"(A) chỉ dẫn nộp trực tiếp lên cổng tài chính.","vocabulary":[]}', NULL, NOW(), NOW()),
(20, 'SINGLE_CHOICE', 'Part 2: Who is responsible for onboarding new hires?', NULL, '{"text":"Who is responsible for onboarding the new engineering hires?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Human Resources coordinates the orientation."},{"key":"B","text":"(B) Twelve applicants were interviewed."},{"key":"C","text":"(C) Starting on the first of September."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Who is responsible for onboarding the new engineering hires?\\n(A) Human Resources coordinates the orientation.\\n(B) Twelve applicants were interviewed.\\n(C) Starting on the first of September.","translation":"''Who'' có thể trả lời bằng tên phòng ban phụ trách.","clue":"''Who'' có thể trả lời bằng tên phòng ban phụ trách.","analysis":"(A) ''Human Resources'' là đáp án chuẩn TOEIC cho câu hỏi Who.","vocabulary":[]}', NULL, NOW(), NOW()),
(21, 'SINGLE_CHOICE', 'Part 2: Yes/No - Did you confirm the catering order?', NULL, '{"text":"Did you confirm the catering order for tomorrow''s seminar?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Yes, they will deliver lunch at 11:30 A.M."},{"key":"B","text":"(B) In the main auditorium."},{"key":"C","text":"(C) About forty-five participants."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Did you confirm the catering order for tomorrow''s seminar?\\n(A) Yes, they will deliver lunch at 11:30 A.M.\\n(B) In the main auditorium.\\n(C) About forty-five participants.","translation":"Câu hỏi Yes/No với trợ động từ ''Did''.","clue":"Câu hỏi Yes/No với trợ động từ ''Did''.","analysis":"(A) xác nhận trực tiếp ''Yes'' kèm giờ giao ăn.","vocabulary":[]}', NULL, NOW(), NOW()),
(22, 'SINGLE_CHOICE', 'Part 2: Yes/No - Have the brochures been printed yet?', NULL, '{"text":"Have the promotional brochures been printed yet?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) The print shop just delivered them this morning."},{"key":"B","text":"(B) For the autumn trade exhibition."},{"key":"C","text":"(C) On glossy recycled paper."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Have the promotional brochures been printed yet?\\n(A) The print shop just delivered them this morning.\\n(B) For the autumn trade exhibition.\\n(C) On glossy recycled paper.","translation":"Câu hỏi xác nhận trạng thái hoàn thành.","clue":"Câu hỏi xác nhận trạng thái hoàn thành.","analysis":"(A) xác nhận tiệm in vừa giao sáng nay (không cần từ Yes/No vẫn đúng nghĩa).","vocabulary":[]}', NULL, NOW(), NOW()),
(23, 'SINGLE_CHOICE', 'Part 2: Choice - Would you prefer morning or afternoon shift?', NULL, '{"text":"Would you prefer to schedule the client call in the morning or the afternoon?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) The afternoon works much better for my schedule."},{"key":"B","text":"(B) Yes, I spoke with the client yesterday."},{"key":"C","text":"(C) Using the video conferencing link."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Would you prefer to schedule the client call in the morning or the afternoon?\\n(A) The afternoon works much better for my schedule.\\n(B) Yes, I spoke with the client yesterday.\\n(C) Using the video conferencing link.","translation":"Câu hỏi lựa chọn có ''or'' KHÔNG trả lời Yes/No.","clue":"Câu hỏi lựa chọn có ''or'' KHÔNG trả lời Yes/No.","analysis":"(A) chọn rõ phương án ''The afternoon''.","vocabulary":[]}', NULL, NOW(), NOW()),
(24, 'SINGLE_CHOICE', 'Part 2: Choice - Should we rent a booth or sponsor the keynote?', NULL, '{"text":"Should we rent an exhibition booth or sponsor the keynote speech?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Sponsoring the keynote gives us far more visibility."},{"key":"B","text":"(B) Yes, the conference is in October."},{"key":"C","text":"(C) Three marketing specialists will attend."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Should we rent an exhibition booth or sponsor the keynote speech?\\n(A) Sponsoring the keynote gives us far more visibility.\\n(B) Yes, the conference is in October.\\n(C) Three marketing specialists will attend.","translation":"Câu hỏi lựa chọn giữa 2 phương án marketing.","clue":"Câu hỏi lựa chọn giữa 2 phương án marketing.","analysis":"(A) chọn phương án 2 kèm lý do tăng độ nhận diện.","vocabulary":[]}', NULL, NOW(), NOW()),
(25, 'SINGLE_CHOICE', 'Part 2: Tag Question - The quarterly report is ready, isn''t it?', NULL, '{"text":"The quarterly sales report is ready for review, isn''t it?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Almost—I just need to verify the regional totals."},{"key":"B","text":"(B) Sales increased by nine percent."},{"key":"C","text":"(C) At the regional branch office."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"The quarterly sales report is ready for review, isn''t it?\\n(A) Almost—I just need to verify the regional totals.\\n(B) Sales increased by nine percent.\\n(C) At the regional branch office.","translation":"Câu hỏi đuôi ''isn''t it?'' yêu cầu xác nhận tình trạng.","clue":"Câu hỏi đuôi ''isn''t it?'' yêu cầu xác nhận tình trạng.","analysis":"(A) ''Almost...'' xác nhận sắp xong, chỉ cần kiểm tra nốt số liệu.","vocabulary":[]}', NULL, NOW(), NOW()),
(26, 'SINGLE_CHOICE', 'Part 2: Yes/No - Can you cover the reception desk at two?', NULL, '{"text":"Can you cover the reception desk while I step out at two o''clock?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Sure, I don''t have any meetings until three."},{"key":"B","text":"(B) The desk was delivered last Tuesday."},{"key":"C","text":"(C) Please sign the visitor badge."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Can you cover the reception desk while I step out at two o''clock?\\n(A) Sure, I don''t have any meetings until three.\\n(B) The desk was delivered last Tuesday.\\n(C) Please sign the visitor badge.","translation":"Câu đề nghị lịch sự ''Can you...?'' cần đồng ý hoặc từ chối.","clue":"Câu đề nghị lịch sự ''Can you...?'' cần đồng ý hoặc từ chối.","analysis":"(A) nhận lời vì rảnh đến 3 giờ.","vocabulary":[]}', NULL, NOW(), NOW()),
(27, 'SINGLE_CHOICE', 'Part 2: Choice - Will you pay by corporate card or bank transfer?', NULL, '{"text":"Will the company settle this invoice by corporate card or bank transfer?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Accounting always processes vendor bills by bank transfer."},{"key":"B","text":"(B) Yes, the invoice number is correct."},{"key":"C","text":"(C) Within thirty business days."}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Will the company settle this invoice by corporate card or bank transfer?\\n(A) Accounting always processes vendor bills by bank transfer.\\n(B) Yes, the invoice number is correct.\\n(C) Within thirty business days.","translation":"Câu hỏi lựa chọn phương thức thanh toán.","clue":"Câu hỏi lựa chọn phương thức thanh toán.","analysis":"(A) chọn rõ ''bank transfer''.","vocabulary":[]}', NULL, NOW(), NOW()),
(28, 'SINGLE_CHOICE', 'Part 2: Yes/No - Is the projector in Room 4 working properly?', NULL, '{"text":"Is the projector in Conference Room 4 working properly now?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) No, the technician is still replacing the bulb."},{"key":"B","text":"(B) The project deadline was extended."},{"key":"C","text":"(C) Room 4 seats twenty people."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Is the projector in Conference Room 4 working properly now?\\n(A) No, the technician is still replacing the bulb.\\n(B) The project deadline was extended.\\n(C) Room 4 seats twenty people.","translation":"Cẩn thận bẫy đồng âm ''projector'' vs ''project''.","clue":"Cẩn thận bẫy đồng âm ''projector'' vs ''project''.","analysis":"(A) trả lời trực tiếp ''No'' và nêu rõ đang thay bóng đèn.","vocabulary":[]}', NULL, NOW(), NOW()),
(29, 'SINGLE_CHOICE', 'Part 2: Tag Question - You''ve already booked the hotel, haven''t you?', NULL, '{"text":"You''ve already booked the hotel rooms for the delegation, haven''t you?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Yes, I forwarded the confirmation codes to your email."},{"key":"B","text":"(B) The delegation arrives from Seoul."},{"key":"C","text":"(C) For three consecutive nights."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"You''ve already booked the hotel rooms for the delegation, haven''t you?\\n(A) Yes, I forwarded the confirmation codes to your email.\\n(B) The delegation arrives from Seoul.\\n(C) For three consecutive nights.","translation":"Câu hỏi đuôi xác nhận việc đặt phòng.","clue":"Câu hỏi đuôi xác nhận việc đặt phòng.","analysis":"(A) xác nhận đã đặt và gửi mã xác nhận qua email.","vocabulary":[]}', NULL, NOW(), NOW()),
(30, 'SINGLE_CHOICE', 'Part 2: Indirect - Aren''t we getting a new photocopier soon?', NULL, '{"text":"Aren''t we getting a replacement for the broken photocopier soon?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) The procurement team is still waiting for vendor quotes."},{"key":"B","text":"(B) Make fifty double-sided copies, please."},{"key":"C","text":"(C) Yes, the photo looks very sharp."}]}', '{"selected":"A","key":"A"}', 4, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Aren''t we getting a replacement for the broken photocopier soon?\\n(A) The procurement team is still waiting for vendor quotes.\\n(B) Make fifty double-sided copies, please.\\n(C) Yes, the photo looks very sharp.","translation":"Câu trả lời gián tiếp không dùng Yes/No trực tiếp.","clue":"Câu trả lời gián tiếp không dùng Yes/No trực tiếp.","analysis":"(A) ngụ ý chưa có ngay vì phòng thu mua đang chờ báo giá. Loại bẫy đồng âm ''photo''/''copies''.","vocabulary":[]}', NULL, NOW(), NOW()),
(31, 'SINGLE_CHOICE', 'Part 2: Indirect - Why is the lobby so crowded today?', NULL, '{"text":"Why is the main lobby unusually crowded this morning?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Didn''t you hear we''re hosting the career fair today?"},{"key":"B","text":"(B) The elevator stops on every floor."},{"key":"C","text":"(C) Yes, it''s a very spacious building."}]}', '{"selected":"A","key":"A"}', 4, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Why is the main lobby unusually crowded this morning?\\n(A) Didn''t you hear we''re hosting the career fair today?\\n(B) The elevator stops on every floor.\\n(C) Yes, it''s a very spacious building.","translation":"Dùng câu hỏi tu từ để trả lời gián tiếp cho câu hỏi Why.","clue":"Dùng câu hỏi tu từ để trả lời gián tiếp cho câu hỏi Why.","analysis":"(A) nhắc người nghe hôm nay công ty tổ chức ngày hội việc làm.","vocabulary":[]}', NULL, NOW(), NOW()),
(32, 'SINGLE_CHOICE', 'Part 2: Indirect - Do you know where the warranty card is?', NULL, '{"text":"Do you know where the warranty card for the new scanner is kept?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) You should ask Elena—she unpacked the equipment."},{"key":"B","text":"(B) It scans forty pages per minute."},{"key":"C","text":"(C) A two-year manufacturer guarantee."}]}', '{"selected":"A","key":"A"}', 4, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Do you know where the warranty card for the new scanner is kept?\\n(A) You should ask Elena—she unpacked the equipment.\\n(B) It scans forty pages per minute.\\n(C) A two-year manufacturer guarantee.","translation":"Câu trả lời chuyển hướng sang người biết thông tin.","clue":"Câu trả lời chuyển hướng sang người biết thông tin.","analysis":"(A) ''You should ask Elena'' là dạng phản hồi gián tiếp kinh điển Part 2.","vocabulary":[]}', NULL, NOW(), NOW()),
(33, 'SINGLE_CHOICE', 'Part 2: Indirect - Should I order more toner cartridges?', NULL, '{"text":"Should I order more printer toner cartridges this afternoon?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Check the supply closet on the third floor first."},{"key":"B","text":"(B) The report needs to be printed in color."},{"key":"C","text":"(C) Yesterday''s order arrived undamaged."}]}', '{"selected":"A","key":"A"}', 4, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Should I order more printer toner cartridges this afternoon?\\n(A) Check the supply closet on the third floor first.\\n(B) The report needs to be printed in color.\\n(C) Yesterday''s order arrived undamaged.","translation":"Câu trả lời đưa ra hành động kiểm tra trước khi quyết định.","clue":"Câu trả lời đưa ra hành động kiểm tra trước khi quyết định.","analysis":"(A) khuyên kiểm tra tủ vật tư tầng 3 trước xem còn hàng không.","vocabulary":[]}', NULL, NOW(), NOW()),
(34, 'SINGLE_CHOICE', 'Part 2: Indirect - Would you mind reviewing my slide deck?', NULL, '{"text":"Would you mind reviewing my presentation slides before the board meeting?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) Send them over and I''ll look at them right after lunch."},{"key":"B","text":"(B) The boardroom has been reserved."},{"key":"C","text":"(C) Yes, the presentation was inspiring."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Would you mind reviewing my presentation slides before the board meeting?\\n(A) Send them over and I''ll look at them right after lunch.\\n(B) The boardroom has been reserved.\\n(C) Yes, the presentation was inspiring.","translation":"Câu nhờ vả ''Would you mind...'' nhận lời bằng hành động cụ thể.","clue":"Câu nhờ vả ''Would you mind...'' nhận lời bằng hành động cụ thể.","analysis":"(A) đồng ý xem sau giờ ăn trưa.","vocabulary":[]}', NULL, NOW(), NOW()),
(35, 'SINGLE_CHOICE', 'Part 2: Indirect - Isn''t the warehouse tour starting at ten?', NULL, '{"text":"Isn''t the safety tour of the warehouse supposed to start at ten?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) The operations manager sent out a revised itinerary."},{"key":"B","text":"(B) Hard hats are required inside."},{"key":"C","text":"(C) About ten employees signed up."}]}', '{"selected":"A","key":"A"}', 4, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Isn''t the safety tour of the warehouse supposed to start at ten?\\n(A) The operations manager sent out a revised itinerary.\\n(B) Hard hats are required inside.\\n(C) About ten employees signed up.","translation":"Phản hồi gián tiếp báo hiệu giờ đã thay đổi.","clue":"Phản hồi gián tiếp báo hiệu giờ đã thay đổi.","analysis":"(A) ám chỉ lịch trình đã được cập nhật lại, không còn là 10 giờ nữa.","vocabulary":[]}', NULL, NOW(), NOW()),
(36, 'SINGLE_CHOICE', 'Part 2: Indirect - How did the product demo go yesterday?', NULL, '{"text":"How did the live product demonstration go with the retail buyers?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) They already requested a formal contract draft."},{"key":"B","text":"(B) We took the express train downtown."},{"key":"C","text":"(C) The demo unit weighs two kilograms."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"How did the live product demonstration go with the retail buyers?\\n(A) They already requested a formal contract draft.\\n(B) We took the express train downtown.\\n(C) The demo unit weighs two kilograms.","translation":"Đánh giá kết quả gián tiếp qua dấu hiệu tích cực.","clue":"Đánh giá kết quả gián tiếp qua dấu hiệu tích cực.","analysis":"(A) khách hàng đã yêu cầu bản thảo hợp đồng -> buổi demo cực kỳ thành công.","vocabulary":[]}', NULL, NOW(), NOW()),
(37, 'SINGLE_CHOICE', 'Part 2: Indirect - Can we finish the redesign before Friday?', NULL, '{"text":"Do you think we can finish the website redesign before Friday?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) We''re still waiting on final brand assets from the client."},{"key":"B","text":"(B) The website receives thousands of visits."},{"key":"C","text":"(C) On Friday afternoon at four."}]}', '{"selected":"A","key":"A"}', 4, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Do you think we can finish the website redesign before Friday?\\n(A) We''re still waiting on final brand assets from the client.\\n(B) The website receives thousands of visits.\\n(C) On Friday afternoon at four.","translation":"Từ chối/bày tỏ sự không chắc chắn một cách gián tiếp.","clue":"Từ chối/bày tỏ sự không chắc chắn một cách gián tiếp.","analysis":"(A) nêu lý do đang chờ tài nguyên từ khách hàng -> khó kịp trước thứ Sáu.","vocabulary":[]}', NULL, NOW(), NOW()),
(38, 'SINGLE_CHOICE', 'Part 2: Indirect - Where can I find the updated employee handbook?', NULL, '{"text":"Where can I find the updated employee benefits handbook?","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","options":[{"key":"A","text":"(A) HR posted a direct link on the company intranet."},{"key":"B","text":"(B) Health coverage starts after ninety days."},{"key":"C","text":"(C) I read it twice last month."}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi Hỏi - Đáp TOEIC Part 2.', 2, '{"transcript":"Where can I find the updated employee benefits handbook?\\n(A) HR posted a direct link on the company intranet.\\n(B) Health coverage starts after ninety days.\\n(C) I read it twice last month.","translation":"Chỉ dẫn nguồn tài liệu gián tiếp qua cổng nội bộ.","clue":"Chỉ dẫn nguồn tài liệu gián tiếp qua cổng nội bộ.","analysis":"(A) nêu rõ phòng nhân sự đã đăng link trên mạng nội bộ.","vocabulary":[]}', NULL, NOW(), NOW()),
(39, 'SINGLE_CHOICE', 'Part 3 Conv 1: HR interview and Singapore branch start date', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 1: HR interview and Singapore branch start date).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 1.', 3, '{"transcript":"W: Good morning, Mr. Campbell. Thank you for coming in for the final interview for our Senior Financial Analyst role.\\nM: Thank you, Ms. Lee. I have followed your sustainable investment initiatives for years.\\nW: The board already approved the offer. Could you start at our Singapore branch by the beginning of next month?\\nM: That works well. My current contract ends in two weeks, leaving enough time to relocate.","translation":"Nữ: Chào anh Campbell, cảm ơn anh đến phỏng vấn vòng cuối vị trí Chuyên viên phân tích tài chính cao cấp. Hội đồng đã duyệt đề nghị, anh có thể bắt đầu tại chi nhánh Singapore đầu tháng tới không?\\nNam: Hoàn toàn được, hợp đồng hiện tại của tôi kết thúc sau 2 tuần nữa nên đủ thời gian chuyển chỗ ở.","analysis":"Nữ: Chào anh Campbell, cảm ơn anh đến phỏng vấn vòng cuối vị trí Chuyên viên phân tích tài chính cao cấp. Hội đồng đã duyệt đề nghị, anh có thể bắt đầu tại chi nhánh Singapore đầu tháng tới không?\\nNam: Hoàn toàn được, hợp đồng hiện tại của tôi kết thúc sau 2 tuần nữa nên đủ thời gian chuyển chỗ ở.","vocabulary":[]}', NULL, NOW(), NOW()),
(40, 'SINGLE_CHOICE', 'Part 3 G1 Q1: What position is the man interviewing for?', 1, '{"text":"What position is the man interviewing for?","options":[{"key":"A","text":"(A) Sustainable Energy Consultant"},{"key":"B","text":"(B) Senior Financial Analyst"},{"key":"C","text":"(C) Human Resources Director"},{"key":"D","text":"(D) Regional Branch Manager"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 1: HR interview and Singapore branch start date.', 3, '{"clue":"Người phụ nữ nói: ''interview for our Senior Financial Analyst role''.","analysis":"Người phụ nữ nói: ''interview for our Senior Financial Analyst role''.","transcript":"W: Good morning, Mr. Campbell. Thank you for coming in for the final interview for our Senior Financial Analyst role.\\nM: Thank you, Ms. Lee. I have followed your sustainable investment initiatives for years.\\nW: The board already approved the offer. Could you start at our Singapore branch by the beginning of next month?\\nM: That works well. My current contract ends in two weeks, leaving enough time to relocate.","translation":"Nữ: Chào anh Campbell, cảm ơn anh đến phỏng vấn vòng cuối vị trí Chuyên viên phân tích tài chính cao cấp. Hội đồng đã duyệt đề nghị, anh có thể bắt đầu tại chi nhánh Singapore đầu tháng tới không?\\nNam: Hoàn toàn được, hợp đồng hiện tại của tôi kết thúc sau 2 tuần nữa nên đủ thời gian chuyển chỗ ở.","vocabulary":[]}', 39, NOW(), NOW());
INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(41, 'SINGLE_CHOICE', 'Part 3 G1 Q2: Where will the man be based?', 2, '{"text":"Where will the man be based?","options":[{"key":"A","text":"(A) In Tokyo"},{"key":"B","text":"(B) In Singapore"},{"key":"C","text":"(C) In Chicago"},{"key":"D","text":"(D) In London"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 1: HR interview and Singapore branch start date.', 3, '{"clue":"Chi nhánh được đề cập trực tiếp là ''Singapore branch''.","analysis":"Chi nhánh được đề cập trực tiếp là ''Singapore branch''.","transcript":"W: Good morning, Mr. Campbell. Thank you for coming in for the final interview for our Senior Financial Analyst role.\\nM: Thank you, Ms. Lee. I have followed your sustainable investment initiatives for years.\\nW: The board already approved the offer. Could you start at our Singapore branch by the beginning of next month?\\nM: That works well. My current contract ends in two weeks, leaving enough time to relocate.","translation":"Nữ: Chào anh Campbell, cảm ơn anh đến phỏng vấn vòng cuối vị trí Chuyên viên phân tích tài chính cao cấp. Hội đồng đã duyệt đề nghị, anh có thể bắt đầu tại chi nhánh Singapore đầu tháng tới không?\\nNam: Hoàn toàn được, hợp đồng hiện tại của tôi kết thúc sau 2 tuần nữa nên đủ thời gian chuyển chỗ ở.","vocabulary":[]}', 39, NOW(), NOW()),
(42, 'SINGLE_CHOICE', 'Part 3 G1 Q3: When is the man expected to begin working?', 3, '{"text":"When is the man expected to begin working?","options":[{"key":"A","text":"(A) Tomorrow morning"},{"key":"B","text":"(B) In two weeks"},{"key":"C","text":"(C) At the beginning of next month"},{"key":"D","text":"(D) Next year"}]}', '{"selected":"C","key":"C"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 1: HR interview and Singapore branch start date.', 3, '{"clue":"Bẫy 2 tuần chỉ là hạn hết hợp đồng cũ; ngày bắt đầu là đầu tháng tới.","analysis":"Bẫy 2 tuần chỉ là hạn hết hợp đồng cũ; ngày bắt đầu là đầu tháng tới.","transcript":"W: Good morning, Mr. Campbell. Thank you for coming in for the final interview for our Senior Financial Analyst role.\\nM: Thank you, Ms. Lee. I have followed your sustainable investment initiatives for years.\\nW: The board already approved the offer. Could you start at our Singapore branch by the beginning of next month?\\nM: That works well. My current contract ends in two weeks, leaving enough time to relocate.","translation":"Nữ: Chào anh Campbell, cảm ơn anh đến phỏng vấn vòng cuối vị trí Chuyên viên phân tích tài chính cao cấp. Hội đồng đã duyệt đề nghị, anh có thể bắt đầu tại chi nhánh Singapore đầu tháng tới không?\\nNam: Hoàn toàn được, hợp đồng hiện tại của tôi kết thúc sau 2 tuần nữa nên đủ thời gian chuyển chỗ ở.","vocabulary":[]}', 39, NOW(), NOW()),
(43, 'SINGLE_CHOICE', 'Part 3 Conv 2: Rescheduling a hotel conference room booking', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 2: Rescheduling a hotel conference room booking).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 2.', 3, '{"transcript":"M: Hello, this is David Chen from Orion Tech. We booked the Cypress Ballroom for Thursday, but our keynote speaker''s flight was postponed.\\nW: I see your reservation, Mr. Chen. Would you like to move it to Friday instead?\\nM: Yes, if you still have a room for eighty guests with dual projectors.\\nW: The Cypress Ballroom is booked Friday, but the Harbor Suite is available and includes two projectors at no extra charge.","translation":"Nam: Tôi là David Chen từ Orion Tech. Chúng tôi đặt phòng Cypress cho thứ Năm nhưng chuyến bay của diễn giả bị hoãn.\\nNữ: Phòng Cypress đã kín thứ Sáu nhưng phòng Harbor Suite còn trống cho 80 khách và có sẵn 2 máy chiếu không tính thêm phí.","analysis":"Nam: Tôi là David Chen từ Orion Tech. Chúng tôi đặt phòng Cypress cho thứ Năm nhưng chuyến bay của diễn giả bị hoãn.\\nNữ: Phòng Cypress đã kín thứ Sáu nhưng phòng Harbor Suite còn trống cho 80 khách và có sẵn 2 máy chiếu không tính thêm phí.","vocabulary":[]}', NULL, NOW(), NOW()),
(44, 'SINGLE_CHOICE', 'Part 3 G2 Q1: Why is the man calling the hotel?', 1, '{"text":"Why is the man calling the hotel?","options":[{"key":"A","text":"(A) To cancel a catering menu"},{"key":"B","text":"(B) To reschedule a room reservation"},{"key":"C","text":"(C) To complain about a projector"},{"key":"D","text":"(D) To book airport transport"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 2: Rescheduling a hotel conference room booking.', 3, '{"clue":"Anh gọi để đổi lịch phòng họp từ thứ Năm sang thứ Sáu do diễn giả bị hoãn chuyến bay.","analysis":"Anh gọi để đổi lịch phòng họp từ thứ Năm sang thứ Sáu do diễn giả bị hoãn chuyến bay.","transcript":"M: Hello, this is David Chen from Orion Tech. We booked the Cypress Ballroom for Thursday, but our keynote speaker''s flight was postponed.\\nW: I see your reservation, Mr. Chen. Would you like to move it to Friday instead?\\nM: Yes, if you still have a room for eighty guests with dual projectors.\\nW: The Cypress Ballroom is booked Friday, but the Harbor Suite is available and includes two projectors at no extra charge.","translation":"Nam: Tôi là David Chen từ Orion Tech. Chúng tôi đặt phòng Cypress cho thứ Năm nhưng chuyến bay của diễn giả bị hoãn.\\nNữ: Phòng Cypress đã kín thứ Sáu nhưng phòng Harbor Suite còn trống cho 80 khách và có sẵn 2 máy chiếu không tính thêm phí.","vocabulary":[]}', 43, NOW(), NOW()),
(45, 'SINGLE_CHOICE', 'Part 3 G2 Q2: How many attendees are expected at the event?', 2, '{"text":"How many attendees are expected at the event?","options":[{"key":"A","text":"(A) Forty"},{"key":"B","text":"(B) Sixty"},{"key":"C","text":"(C) Eighty"},{"key":"D","text":"(D) One hundred"}]}', '{"selected":"C","key":"C"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 2: Rescheduling a hotel conference room booking.', 3, '{"clue":"Người đàn ông yêu cầu phòng đủ cho ''eighty guests''.","analysis":"Người đàn ông yêu cầu phòng đủ cho ''eighty guests''.","transcript":"M: Hello, this is David Chen from Orion Tech. We booked the Cypress Ballroom for Thursday, but our keynote speaker''s flight was postponed.\\nW: I see your reservation, Mr. Chen. Would you like to move it to Friday instead?\\nM: Yes, if you still have a room for eighty guests with dual projectors.\\nW: The Cypress Ballroom is booked Friday, but the Harbor Suite is available and includes two projectors at no extra charge.","translation":"Nam: Tôi là David Chen từ Orion Tech. Chúng tôi đặt phòng Cypress cho thứ Năm nhưng chuyến bay của diễn giả bị hoãn.\\nNữ: Phòng Cypress đã kín thứ Sáu nhưng phòng Harbor Suite còn trống cho 80 khách và có sẵn 2 máy chiếu không tính thêm phí.","vocabulary":[]}', 43, NOW(), NOW()),
(46, 'SINGLE_CHOICE', 'Part 3 G2 Q3: What does the woman offer as an alternative?', 3, '{"text":"What does the woman offer as an alternative?","options":[{"key":"A","text":"(A) A discounted weekend rate"},{"key":"B","text":"(B) A different room with two projectors"},{"key":"C","text":"(C) A refund of the deposit"},{"key":"D","text":"(D) A free breakfast buffet"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 2: Rescheduling a hotel conference room booking.', 3, '{"clue":"Cô đề xuất phòng Harbor Suite kèm 2 máy chiếu miễn phụ phí.","analysis":"Cô đề xuất phòng Harbor Suite kèm 2 máy chiếu miễn phụ phí.","transcript":"M: Hello, this is David Chen from Orion Tech. We booked the Cypress Ballroom for Thursday, but our keynote speaker''s flight was postponed.\\nW: I see your reservation, Mr. Chen. Would you like to move it to Friday instead?\\nM: Yes, if you still have a room for eighty guests with dual projectors.\\nW: The Cypress Ballroom is booked Friday, but the Harbor Suite is available and includes two projectors at no extra charge.","translation":"Nam: Tôi là David Chen từ Orion Tech. Chúng tôi đặt phòng Cypress cho thứ Năm nhưng chuyến bay của diễn giả bị hoãn.\\nNữ: Phòng Cypress đã kín thứ Sáu nhưng phòng Harbor Suite còn trống cho 80 khách và có sẵn 2 máy chiếu không tính thêm phí.","vocabulary":[]}', 43, NOW(), NOW()),
(47, 'SINGLE_CHOICE', 'Part 3 Conv 3: Warehouse inventory software barcode issue', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 3: Warehouse inventory software barcode issue).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 3.', 3, '{"transcript":"W: Ken, have you noticed the handheld barcode scanners aren''t syncing with the inventory dashboard today?\\nM: Yes, several shipping clerks mentioned that. It started right after the overnight firmware update.\\nW: We have forty pallets leaving for Osaka at four o''clock. How should we log them?\\nM: I already called IT support. Until they roll back the patch, let''s record the tracking numbers on the backup spreadsheet.","translation":"Nữ: Máy quét mã vạch cầm tay hôm nay không đồng bộ với bảng tồn kho. Chúng ta có 40 kiện hàng đi Osaka lúc 4 giờ.\\nNam: Lỗi phát sinh sau bản cập nhật đêm qua. Trong lúc chờ IT khôi phục bản vá, ta ghi tạm mã vận đơn vào bảng tính dự phòng.","analysis":"Nữ: Máy quét mã vạch cầm tay hôm nay không đồng bộ với bảng tồn kho. Chúng ta có 40 kiện hàng đi Osaka lúc 4 giờ.\\nNam: Lỗi phát sinh sau bản cập nhật đêm qua. Trong lúc chờ IT khôi phục bản vá, ta ghi tạm mã vận đơn vào bảng tính dự phòng.","vocabulary":[]}', NULL, NOW(), NOW()),
(48, 'SINGLE_CHOICE', 'Part 3 G3 Q1: What problem are the speakers discussing?', 1, '{"text":"What problem are the speakers discussing?","options":[{"key":"A","text":"(A) Missing pallets in the warehouse"},{"key":"B","text":"(B) Barcode scanners failing to sync"},{"key":"C","text":"(C) A delayed cargo ship to Osaka"},{"key":"D","text":"(D) Broken printer cables"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 3: Warehouse inventory software barcode issue.', 3, '{"clue":"Người phụ nữ nêu rõ máy quét mã vạch không đồng bộ với hệ thống.","analysis":"Người phụ nữ nêu rõ máy quét mã vạch không đồng bộ với hệ thống.","transcript":"W: Ken, have you noticed the handheld barcode scanners aren''t syncing with the inventory dashboard today?\\nM: Yes, several shipping clerks mentioned that. It started right after the overnight firmware update.\\nW: We have forty pallets leaving for Osaka at four o''clock. How should we log them?\\nM: I already called IT support. Until they roll back the patch, let''s record the tracking numbers on the backup spreadsheet.","translation":"Nữ: Máy quét mã vạch cầm tay hôm nay không đồng bộ với bảng tồn kho. Chúng ta có 40 kiện hàng đi Osaka lúc 4 giờ.\\nNam: Lỗi phát sinh sau bản cập nhật đêm qua. Trong lúc chờ IT khôi phục bản vá, ta ghi tạm mã vận đơn vào bảng tính dự phòng.","vocabulary":[]}', 47, NOW(), NOW()),
(49, 'SINGLE_CHOICE', 'Part 3 G3 Q2: What likely caused the issue?', 2, '{"text":"What likely caused the issue?","options":[{"key":"A","text":"(A) A power outage"},{"key":"B","text":"(B) An overnight firmware update"},{"key":"C","text":"(C) Expired user passwords"},{"key":"D","text":"(D) Damaged barcode labels"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 3: Warehouse inventory software barcode issue.', 3, '{"clue":"Sự cố bắt đầu ngay sau ''overnight firmware update''.","analysis":"Sự cố bắt đầu ngay sau ''overnight firmware update''.","transcript":"W: Ken, have you noticed the handheld barcode scanners aren''t syncing with the inventory dashboard today?\\nM: Yes, several shipping clerks mentioned that. It started right after the overnight firmware update.\\nW: We have forty pallets leaving for Osaka at four o''clock. How should we log them?\\nM: I already called IT support. Until they roll back the patch, let''s record the tracking numbers on the backup spreadsheet.","translation":"Nữ: Máy quét mã vạch cầm tay hôm nay không đồng bộ với bảng tồn kho. Chúng ta có 40 kiện hàng đi Osaka lúc 4 giờ.\\nNam: Lỗi phát sinh sau bản cập nhật đêm qua. Trong lúc chờ IT khôi phục bản vá, ta ghi tạm mã vận đơn vào bảng tính dự phòng.","vocabulary":[]}', 47, NOW(), NOW()),
(50, 'SINGLE_CHOICE', 'Part 3 G3 Q3: What will the speakers do temporarily?', 3, '{"text":"What will the speakers do temporarily?","options":[{"key":"A","text":"(A) Postpone the Osaka shipment"},{"key":"B","text":"(B) Use a backup spreadsheet to log numbers"},{"key":"C","text":"(C) Purchase new scanners"},{"key":"D","text":"(D) Ask the client to track manually"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 3: Warehouse inventory software barcode issue.', 3, '{"clue":"Họ sẽ ghi tạm số vận đơn vào ''backup spreadsheet''.","analysis":"Họ sẽ ghi tạm số vận đơn vào ''backup spreadsheet''.","transcript":"W: Ken, have you noticed the handheld barcode scanners aren''t syncing with the inventory dashboard today?\\nM: Yes, several shipping clerks mentioned that. It started right after the overnight firmware update.\\nW: We have forty pallets leaving for Osaka at four o''clock. How should we log them?\\nM: I already called IT support. Until they roll back the patch, let''s record the tracking numbers on the backup spreadsheet.","translation":"Nữ: Máy quét mã vạch cầm tay hôm nay không đồng bộ với bảng tồn kho. Chúng ta có 40 kiện hàng đi Osaka lúc 4 giờ.\\nNam: Lỗi phát sinh sau bản cập nhật đêm qua. Trong lúc chờ IT khôi phục bản vá, ta ghi tạm mã vận đơn vào bảng tính dự phòng.","vocabulary":[]}', 47, NOW(), NOW()),
(51, 'SINGLE_CHOICE', 'Part 3 Conv 4: Marketing campaign budget reallocation', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 4: Marketing campaign budget reallocation).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 4.', 3, '{"transcript":"M: Priya, our print magazine ads generated fewer leads than expected this quarter.\\nW: I noticed the same trend in the analytics report. Meanwhile, our short product videos on social media doubled conversion rates.\\nM: Should we shift thirty percent of next quarter''s print budget into video production?\\nW: Definitely. I''ll draft a revised media plan and send it to the finance director before Wednesday''s review.","translation":"Nam: Quảng cáo tạp chí in quý này mang lại ít khách hàng tiềm năng hơn dự kiến.\\nNữ: Trong khi đó video ngắn trên mạng xã hội tăng gấp đôi tỷ lệ chuyển đổi.\\nNam: Ta chuyển 30% ngân sách in ấn sang sản xuất video nhé? Nữ: Chắc chắn rồi, tôi sẽ gửi kế hoạch cho giám đốc tài chính trước thứ Tư.","analysis":"Nam: Quảng cáo tạp chí in quý này mang lại ít khách hàng tiềm năng hơn dự kiến.\\nNữ: Trong khi đó video ngắn trên mạng xã hội tăng gấp đôi tỷ lệ chuyển đổi.\\nNam: Ta chuyển 30% ngân sách in ấn sang sản xuất video nhé? Nữ: Chắc chắn rồi, tôi sẽ gửi kế hoạch cho giám đốc tài chính trước thứ Tư.","vocabulary":[]}', NULL, NOW(), NOW()),
(52, 'SINGLE_CHOICE', 'Part 3 G4 Q1: What performed better than expected this quarter?', 1, '{"text":"What performed better than expected this quarter?","options":[{"key":"A","text":"(A) Print magazine advertisements"},{"key":"B","text":"(B) Short social media videos"},{"key":"C","text":"(C) Radio sponsorships"},{"key":"D","text":"(D) Direct mail flyers"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 4: Marketing campaign budget reallocation.', 3, '{"clue":"Video ngắn trên mạng xã hội đã tăng gấp đôi tỷ lệ chuyển đổi.","analysis":"Video ngắn trên mạng xã hội đã tăng gấp đôi tỷ lệ chuyển đổi.","transcript":"M: Priya, our print magazine ads generated fewer leads than expected this quarter.\\nW: I noticed the same trend in the analytics report. Meanwhile, our short product videos on social media doubled conversion rates.\\nM: Should we shift thirty percent of next quarter''s print budget into video production?\\nW: Definitely. I''ll draft a revised media plan and send it to the finance director before Wednesday''s review.","translation":"Nam: Quảng cáo tạp chí in quý này mang lại ít khách hàng tiềm năng hơn dự kiến.\\nNữ: Trong khi đó video ngắn trên mạng xã hội tăng gấp đôi tỷ lệ chuyển đổi.\\nNam: Ta chuyển 30% ngân sách in ấn sang sản xuất video nhé? Nữ: Chắc chắn rồi, tôi sẽ gửi kế hoạch cho giám đốc tài chính trước thứ Tư.","vocabulary":[]}', 51, NOW(), NOW()),
(53, 'SINGLE_CHOICE', 'Part 3 G4 Q2: What change does the man propose?', 2, '{"text":"What change does the man propose?","options":[{"key":"A","text":"(A) Hiring a new creative agency"},{"key":"B","text":"(B) Moving 30% of the print budget to video"},{"key":"C","text":"(C) Cutting total marketing spend in half"},{"key":"D","text":"(D) Launching a print catalog"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 4: Marketing campaign budget reallocation.', 3, '{"clue":"Anh đề xuất chuyển 30% ngân sách in sang làm video.","analysis":"Anh đề xuất chuyển 30% ngân sách in sang làm video.","transcript":"M: Priya, our print magazine ads generated fewer leads than expected this quarter.\\nW: I noticed the same trend in the analytics report. Meanwhile, our short product videos on social media doubled conversion rates.\\nM: Should we shift thirty percent of next quarter''s print budget into video production?\\nW: Definitely. I''ll draft a revised media plan and send it to the finance director before Wednesday''s review.","translation":"Nam: Quảng cáo tạp chí in quý này mang lại ít khách hàng tiềm năng hơn dự kiến.\\nNữ: Trong khi đó video ngắn trên mạng xã hội tăng gấp đôi tỷ lệ chuyển đổi.\\nNam: Ta chuyển 30% ngân sách in ấn sang sản xuất video nhé? Nữ: Chắc chắn rồi, tôi sẽ gửi kế hoạch cho giám đốc tài chính trước thứ Tư.","vocabulary":[]}', 51, NOW(), NOW()),
(54, 'SINGLE_CHOICE', 'Part 3 G4 Q3: Who will receive the revised media plan?', 3, '{"text":"Who will receive the revised media plan?","options":[{"key":"A","text":"(A) The finance director"},{"key":"B","text":"(B) The sales interns"},{"key":"C","text":"(C) A magazine editor"},{"key":"D","text":"(D) The legal counsel"}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 4: Marketing campaign budget reallocation.', 3, '{"clue":"Bản kế hoạch sửa đổi sẽ được gửi cho ''the finance director''.","analysis":"Bản kế hoạch sửa đổi sẽ được gửi cho ''the finance director''.","transcript":"M: Priya, our print magazine ads generated fewer leads than expected this quarter.\\nW: I noticed the same trend in the analytics report. Meanwhile, our short product videos on social media doubled conversion rates.\\nM: Should we shift thirty percent of next quarter''s print budget into video production?\\nW: Definitely. I''ll draft a revised media plan and send it to the finance director before Wednesday''s review.","translation":"Nam: Quảng cáo tạp chí in quý này mang lại ít khách hàng tiềm năng hơn dự kiến.\\nNữ: Trong khi đó video ngắn trên mạng xã hội tăng gấp đôi tỷ lệ chuyển đổi.\\nNam: Ta chuyển 30% ngân sách in ấn sang sản xuất video nhé? Nữ: Chắc chắn rồi, tôi sẽ gửi kế hoạch cho giám đốc tài chính trước thứ Tư.","vocabulary":[]}', 51, NOW(), NOW()),
(55, 'SINGLE_CHOICE', 'Part 3 Conv 5: Office renovation and temporary seating', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 5: Office renovation and temporary seating).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 5.', 3, '{"transcript":"W: Excuse me, Marcus. Are the painters starting on the fifth-floor design studio next Monday?\\nM: Actually, the contractor pushed it up to this Thursday so they can finish before the holiday weekend.\\nW: Oh, that''s much sooner! Where will my graphic designers set up their workstations?\\nM: Facilities reserved the empty training suite on the second floor, and high-speed ethernet lines are already active there.","translation":"Nữ: Thợ sơn có bắt đầu ở phòng thiết kế tầng 5 vào thứ Hai tới không?\\nNam: Nhà thầu đẩy lịch sớm lên thứ Năm tuần này. Nhóm thiết kế sẽ chuyển tạm xuống phòng đào tạo tầng 2 đã có sẵn mạng cáp tốc độ cao.","analysis":"Nữ: Thợ sơn có bắt đầu ở phòng thiết kế tầng 5 vào thứ Hai tới không?\\nNam: Nhà thầu đẩy lịch sớm lên thứ Năm tuần này. Nhóm thiết kế sẽ chuyển tạm xuống phòng đào tạo tầng 2 đã có sẵn mạng cáp tốc độ cao.","vocabulary":[]}', NULL, NOW(), NOW()),
(56, 'SINGLE_CHOICE', 'Part 3 G5 Q1: When will the renovation work begin?', 1, '{"text":"When will the renovation work begin?","options":[{"key":"A","text":"(A) Next Monday"},{"key":"B","text":"(B) This Thursday"},{"key":"C","text":"(C) Next Friday"},{"key":"D","text":"(D) After the holiday"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 5: Office renovation and temporary seating.', 3, '{"clue":"Nhà thầu đã đẩy lịch sớm hơn sang ''this Thursday''.","analysis":"Nhà thầu đã đẩy lịch sớm hơn sang ''this Thursday''.","transcript":"W: Excuse me, Marcus. Are the painters starting on the fifth-floor design studio next Monday?\\nM: Actually, the contractor pushed it up to this Thursday so they can finish before the holiday weekend.\\nW: Oh, that''s much sooner! Where will my graphic designers set up their workstations?\\nM: Facilities reserved the empty training suite on the second floor, and high-speed ethernet lines are already active there.","translation":"Nữ: Thợ sơn có bắt đầu ở phòng thiết kế tầng 5 vào thứ Hai tới không?\\nNam: Nhà thầu đẩy lịch sớm lên thứ Năm tuần này. Nhóm thiết kế sẽ chuyển tạm xuống phòng đào tạo tầng 2 đã có sẵn mạng cáp tốc độ cao.","vocabulary":[]}', 55, NOW(), NOW()),
(57, 'SINGLE_CHOICE', 'Part 3 G5 Q2: Why was the schedule moved earlier?', 2, '{"text":"Why was the schedule moved earlier?","options":[{"key":"A","text":"(A) To complete work before the holiday weekend"},{"key":"B","text":"(B) To lower contractor fees"},{"key":"C","text":"(C) Because paint supplies were expiring"},{"key":"D","text":"(D) To prepare for a client visit"}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 5: Office renovation and temporary seating.', 3, '{"clue":"Họ muốn hoàn thành trước kỳ nghỉ lễ cuối tuần.","analysis":"Họ muốn hoàn thành trước kỳ nghỉ lễ cuối tuần.","transcript":"W: Excuse me, Marcus. Are the painters starting on the fifth-floor design studio next Monday?\\nM: Actually, the contractor pushed it up to this Thursday so they can finish before the holiday weekend.\\nW: Oh, that''s much sooner! Where will my graphic designers set up their workstations?\\nM: Facilities reserved the empty training suite on the second floor, and high-speed ethernet lines are already active there.","translation":"Nữ: Thợ sơn có bắt đầu ở phòng thiết kế tầng 5 vào thứ Hai tới không?\\nNam: Nhà thầu đẩy lịch sớm lên thứ Năm tuần này. Nhóm thiết kế sẽ chuyển tạm xuống phòng đào tạo tầng 2 đã có sẵn mạng cáp tốc độ cao.","vocabulary":[]}', 55, NOW(), NOW()),
(58, 'SINGLE_CHOICE', 'Part 3 G5 Q3: Where will the design team work temporarily?', 3, '{"text":"Where will the design team work temporarily?","options":[{"key":"A","text":"(A) From home"},{"key":"B","text":"(B) In the second-floor training suite"},{"key":"C","text":"(C) In the lobby lounge"},{"key":"D","text":"(D) At a nearby coworking space"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 5: Office renovation and temporary seating.', 3, '{"clue":"Bộ phận cơ sở vật chất đã đặt phòng đào tạo trống ở tầng 2.","analysis":"Bộ phận cơ sở vật chất đã đặt phòng đào tạo trống ở tầng 2.","transcript":"W: Excuse me, Marcus. Are the painters starting on the fifth-floor design studio next Monday?\\nM: Actually, the contractor pushed it up to this Thursday so they can finish before the holiday weekend.\\nW: Oh, that''s much sooner! Where will my graphic designers set up their workstations?\\nM: Facilities reserved the empty training suite on the second floor, and high-speed ethernet lines are already active there.","translation":"Nữ: Thợ sơn có bắt đầu ở phòng thiết kế tầng 5 vào thứ Hai tới không?\\nNam: Nhà thầu đẩy lịch sớm lên thứ Năm tuần này. Nhóm thiết kế sẽ chuyển tạm xuống phòng đào tạo tầng 2 đã có sẵn mạng cáp tốc độ cao.","vocabulary":[]}', 55, NOW(), NOW()),
(59, 'SINGLE_CHOICE', 'Part 3 Conv 6: Customer service inquiry about defective espresso machine', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 6: Customer service inquiry about defective espresso machine).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 6.', 3, '{"transcript":"M: Good afternoon, BrewMaster Support. How can I assist you today?\\nW: Hi, I purchased your commercial espresso machine last month for my bakery, and the steam wand stopped building pressure yesterday.\\nM: I apologize for the trouble. Since it''s still within the ninety-day commercial exchange window, we can ship a replacement unit overnight.\\nW: That would save our weekend rush! Should I return the faulty machine in the same crate?","translation":"Nam: Hỗ trợ BrewMaster xin nghe.\\nNữ: Tôi mua máy pha cà phê thương mại tháng trước cho tiệm bánh nhưng vòi đánh sữa mất áp suất.\\nNam: Vì còn trong hạn đổi trả 90 ngày, chúng tôi sẽ gửi máy thay thế giao qua đêm ngay.","analysis":"Nam: Hỗ trợ BrewMaster xin nghe.\\nNữ: Tôi mua máy pha cà phê thương mại tháng trước cho tiệm bánh nhưng vòi đánh sữa mất áp suất.\\nNam: Vì còn trong hạn đổi trả 90 ngày, chúng tôi sẽ gửi máy thay thế giao qua đêm ngay.","vocabulary":[]}', NULL, NOW(), NOW()),
(60, 'SINGLE_CHOICE', 'Part 3 G6 Q1: Where does the woman most likely work?', 1, '{"text":"Where does the woman most likely work?","options":[{"key":"A","text":"(A) At an appliance factory"},{"key":"B","text":"(B) At a bakery"},{"key":"C","text":"(C) At a shipping company"},{"key":"D","text":"(D) At a hardware store"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 6: Customer service inquiry about defective espresso machine.', 3, '{"clue":"Cô nói rõ ''I purchased your commercial espresso machine for my bakery''.","analysis":"Cô nói rõ ''I purchased your commercial espresso machine for my bakery''.","transcript":"M: Good afternoon, BrewMaster Support. How can I assist you today?\\nW: Hi, I purchased your commercial espresso machine last month for my bakery, and the steam wand stopped building pressure yesterday.\\nM: I apologize for the trouble. Since it''s still within the ninety-day commercial exchange window, we can ship a replacement unit overnight.\\nW: That would save our weekend rush! Should I return the faulty machine in the same crate?","translation":"Nam: Hỗ trợ BrewMaster xin nghe.\\nNữ: Tôi mua máy pha cà phê thương mại tháng trước cho tiệm bánh nhưng vòi đánh sữa mất áp suất.\\nNam: Vì còn trong hạn đổi trả 90 ngày, chúng tôi sẽ gửi máy thay thế giao qua đêm ngay.","vocabulary":[]}', 59, NOW(), NOW()),
(61, 'SINGLE_CHOICE', 'Part 3 G6 Q2: What is wrong with the machine?', 2, '{"text":"What is wrong with the machine?","options":[{"key":"A","text":"(A) The power cord is frayed"},{"key":"B","text":"(B) The steam wand lost pressure"},{"key":"C","text":"(C) The water tank is cracked"},{"key":"D","text":"(D) The grinder is jammed"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 6: Customer service inquiry about defective espresso machine.', 3, '{"clue":"Vòi đánh sữa ''stopped building pressure''.","analysis":"Vòi đánh sữa ''stopped building pressure''.","transcript":"M: Good afternoon, BrewMaster Support. How can I assist you today?\\nW: Hi, I purchased your commercial espresso machine last month for my bakery, and the steam wand stopped building pressure yesterday.\\nM: I apologize for the trouble. Since it''s still within the ninety-day commercial exchange window, we can ship a replacement unit overnight.\\nW: That would save our weekend rush! Should I return the faulty machine in the same crate?","translation":"Nam: Hỗ trợ BrewMaster xin nghe.\\nNữ: Tôi mua máy pha cà phê thương mại tháng trước cho tiệm bánh nhưng vòi đánh sữa mất áp suất.\\nNam: Vì còn trong hạn đổi trả 90 ngày, chúng tôi sẽ gửi máy thay thế giao qua đêm ngay.","vocabulary":[]}', 59, NOW(), NOW()),
(62, 'SINGLE_CHOICE', 'Part 3 G6 Q3: What solution does the representative offer?', 3, '{"text":"What solution does the representative offer?","options":[{"key":"A","text":"(A) A partial cash refund"},{"key":"B","text":"(B) An overnight replacement unit"},{"key":"C","text":"(C) An on-site repair next month"},{"key":"D","text":"(D) A discount coupon"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 6: Customer service inquiry about defective espresso machine.', 3, '{"clue":"Hãng sẽ gửi máy thay thế giao qua đêm (''ship a replacement unit overnight'').","analysis":"Hãng sẽ gửi máy thay thế giao qua đêm (''ship a replacement unit overnight'').","transcript":"M: Good afternoon, BrewMaster Support. How can I assist you today?\\nW: Hi, I purchased your commercial espresso machine last month for my bakery, and the steam wand stopped building pressure yesterday.\\nM: I apologize for the trouble. Since it''s still within the ninety-day commercial exchange window, we can ship a replacement unit overnight.\\nW: That would save our weekend rush! Should I return the faulty machine in the same crate?","translation":"Nam: Hỗ trợ BrewMaster xin nghe.\\nNữ: Tôi mua máy pha cà phê thương mại tháng trước cho tiệm bánh nhưng vòi đánh sữa mất áp suất.\\nNam: Vì còn trong hạn đổi trả 90 ngày, chúng tôi sẽ gửi máy thay thế giao qua đêm ngay.","vocabulary":[]}', 59, NOW(), NOW()),
(63, 'SINGLE_CHOICE', 'Part 3 Conv 7: Planning a corporate charity run event', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 7: Planning a corporate charity run event).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 7.', 3, '{"transcript":"W: Carlos, have we finalized the route for the annual 5K charity run along the riverfront?\\nM: Yes, the city parks office approved the permit this morning. Now we just need volunteers to staff the three water stations.\\nW: I can post a sign-up sheet on the staff bulletin board and announce it at tomorrow''s town hall.\\nM: Great! Also remind everyone that volunteers receive a complimentary event jacket.","translation":"Nữ: Ta chốt đường chạy từ thiện 5K ven sông chưa?\\nNam: Sở công viên đã cấp phép sáng nay, giờ chỉ cần tình nguyện viên trực 3 trạm tiếp nước. Tình nguyện viên sẽ được tặng áo khoác sự kiện miễn phí.","analysis":"Nữ: Ta chốt đường chạy từ thiện 5K ven sông chưa?\\nNam: Sở công viên đã cấp phép sáng nay, giờ chỉ cần tình nguyện viên trực 3 trạm tiếp nước. Tình nguyện viên sẽ được tặng áo khoác sự kiện miễn phí.","vocabulary":[]}', NULL, NOW(), NOW()),
(64, 'SINGLE_CHOICE', 'Part 3 G7 Q1: What did the city parks office approve?', 1, '{"text":"What did the city parks office approve?","options":[{"key":"A","text":"(A) A food truck license"},{"key":"B","text":"(B) The permit for a charity run"},{"key":"C","text":"(C) A parking lot expansion"},{"key":"D","text":"(D) A concert stage"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 7: Planning a corporate charity run event.', 3, '{"clue":"Sở công viên đã cấp giấy phép đường chạy từ thiện 5K.","analysis":"Sở công viên đã cấp giấy phép đường chạy từ thiện 5K.","transcript":"W: Carlos, have we finalized the route for the annual 5K charity run along the riverfront?\\nM: Yes, the city parks office approved the permit this morning. Now we just need volunteers to staff the three water stations.\\nW: I can post a sign-up sheet on the staff bulletin board and announce it at tomorrow''s town hall.\\nM: Great! Also remind everyone that volunteers receive a complimentary event jacket.","translation":"Nữ: Ta chốt đường chạy từ thiện 5K ven sông chưa?\\nNam: Sở công viên đã cấp phép sáng nay, giờ chỉ cần tình nguyện viên trực 3 trạm tiếp nước. Tình nguyện viên sẽ được tặng áo khoác sự kiện miễn phí.","vocabulary":[]}', 63, NOW(), NOW()),
(65, 'SINGLE_CHOICE', 'Part 3 G7 Q2: What do the organizers still need?', 2, '{"text":"What do the organizers still need?","options":[{"key":"A","text":"(A) Sponsors for prizes"},{"key":"B","text":"(B) Volunteers for water stations"},{"key":"C","text":"(C) Printed race maps"},{"key":"D","text":"(D) Medical ambulances"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 7: Planning a corporate charity run event.', 3, '{"clue":"Họ cần tình nguyện viên phụ trách 3 trạm tiếp nước.","analysis":"Họ cần tình nguyện viên phụ trách 3 trạm tiếp nước.","transcript":"W: Carlos, have we finalized the route for the annual 5K charity run along the riverfront?\\nM: Yes, the city parks office approved the permit this morning. Now we just need volunteers to staff the three water stations.\\nW: I can post a sign-up sheet on the staff bulletin board and announce it at tomorrow''s town hall.\\nM: Great! Also remind everyone that volunteers receive a complimentary event jacket.","translation":"Nữ: Ta chốt đường chạy từ thiện 5K ven sông chưa?\\nNam: Sở công viên đã cấp phép sáng nay, giờ chỉ cần tình nguyện viên trực 3 trạm tiếp nước. Tình nguyện viên sẽ được tặng áo khoác sự kiện miễn phí.","vocabulary":[]}', 63, NOW(), NOW()),
(66, 'SINGLE_CHOICE', 'Part 3 G7 Q3: What incentive is mentioned for volunteers?', 3, '{"text":"What incentive is mentioned for volunteers?","options":[{"key":"A","text":"(A) Extra vacation hours"},{"key":"B","text":"(B) A complimentary event jacket"},{"key":"C","text":"(C) Free lunch vouchers"},{"key":"D","text":"(D) Gift cards"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 7: Planning a corporate charity run event.', 3, '{"clue":"Tình nguyện viên được tặng ''a complimentary event jacket''.","analysis":"Tình nguyện viên được tặng ''a complimentary event jacket''.","transcript":"W: Carlos, have we finalized the route for the annual 5K charity run along the riverfront?\\nM: Yes, the city parks office approved the permit this morning. Now we just need volunteers to staff the three water stations.\\nW: I can post a sign-up sheet on the staff bulletin board and announce it at tomorrow''s town hall.\\nM: Great! Also remind everyone that volunteers receive a complimentary event jacket.","translation":"Nữ: Ta chốt đường chạy từ thiện 5K ven sông chưa?\\nNam: Sở công viên đã cấp phép sáng nay, giờ chỉ cần tình nguyện viên trực 3 trạm tiếp nước. Tình nguyện viên sẽ được tặng áo khoác sự kiện miễn phí.","vocabulary":[]}', 63, NOW(), NOW()),
(67, 'SINGLE_CHOICE', 'Part 3 Conv 8: Reviewing a software release timeline', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 8: Reviewing a software release timeline).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 4, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 8.', 3, '{"transcript":"M: Hannah, QA found two minor checkout bugs in the mobile app beta. Will that delay Friday''s launch?\\nW: Not necessarily. Both bugs are isolated to the coupon validation module, so my developers can patch them by tonight.\\nM: That''s a relief. Our press release is already scheduled to go live at 9:00 A.M. Friday.\\nW: Let''s run a final regression test tomorrow afternoon so we can sign off with complete confidence.","translation":"Nam: QA tìm thấy 2 lỗi nhỏ ở phần thanh toán bản beta, có làm trễ lịch ra mắt thứ Sáu không?\\nNữ: Hai lỗi nằm gọn ở mô-đun mã giảm giá nên đội dev vá xong tối nay, chiều mai chạy kiểm thử hồi quy chốt luôn.","analysis":"Nam: QA tìm thấy 2 lỗi nhỏ ở phần thanh toán bản beta, có làm trễ lịch ra mắt thứ Sáu không?\\nNữ: Hai lỗi nằm gọn ở mô-đun mã giảm giá nên đội dev vá xong tối nay, chiều mai chạy kiểm thử hồi quy chốt luôn.","vocabulary":[]}', NULL, NOW(), NOW()),
(68, 'SINGLE_CHOICE', 'Part 3 G8 Q1: Where were the two bugs discovered?', 1, '{"text":"Where were the two bugs discovered?","options":[{"key":"A","text":"(A) In the login screen"},{"key":"B","text":"(B) In the coupon validation module"},{"key":"C","text":"(C) In the push notification service"},{"key":"D","text":"(D) In the profile settings"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 8: Reviewing a software release timeline.', 3, '{"clue":"Cả hai lỗi đều nằm trong ''coupon validation module''.","analysis":"Cả hai lỗi đều nằm trong ''coupon validation module''.","transcript":"M: Hannah, QA found two minor checkout bugs in the mobile app beta. Will that delay Friday''s launch?\\nW: Not necessarily. Both bugs are isolated to the coupon validation module, so my developers can patch them by tonight.\\nM: That''s a relief. Our press release is already scheduled to go live at 9:00 A.M. Friday.\\nW: Let''s run a final regression test tomorrow afternoon so we can sign off with complete confidence.","translation":"Nam: QA tìm thấy 2 lỗi nhỏ ở phần thanh toán bản beta, có làm trễ lịch ra mắt thứ Sáu không?\\nNữ: Hai lỗi nằm gọn ở mô-đun mã giảm giá nên đội dev vá xong tối nay, chiều mai chạy kiểm thử hồi quy chốt luôn.","vocabulary":[]}', 67, NOW(), NOW()),
(69, 'SINGLE_CHOICE', 'Part 3 G8 Q2: Why is the man concerned about delaying Friday''s launch?', 2, '{"text":"Why is the man concerned about delaying Friday''s launch?","options":[{"key":"A","text":"(A) Investors are visiting"},{"key":"B","text":"(B) A press release is scheduled for Friday morning"},{"key":"C","text":"(C) The app store closes for maintenance"},{"key":"D","text":"(D) Developers are going on leave"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 8: Reviewing a software release timeline.', 3, '{"clue":"Thông cáo báo chí đã lên lịch phát hành lúc 9 giờ sáng thứ Sáu.","analysis":"Thông cáo báo chí đã lên lịch phát hành lúc 9 giờ sáng thứ Sáu.","transcript":"M: Hannah, QA found two minor checkout bugs in the mobile app beta. Will that delay Friday''s launch?\\nW: Not necessarily. Both bugs are isolated to the coupon validation module, so my developers can patch them by tonight.\\nM: That''s a relief. Our press release is already scheduled to go live at 9:00 A.M. Friday.\\nW: Let''s run a final regression test tomorrow afternoon so we can sign off with complete confidence.","translation":"Nam: QA tìm thấy 2 lỗi nhỏ ở phần thanh toán bản beta, có làm trễ lịch ra mắt thứ Sáu không?\\nNữ: Hai lỗi nằm gọn ở mô-đun mã giảm giá nên đội dev vá xong tối nay, chiều mai chạy kiểm thử hồi quy chốt luôn.","vocabulary":[]}', 67, NOW(), NOW()),
(70, 'SINGLE_CHOICE', 'Part 3 G8 Q3: What will happen tomorrow afternoon?', 3, '{"text":"What will happen tomorrow afternoon?","options":[{"key":"A","text":"(A) A final regression test"},{"key":"B","text":"(B) A press conference"},{"key":"C","text":"(C) A customer survey"},{"key":"D","text":"(D) A hiring interview"}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 8: Reviewing a software release timeline.', 3, '{"clue":"Nhóm sẽ chạy bài kiểm thử hồi quy cuối cùng vào chiều mai.","analysis":"Nhóm sẽ chạy bài kiểm thử hồi quy cuối cùng vào chiều mai.","transcript":"M: Hannah, QA found two minor checkout bugs in the mobile app beta. Will that delay Friday''s launch?\\nW: Not necessarily. Both bugs are isolated to the coupon validation module, so my developers can patch them by tonight.\\nM: That''s a relief. Our press release is already scheduled to go live at 9:00 A.M. Friday.\\nW: Let''s run a final regression test tomorrow afternoon so we can sign off with complete confidence.","translation":"Nam: QA tìm thấy 2 lỗi nhỏ ở phần thanh toán bản beta, có làm trễ lịch ra mắt thứ Sáu không?\\nNữ: Hai lỗi nằm gọn ở mô-đun mã giảm giá nên đội dev vá xong tối nay, chiều mai chạy kiểm thử hồi quy chốt luôn.","vocabulary":[]}', 67, NOW(), NOW()),
(71, 'SINGLE_CHOICE', 'Part 3 Conv 9: Negotiating bulk office furniture delivery', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 9: Negotiating bulk office furniture delivery).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 9.', 3, '{"transcript":"W: Thanks for meeting with me, Mr. Sato. We''re furnishing our new Austin branch and need sixty ergonomic chairs by June 15.\\nM: We currently have forty-five in our Dallas warehouse and can manufacture the remaining fifteen within ten days.\\nW: That fits our timeline. Does your price include assembly and packaging removal?\\nM: For orders over fifty units, we waive the assembly fee and haul away all cardboard.","translation":"Nữ: Chúng tôi cần 60 ghế công thái học cho chi nhánh Austin trước 15/6. Giá có bao gồm lắp đặt không?\\nNam: Kho Dallas có sẵn 45 chiếc, 15 chiếc còn lại sản xuất trong 10 ngày. Đơn trên 50 chiếc được miễn phí lắp đặt và thu dọn thùng bìa.","analysis":"Nữ: Chúng tôi cần 60 ghế công thái học cho chi nhánh Austin trước 15/6. Giá có bao gồm lắp đặt không?\\nNam: Kho Dallas có sẵn 45 chiếc, 15 chiếc còn lại sản xuất trong 10 ngày. Đơn trên 50 chiếc được miễn phí lắp đặt và thu dọn thùng bìa.","vocabulary":[]}', NULL, NOW(), NOW()),
(72, 'SINGLE_CHOICE', 'Part 3 G9 Q1: How many chairs does the woman''s company need?', 1, '{"text":"How many chairs does the woman''s company need?","options":[{"key":"A","text":"(A) Fifteen"},{"key":"B","text":"(B) Forty-five"},{"key":"C","text":"(C) Fifty"},{"key":"D","text":"(D) Sixty"}]}', '{"selected":"D","key":"D"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 9: Negotiating bulk office furniture delivery.', 3, '{"clue":"Cô yêu cầu ''sixty ergonomic chairs''.","analysis":"Cô yêu cầu ''sixty ergonomic chairs''.","transcript":"W: Thanks for meeting with me, Mr. Sato. We''re furnishing our new Austin branch and need sixty ergonomic chairs by June 15.\\nM: We currently have forty-five in our Dallas warehouse and can manufacture the remaining fifteen within ten days.\\nW: That fits our timeline. Does your price include assembly and packaging removal?\\nM: For orders over fifty units, we waive the assembly fee and haul away all cardboard.","translation":"Nữ: Chúng tôi cần 60 ghế công thái học cho chi nhánh Austin trước 15/6. Giá có bao gồm lắp đặt không?\\nNam: Kho Dallas có sẵn 45 chiếc, 15 chiếc còn lại sản xuất trong 10 ngày. Đơn trên 50 chiếc được miễn phí lắp đặt và thu dọn thùng bìa.","vocabulary":[]}', 71, NOW(), NOW()),
(73, 'SINGLE_CHOICE', 'Part 3 G9 Q2: How will the supplier fulfill the remaining chairs?', 2, '{"text":"How will the supplier fulfill the remaining chairs?","options":[{"key":"A","text":"(A) Order them from overseas"},{"key":"B","text":"(B) Manufacture them within ten days"},{"key":"C","text":"(C) Transfer them from Austin"},{"key":"D","text":"(D) Substitute a different model"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 9: Negotiating bulk office furniture delivery.', 3, '{"clue":"15 chiếc còn lại sẽ được sản xuất trong vòng 10 ngày.","analysis":"15 chiếc còn lại sẽ được sản xuất trong vòng 10 ngày.","transcript":"W: Thanks for meeting with me, Mr. Sato. We''re furnishing our new Austin branch and need sixty ergonomic chairs by June 15.\\nM: We currently have forty-five in our Dallas warehouse and can manufacture the remaining fifteen within ten days.\\nW: That fits our timeline. Does your price include assembly and packaging removal?\\nM: For orders over fifty units, we waive the assembly fee and haul away all cardboard.","translation":"Nữ: Chúng tôi cần 60 ghế công thái học cho chi nhánh Austin trước 15/6. Giá có bao gồm lắp đặt không?\\nNam: Kho Dallas có sẵn 45 chiếc, 15 chiếc còn lại sản xuất trong 10 ngày. Đơn trên 50 chiếc được miễn phí lắp đặt và thu dọn thùng bìa.","vocabulary":[]}', 71, NOW(), NOW()),
(74, 'SINGLE_CHOICE', 'Part 3 G9 Q3: What benefit applies to orders over fifty units?', 3, '{"text":"What benefit applies to orders over fifty units?","options":[{"key":"A","text":"(A) Extended five-year warranty"},{"key":"B","text":"(B) Free assembly and packaging removal"},{"key":"C","text":"(C) A 20% volume rebate"},{"key":"D","text":"(D) Free standing desks"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 9: Negotiating bulk office furniture delivery.', 3, '{"clue":"Miễn phí lắp đặt (''waive the assembly fee'') và dọn sạch thùng bìa.","analysis":"Miễn phí lắp đặt (''waive the assembly fee'') và dọn sạch thùng bìa.","transcript":"W: Thanks for meeting with me, Mr. Sato. We''re furnishing our new Austin branch and need sixty ergonomic chairs by June 15.\\nM: We currently have forty-five in our Dallas warehouse and can manufacture the remaining fifteen within ten days.\\nW: That fits our timeline. Does your price include assembly and packaging removal?\\nM: For orders over fifty units, we waive the assembly fee and haul away all cardboard.","translation":"Nữ: Chúng tôi cần 60 ghế công thái học cho chi nhánh Austin trước 15/6. Giá có bao gồm lắp đặt không?\\nNam: Kho Dallas có sẵn 45 chiếc, 15 chiếc còn lại sản xuất trong 10 ngày. Đơn trên 50 chiếc được miễn phí lắp đặt và thu dọn thùng bìa.","vocabulary":[]}', 71, NOW(), NOW()),
(75, 'SINGLE_CHOICE', 'Part 3 Conv 10: Coordinating an international business trip', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 10: Coordinating an international business trip).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 10.', 3, '{"transcript":"M: Mei, did the travel desk confirm your hotel near the Frankfurt exhibition center?\\nW: Yes, I''m staying two blocks from Hall 3. However, my return flight has a six-hour layover in Zurich.\\nM: Why not request the direct evening flight instead? Our updated travel policy covers direct flights for trips over eight hours.\\nW: Really? I didn''t realize the policy changed last month. I''ll call the agency right away.","translation":"Nam: Phòng du lịch xác nhận khách sạn ở Frankfurt cho cô chưa?\\nNữ: Rồi, nhưng chuyến bay về bị quá cảnh 6 tiếng ở Zurich.\\nNam: Chính sách công tác mới cho phép đặt bay thẳng với chặng trên 8 tiếng đấy. Cô gọi đại lý đổi ngay đi.","analysis":"Nam: Phòng du lịch xác nhận khách sạn ở Frankfurt cho cô chưa?\\nNữ: Rồi, nhưng chuyến bay về bị quá cảnh 6 tiếng ở Zurich.\\nNam: Chính sách công tác mới cho phép đặt bay thẳng với chặng trên 8 tiếng đấy. Cô gọi đại lý đổi ngay đi.","vocabulary":[]}', NULL, NOW(), NOW()),
(76, 'SINGLE_CHOICE', 'Part 3 G10 Q1: What issue does the woman mention about her itinerary?', 1, '{"text":"What issue does the woman mention about her itinerary?","options":[{"key":"A","text":"(A) Her hotel is too far away"},{"key":"B","text":"(B) Her return flight has a long layover"},{"key":"C","text":"(C) Her passport is expired"},{"key":"D","text":"(D) Her conference badge is missing"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 10: Coordinating an international business trip.', 3, '{"clue":"Chuyến bay về bị quá cảnh 6 tiếng tại Zurich.","analysis":"Chuyến bay về bị quá cảnh 6 tiếng tại Zurich.","transcript":"M: Mei, did the travel desk confirm your hotel near the Frankfurt exhibition center?\\nW: Yes, I''m staying two blocks from Hall 3. However, my return flight has a six-hour layover in Zurich.\\nM: Why not request the direct evening flight instead? Our updated travel policy covers direct flights for trips over eight hours.\\nW: Really? I didn''t realize the policy changed last month. I''ll call the agency right away.","translation":"Nam: Phòng du lịch xác nhận khách sạn ở Frankfurt cho cô chưa?\\nNữ: Rồi, nhưng chuyến bay về bị quá cảnh 6 tiếng ở Zurich.\\nNam: Chính sách công tác mới cho phép đặt bay thẳng với chặng trên 8 tiếng đấy. Cô gọi đại lý đổi ngay đi.","vocabulary":[]}', 75, NOW(), NOW()),
(77, 'SINGLE_CHOICE', 'Part 3 G10 Q2: What does the man inform the woman about?', 2, '{"text":"What does the man inform the woman about?","options":[{"key":"A","text":"(A) A hotel upgrade"},{"key":"B","text":"(B) An updated company travel policy"},{"key":"C","text":"(C) A train strike in Zurich"},{"key":"D","text":"(D) A rescheduled trade fair"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 10: Coordinating an international business trip.', 3, '{"clue":"Chính sách công tác mới hỗ trợ bay thẳng cho chuyến trên 8 giờ.","analysis":"Chính sách công tác mới hỗ trợ bay thẳng cho chuyến trên 8 giờ.","transcript":"M: Mei, did the travel desk confirm your hotel near the Frankfurt exhibition center?\\nW: Yes, I''m staying two blocks from Hall 3. However, my return flight has a six-hour layover in Zurich.\\nM: Why not request the direct evening flight instead? Our updated travel policy covers direct flights for trips over eight hours.\\nW: Really? I didn''t realize the policy changed last month. I''ll call the agency right away.","translation":"Nam: Phòng du lịch xác nhận khách sạn ở Frankfurt cho cô chưa?\\nNữ: Rồi, nhưng chuyến bay về bị quá cảnh 6 tiếng ở Zurich.\\nNam: Chính sách công tác mới cho phép đặt bay thẳng với chặng trên 8 tiếng đấy. Cô gọi đại lý đổi ngay đi.","vocabulary":[]}', 75, NOW(), NOW()),
(78, 'SINGLE_CHOICE', 'Part 3 G10 Q3: What will the woman probably do next?', 3, '{"text":"What will the woman probably do next?","options":[{"key":"A","text":"(A) Book a hotel in Zurich"},{"key":"B","text":"(B) Contact the travel agency to change her flight"},{"key":"C","text":"(C) Cancel her trip"},{"key":"D","text":"(D) Attend a different seminar"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 10: Coordinating an international business trip.', 3, '{"clue":"Cô nói sẽ gọi đại lý du lịch ngay (''call the agency right away'').","analysis":"Cô nói sẽ gọi đại lý du lịch ngay (''call the agency right away'').","transcript":"M: Mei, did the travel desk confirm your hotel near the Frankfurt exhibition center?\\nW: Yes, I''m staying two blocks from Hall 3. However, my return flight has a six-hour layover in Zurich.\\nM: Why not request the direct evening flight instead? Our updated travel policy covers direct flights for trips over eight hours.\\nW: Really? I didn''t realize the policy changed last month. I''ll call the agency right away.","translation":"Nam: Phòng du lịch xác nhận khách sạn ở Frankfurt cho cô chưa?\\nNữ: Rồi, nhưng chuyến bay về bị quá cảnh 6 tiếng ở Zurich.\\nNam: Chính sách công tác mới cho phép đặt bay thẳng với chặng trên 8 tiếng đấy. Cô gọi đại lý đổi ngay đi.","vocabulary":[]}', 75, NOW(), NOW()),
(79, 'SINGLE_CHOICE', 'Part 3 Conv 11: Discussing quarterly employee wellness program', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 11: Discussing quarterly employee wellness program).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 3, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 11.', 3, '{"transcript":"W: Ben, participation in our lunchtime yoga classes jumped forty percent since we moved them to the rooftop terrace.\\nM: That''s fantastic news! Employees have also been asking whether we could add a nutrition workshop next month.\\nW: I know a registered dietitian who gives corporate talks. Let''s check if she has availability on a Tuesday.\\nM: Perfect—I''ll verify the wellness budget and confirm we can cover her speaker honorarium.","translation":"Nữ: Tỷ lệ tham gia lớp yoga buổi trưa tăng 40% từ khi chuyển lên sân thượng.\\nNam: Nhân viên cũng muốn thêm hội thảo dinh dưỡng tháng sau. Tôi sẽ kiểm tra ngân sách phúc lợi để chi trả thù lao diễn giả.","analysis":"Nữ: Tỷ lệ tham gia lớp yoga buổi trưa tăng 40% từ khi chuyển lên sân thượng.\\nNam: Nhân viên cũng muốn thêm hội thảo dinh dưỡng tháng sau. Tôi sẽ kiểm tra ngân sách phúc lợi để chi trả thù lao diễn giả.","vocabulary":[]}', NULL, NOW(), NOW()),
(80, 'SINGLE_CHOICE', 'Part 3 G11 Q1: Why did attendance at the yoga classes increase?', 1, '{"text":"Why did attendance at the yoga classes increase?","options":[{"key":"A","text":"(A) They were moved to the rooftop terrace"},{"key":"B","text":"(B) A new instructor was hired"},{"key":"C","text":"(C) They were held after work"},{"key":"D","text":"(D) Free mats were distributed"}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 11: Discussing quarterly employee wellness program.', 3, '{"clue":"Từ khi chuyển địa điểm lên sân thượng, số người tham gia tăng 40%.","analysis":"Từ khi chuyển địa điểm lên sân thượng, số người tham gia tăng 40%.","transcript":"W: Ben, participation in our lunchtime yoga classes jumped forty percent since we moved them to the rooftop terrace.\\nM: That''s fantastic news! Employees have also been asking whether we could add a nutrition workshop next month.\\nW: I know a registered dietitian who gives corporate talks. Let''s check if she has availability on a Tuesday.\\nM: Perfect—I''ll verify the wellness budget and confirm we can cover her speaker honorarium.","translation":"Nữ: Tỷ lệ tham gia lớp yoga buổi trưa tăng 40% từ khi chuyển lên sân thượng.\\nNam: Nhân viên cũng muốn thêm hội thảo dinh dưỡng tháng sau. Tôi sẽ kiểm tra ngân sách phúc lợi để chi trả thù lao diễn giả.","vocabulary":[]}', 79, NOW(), NOW());
INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(81, 'SINGLE_CHOICE', 'Part 3 G11 Q2: What new activity are employees requesting?', 2, '{"text":"What new activity are employees requesting?","options":[{"key":"A","text":"(A) A running club"},{"key":"B","text":"(B) A nutrition workshop"},{"key":"C","text":"(C) A meditation app"},{"key":"D","text":"(D) Massage chairs"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 11: Discussing quarterly employee wellness program.', 3, '{"clue":"Nhân viên đề xuất thêm một buổi hội thảo dinh dưỡng.","analysis":"Nhân viên đề xuất thêm một buổi hội thảo dinh dưỡng.","transcript":"W: Ben, participation in our lunchtime yoga classes jumped forty percent since we moved them to the rooftop terrace.\\nM: That''s fantastic news! Employees have also been asking whether we could add a nutrition workshop next month.\\nW: I know a registered dietitian who gives corporate talks. Let''s check if she has availability on a Tuesday.\\nM: Perfect—I''ll verify the wellness budget and confirm we can cover her speaker honorarium.","translation":"Nữ: Tỷ lệ tham gia lớp yoga buổi trưa tăng 40% từ khi chuyển lên sân thượng.\\nNam: Nhân viên cũng muốn thêm hội thảo dinh dưỡng tháng sau. Tôi sẽ kiểm tra ngân sách phúc lợi để chi trả thù lao diễn giả.","vocabulary":[]}', 79, NOW(), NOW()),
(82, 'SINGLE_CHOICE', 'Part 3 G11 Q3: What will the man check next?', 3, '{"text":"What will the man check next?","options":[{"key":"A","text":"(A) The rooftop weather forecast"},{"key":"B","text":"(B) The wellness program budget"},{"key":"C","text":"(C) The dietitian''s resume"},{"key":"D","text":"(D) Room capacity"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 11: Discussing quarterly employee wellness program.', 3, '{"clue":"Anh sẽ kiểm tra ngân sách phúc lợi cho thù lao diễn giả.","analysis":"Anh sẽ kiểm tra ngân sách phúc lợi cho thù lao diễn giả.","transcript":"W: Ben, participation in our lunchtime yoga classes jumped forty percent since we moved them to the rooftop terrace.\\nM: That''s fantastic news! Employees have also been asking whether we could add a nutrition workshop next month.\\nW: I know a registered dietitian who gives corporate talks. Let''s check if she has availability on a Tuesday.\\nM: Perfect—I''ll verify the wellness budget and confirm we can cover her speaker honorarium.","translation":"Nữ: Tỷ lệ tham gia lớp yoga buổi trưa tăng 40% từ khi chuyển lên sân thượng.\\nNam: Nhân viên cũng muốn thêm hội thảo dinh dưỡng tháng sau. Tôi sẽ kiểm tra ngân sách phúc lợi để chi trả thù lao diễn giả.","vocabulary":[]}', 79, NOW(), NOW()),
(83, 'SINGLE_CHOICE', 'Part 3 Conv 12: Resolving a billing discrepancy with a vendor', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 12: Resolving a billing discrepancy with a vendor).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 4, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 12.', 3, '{"transcript":"M: Accounts Payable, this is Liam speaking.\\nW: Hi Liam, it''s Nora from Summit Cleaning Services. We received payment for Invoice 882, but it was short by three hundred dollars.\\nM: Let me pull that up... Oh, I see why. The extra carpet shampooing on the fourth floor wasn''t listed on the original purchase order.\\nW: We got written approval for that from Ms. Gomez on May 4. I can email you the signed addendum right now.","translation":"Nữ: Tôi là Nora từ Summit Cleaning. Thanh toán hóa đơn 882 bị thiếu 300 đô.\\nNam: Vì hạng mục giặt thảm tầng 4 không có trong đơn đặt hàng gốc.\\nNữ: Bà Gomez đã ký duyệt phụ lục ngày 4/5, tôi sẽ gửi email bản ký ngay.","analysis":"Nữ: Tôi là Nora từ Summit Cleaning. Thanh toán hóa đơn 882 bị thiếu 300 đô.\\nNam: Vì hạng mục giặt thảm tầng 4 không có trong đơn đặt hàng gốc.\\nNữ: Bà Gomez đã ký duyệt phụ lục ngày 4/5, tôi sẽ gửi email bản ký ngay.","vocabulary":[]}', NULL, NOW(), NOW()),
(84, 'SINGLE_CHOICE', 'Part 3 G12 Q1: Why is Nora calling Liam?', 1, '{"text":"Why is Nora calling Liam?","options":[{"key":"A","text":"(A) To schedule carpet cleaning"},{"key":"B","text":"(B) To resolve a short payment on an invoice"},{"key":"C","text":"(C) To renew an annual contract"},{"key":"D","text":"(D) To update bank account details"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 12: Resolving a billing discrepancy with a vendor.', 3, '{"clue":"Hóa đơn 882 bị thanh toán thiếu 300 đô la.","analysis":"Hóa đơn 882 bị thanh toán thiếu 300 đô la.","transcript":"M: Accounts Payable, this is Liam speaking.\\nW: Hi Liam, it''s Nora from Summit Cleaning Services. We received payment for Invoice 882, but it was short by three hundred dollars.\\nM: Let me pull that up... Oh, I see why. The extra carpet shampooing on the fourth floor wasn''t listed on the original purchase order.\\nW: We got written approval for that from Ms. Gomez on May 4. I can email you the signed addendum right now.","translation":"Nữ: Tôi là Nora từ Summit Cleaning. Thanh toán hóa đơn 882 bị thiếu 300 đô.\\nNam: Vì hạng mục giặt thảm tầng 4 không có trong đơn đặt hàng gốc.\\nNữ: Bà Gomez đã ký duyệt phụ lục ngày 4/5, tôi sẽ gửi email bản ký ngay.","vocabulary":[]}', 83, NOW(), NOW()),
(85, 'SINGLE_CHOICE', 'Part 3 G12 Q2: Why wasn''t the full amount paid initially?', 2, '{"text":"Why wasn''t the full amount paid initially?","options":[{"key":"A","text":"(A) The cleaning was incomplete"},{"key":"B","text":"(B) Carpet shampooing was not on the original PO"},{"key":"C","text":"(C) The invoice was overdue"},{"key":"D","text":"(D) A tax rate changed"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 12: Resolving a billing discrepancy with a vendor.', 3, '{"clue":"Dịch vụ giặt thảm không nằm trên đơn đặt hàng gốc.","analysis":"Dịch vụ giặt thảm không nằm trên đơn đặt hàng gốc.","transcript":"M: Accounts Payable, this is Liam speaking.\\nW: Hi Liam, it''s Nora from Summit Cleaning Services. We received payment for Invoice 882, but it was short by three hundred dollars.\\nM: Let me pull that up... Oh, I see why. The extra carpet shampooing on the fourth floor wasn''t listed on the original purchase order.\\nW: We got written approval for that from Ms. Gomez on May 4. I can email you the signed addendum right now.","translation":"Nữ: Tôi là Nora từ Summit Cleaning. Thanh toán hóa đơn 882 bị thiếu 300 đô.\\nNam: Vì hạng mục giặt thảm tầng 4 không có trong đơn đặt hàng gốc.\\nNữ: Bà Gomez đã ký duyệt phụ lục ngày 4/5, tôi sẽ gửi email bản ký ngay.","vocabulary":[]}', 83, NOW(), NOW()),
(86, 'SINGLE_CHOICE', 'Part 3 G12 Q3: What will Nora send to Liam?', 3, '{"text":"What will Nora send to Liam?","options":[{"key":"A","text":"(A) A revised service catalog"},{"key":"B","text":"(B) A signed approval addendum"},{"key":"C","text":"(C) Photos of the fourth floor"},{"key":"D","text":"(D) A credit memo"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 12: Resolving a billing discrepancy with a vendor.', 3, '{"clue":"Cô sẽ gửi email bản phụ lục đã có chữ ký duyệt của bà Gomez.","analysis":"Cô sẽ gửi email bản phụ lục đã có chữ ký duyệt của bà Gomez.","transcript":"M: Accounts Payable, this is Liam speaking.\\nW: Hi Liam, it''s Nora from Summit Cleaning Services. We received payment for Invoice 882, but it was short by three hundred dollars.\\nM: Let me pull that up... Oh, I see why. The extra carpet shampooing on the fourth floor wasn''t listed on the original purchase order.\\nW: We got written approval for that from Ms. Gomez on May 4. I can email you the signed addendum right now.","translation":"Nữ: Tôi là Nora từ Summit Cleaning. Thanh toán hóa đơn 882 bị thiếu 300 đô.\\nNam: Vì hạng mục giặt thảm tầng 4 không có trong đơn đặt hàng gốc.\\nNữ: Bà Gomez đã ký duyệt phụ lục ngày 4/5, tôi sẽ gửi email bản ký ngay.","vocabulary":[]}', 83, NOW(), NOW()),
(87, 'SINGLE_CHOICE', 'Part 3 Conv 13: Preparing for a museum architecture exhibit', NULL, '{"text":"Questions refer to the following conversation (Part 3 Conv 13: Preparing for a museum architecture exhibit).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the workplace conversation and answer the three questions."}', '{"info":"Parent conversation stimulus"}', 4, 'LISTENING', 'Chùm hội thoại TOEIC Part 3 số 13.', 3, '{"transcript":"W: Did the lighting crew finish mounting the spotlights in the East Gallery for Friday''s architecture exhibit?\\nM: Almost—they''re calibrating the warm LEDs over the scale models so the paper blueprints don''t fade.\\nW: Good call. And have the audio guide headsets been loaded with the bilingual commentary?\\nM: Yes, both English and Japanese tracks are ready, and the front desk has fifty charged units.","translation":"Nữ: Đội ánh sáng lắp xong đèn ở phòng trưng bày Đông cho triển lãm kiến trúc thứ Sáu chưa?\\nNam: Họ đang chỉnh đèn LED để không làm phai màu bản vẽ giấy. Tai nghe thuyết minh song ngữ Anh - Nhật cũng đã nạp xong 50 bộ tại quầy lễ tân.","analysis":"Nữ: Đội ánh sáng lắp xong đèn ở phòng trưng bày Đông cho triển lãm kiến trúc thứ Sáu chưa?\\nNam: Họ đang chỉnh đèn LED để không làm phai màu bản vẽ giấy. Tai nghe thuyết minh song ngữ Anh - Nhật cũng đã nạp xong 50 bộ tại quầy lễ tân.","vocabulary":[]}', NULL, NOW(), NOW()),
(88, 'SINGLE_CHOICE', 'Part 3 G13 Q1: What type of event are the speakers preparing for?', 1, '{"text":"What type of event are the speakers preparing for?","options":[{"key":"A","text":"(A) A film festival"},{"key":"B","text":"(B) An architecture exhibition"},{"key":"C","text":"(C) A photography auction"},{"key":"D","text":"(D) A book signing"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 3 Conv 13: Preparing for a museum architecture exhibit.', 3, '{"clue":"Họ chuẩn bị cho ''Friday''s architecture exhibit''.","analysis":"Họ chuẩn bị cho ''Friday''s architecture exhibit''.","transcript":"W: Did the lighting crew finish mounting the spotlights in the East Gallery for Friday''s architecture exhibit?\\nM: Almost—they''re calibrating the warm LEDs over the scale models so the paper blueprints don''t fade.\\nW: Good call. And have the audio guide headsets been loaded with the bilingual commentary?\\nM: Yes, both English and Japanese tracks are ready, and the front desk has fifty charged units.","translation":"Nữ: Đội ánh sáng lắp xong đèn ở phòng trưng bày Đông cho triển lãm kiến trúc thứ Sáu chưa?\\nNam: Họ đang chỉnh đèn LED để không làm phai màu bản vẽ giấy. Tai nghe thuyết minh song ngữ Anh - Nhật cũng đã nạp xong 50 bộ tại quầy lễ tân.","vocabulary":[]}', 87, NOW(), NOW()),
(89, 'SINGLE_CHOICE', 'Part 3 G13 Q2: Why are technicians calibrating the LEDs carefully?', 2, '{"text":"Why are technicians calibrating the LEDs carefully?","options":[{"key":"A","text":"(A) To reduce electricity bills"},{"key":"B","text":"(B) To prevent paper blueprints from fading"},{"key":"C","text":"(C) To brighten the gift shop"},{"key":"D","text":"(D) To sync with video screens"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 3 Conv 13: Preparing for a museum architecture exhibit.', 3, '{"clue":"Hiệu chỉnh đèn LED ấm để tránh làm phai màu các bản vẽ giấy.","analysis":"Hiệu chỉnh đèn LED ấm để tránh làm phai màu các bản vẽ giấy.","transcript":"W: Did the lighting crew finish mounting the spotlights in the East Gallery for Friday''s architecture exhibit?\\nM: Almost—they''re calibrating the warm LEDs over the scale models so the paper blueprints don''t fade.\\nW: Good call. And have the audio guide headsets been loaded with the bilingual commentary?\\nM: Yes, both English and Japanese tracks are ready, and the front desk has fifty charged units.","translation":"Nữ: Đội ánh sáng lắp xong đèn ở phòng trưng bày Đông cho triển lãm kiến trúc thứ Sáu chưa?\\nNam: Họ đang chỉnh đèn LED để không làm phai màu bản vẽ giấy. Tai nghe thuyết minh song ngữ Anh - Nhật cũng đã nạp xong 50 bộ tại quầy lễ tân.","vocabulary":[]}', 87, NOW(), NOW()),
(90, 'SINGLE_CHOICE', 'Part 3 G13 Q3: What is ready at the front desk?', 3, '{"text":"What is ready at the front desk?","options":[{"key":"A","text":"(A) Printed exhibition catalogs"},{"key":"B","text":"(B) Fifty charged bilingual audio headsets"},{"key":"C","text":"(C) VIP entry wristbands"},{"key":"D","text":"(D) Donation boxes"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 3 Conv 13: Preparing for a museum architecture exhibit.', 3, '{"clue":"50 bộ tai nghe thuyết minh song ngữ Anh-Nhật đã sạc đầy tại quầy.","analysis":"50 bộ tai nghe thuyết minh song ngữ Anh-Nhật đã sạc đầy tại quầy.","transcript":"W: Did the lighting crew finish mounting the spotlights in the East Gallery for Friday''s architecture exhibit?\\nM: Almost—they''re calibrating the warm LEDs over the scale models so the paper blueprints don''t fade.\\nW: Good call. And have the audio guide headsets been loaded with the bilingual commentary?\\nM: Yes, both English and Japanese tracks are ready, and the front desk has fifty charged units.","translation":"Nữ: Đội ánh sáng lắp xong đèn ở phòng trưng bày Đông cho triển lãm kiến trúc thứ Sáu chưa?\\nNam: Họ đang chỉnh đèn LED để không làm phai màu bản vẽ giấy. Tai nghe thuyết minh song ngữ Anh - Nhật cũng đã nạp xong 50 bộ tại quầy lễ tân.","vocabulary":[]}', 87, NOW(), NOW()),
(91, 'SINGLE_CHOICE', 'Part 4 Talk 1: Airport departure delay announcement', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 1: Airport departure delay announcement).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 3, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 1.', 4, '{"transcript":"Attention all passengers booked on Pacific Sky Flight 402 to Seattle. Due to severe thunderstorms along our flight path, departure has been pushed back from 3:15 P.M. to 5:30 P.M. Passengers traveling with young children or requiring special assistance may approach Gate 18 to receive complimentary meal vouchers valid at any terminal dining outlet.","translation":"Thông báo hành khách chuyến bay Pacific Sky 402 đi Seattle: do giông bão dữ dội, giờ khởi hành lùi từ 3:15 chiều sang 5:30 chiều. Hành khách đi cùng trẻ nhỏ hoặc cần hỗ trợ đặc biệt đến Cổng 18 nhận phiếu ăn miễn phí.","analysis":"Thông báo hành khách chuyến bay Pacific Sky 402 đi Seattle: do giông bão dữ dội, giờ khởi hành lùi từ 3:15 chiều sang 5:30 chiều. Hành khách đi cùng trẻ nhỏ hoặc cần hỗ trợ đặc biệt đến Cổng 18 nhận phiếu ăn miễn phí.","vocabulary":[]}', NULL, NOW(), NOW()),
(92, 'SINGLE_CHOICE', 'Part 4 G1 Q1: Why has Flight 402 been delayed?', 1, '{"text":"Why has Flight 402 been delayed?","options":[{"key":"A","text":"(A) Engine inspection"},{"key":"B","text":"(B) Severe weather conditions"},{"key":"C","text":"(C) Crew scheduling conflict"},{"key":"D","text":"(D) Runway construction"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 1: Airport departure delay announcement.', 4, '{"clue":"Nguyên nhân là ''severe thunderstorms along our flight path''.","analysis":"Nguyên nhân là ''severe thunderstorms along our flight path''.","transcript":"Attention all passengers booked on Pacific Sky Flight 402 to Seattle. Due to severe thunderstorms along our flight path, departure has been pushed back from 3:15 P.M. to 5:30 P.M. Passengers traveling with young children or requiring special assistance may approach Gate 18 to receive complimentary meal vouchers valid at any terminal dining outlet.","translation":"Thông báo hành khách chuyến bay Pacific Sky 402 đi Seattle: do giông bão dữ dội, giờ khởi hành lùi từ 3:15 chiều sang 5:30 chiều. Hành khách đi cùng trẻ nhỏ hoặc cần hỗ trợ đặc biệt đến Cổng 18 nhận phiếu ăn miễn phí.","vocabulary":[]}', 91, NOW(), NOW()),
(93, 'SINGLE_CHOICE', 'Part 4 G1 Q2: What is the revised departure time?', 2, '{"text":"What is the revised departure time?","options":[{"key":"A","text":"(A) 3:15 P.M."},{"key":"B","text":"(B) 4:30 P.M."},{"key":"C","text":"(C) 5:30 P.M."},{"key":"D","text":"(D) 6:15 P.M."}]}', '{"selected":"C","key":"C"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 1: Airport departure delay announcement.', 4, '{"clue":"Giờ bay mới được dời sang 5:30 chiều.","analysis":"Giờ bay mới được dời sang 5:30 chiều.","transcript":"Attention all passengers booked on Pacific Sky Flight 402 to Seattle. Due to severe thunderstorms along our flight path, departure has been pushed back from 3:15 P.M. to 5:30 P.M. Passengers traveling with young children or requiring special assistance may approach Gate 18 to receive complimentary meal vouchers valid at any terminal dining outlet.","translation":"Thông báo hành khách chuyến bay Pacific Sky 402 đi Seattle: do giông bão dữ dội, giờ khởi hành lùi từ 3:15 chiều sang 5:30 chiều. Hành khách đi cùng trẻ nhỏ hoặc cần hỗ trợ đặc biệt đến Cổng 18 nhận phiếu ăn miễn phí.","vocabulary":[]}', 91, NOW(), NOW()),
(94, 'SINGLE_CHOICE', 'Part 4 G1 Q3: What can eligible passengers collect at Gate 18?', 3, '{"text":"What can eligible passengers collect at Gate 18?","options":[{"key":"A","text":"(A) Hotel vouchers"},{"key":"B","text":"(B) Complimentary meal vouchers"},{"key":"C","text":"(C) Priority boarding passes"},{"key":"D","text":"(D) Luggage tags"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 1: Airport departure delay announcement.', 4, '{"clue":"Phát phiếu ăn miễn phí (''complimentary meal vouchers'') tại Cổng 18.","analysis":"Phát phiếu ăn miễn phí (''complimentary meal vouchers'') tại Cổng 18.","transcript":"Attention all passengers booked on Pacific Sky Flight 402 to Seattle. Due to severe thunderstorms along our flight path, departure has been pushed back from 3:15 P.M. to 5:30 P.M. Passengers traveling with young children or requiring special assistance may approach Gate 18 to receive complimentary meal vouchers valid at any terminal dining outlet.","translation":"Thông báo hành khách chuyến bay Pacific Sky 402 đi Seattle: do giông bão dữ dội, giờ khởi hành lùi từ 3:15 chiều sang 5:30 chiều. Hành khách đi cùng trẻ nhỏ hoặc cần hỗ trợ đặc biệt đến Cổng 18 nhận phiếu ăn miễn phí.","vocabulary":[]}', 91, NOW(), NOW()),
(95, 'SINGLE_CHOICE', 'Part 4 Talk 2: Voicemail from a dental clinic regarding appointment', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 2: Voicemail from a dental clinic regarding appointment).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 2, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 2.', 4, '{"transcript":"Hello, Mr. Alvarez. This is Clara calling from Bayside Dental Associates to confirm your routine cleaning tomorrow, Wednesday, at 10:30 A.M. Because we recently upgraded our patient intake system, please arrive fifteen minutes early to update your insurance card on our tablet kiosk. If you need to reschedule, call us before 5:00 P.M. today to avoid a cancellation fee.","translation":"Chào anh Alvarez, Clara gọi từ phòng khám nha khoa Bayside xác nhận lịch lấy cao răng 10:30 sáng mai. Vui lòng đến sớm 15 phút cập nhật thẻ bảo hiểm trên máy tính bảng. Nếu đổi lịch hãy gọi trước 5 giờ chiều nay để tránh phí hủy.","analysis":"Chào anh Alvarez, Clara gọi từ phòng khám nha khoa Bayside xác nhận lịch lấy cao răng 10:30 sáng mai. Vui lòng đến sớm 15 phút cập nhật thẻ bảo hiểm trên máy tính bảng. Nếu đổi lịch hãy gọi trước 5 giờ chiều nay để tránh phí hủy.","vocabulary":[]}', NULL, NOW(), NOW()),
(96, 'SINGLE_CHOICE', 'Part 4 G2 Q1: What is the purpose of the message?', 1, '{"text":"What is the purpose of the message?","options":[{"key":"A","text":"(A) To cancel a dental procedure"},{"key":"B","text":"(B) To confirm an upcoming appointment"},{"key":"C","text":"(C) To collect an overdue bill"},{"key":"D","text":"(D) To advertise teeth whitening"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 2: Voicemail from a dental clinic regarding appointment.', 4, '{"clue":"Lời nhắn gọi để xác nhận lịch khám định kỳ sáng thứ Tư.","analysis":"Lời nhắn gọi để xác nhận lịch khám định kỳ sáng thứ Tư.","transcript":"Hello, Mr. Alvarez. This is Clara calling from Bayside Dental Associates to confirm your routine cleaning tomorrow, Wednesday, at 10:30 A.M. Because we recently upgraded our patient intake system, please arrive fifteen minutes early to update your insurance card on our tablet kiosk. If you need to reschedule, call us before 5:00 P.M. today to avoid a cancellation fee.","translation":"Chào anh Alvarez, Clara gọi từ phòng khám nha khoa Bayside xác nhận lịch lấy cao răng 10:30 sáng mai. Vui lòng đến sớm 15 phút cập nhật thẻ bảo hiểm trên máy tính bảng. Nếu đổi lịch hãy gọi trước 5 giờ chiều nay để tránh phí hủy.","vocabulary":[]}', 95, NOW(), NOW()),
(97, 'SINGLE_CHOICE', 'Part 4 G2 Q2: Why is the listener asked to arrive fifteen minutes early?', 2, '{"text":"Why is the listener asked to arrive fifteen minutes early?","options":[{"key":"A","text":"(A) To meet a new dentist"},{"key":"B","text":"(B) To update insurance details on a kiosk"},{"key":"C","text":"(C) To complete X-ray scans"},{"key":"D","text":"(D) Because parking is limited"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 2: Voicemail from a dental clinic regarding appointment.', 4, '{"clue":"Đến sớm 15 phút để cập nhật thẻ bảo hiểm trên hệ thống mới.","analysis":"Đến sớm 15 phút để cập nhật thẻ bảo hiểm trên hệ thống mới.","transcript":"Hello, Mr. Alvarez. This is Clara calling from Bayside Dental Associates to confirm your routine cleaning tomorrow, Wednesday, at 10:30 A.M. Because we recently upgraded our patient intake system, please arrive fifteen minutes early to update your insurance card on our tablet kiosk. If you need to reschedule, call us before 5:00 P.M. today to avoid a cancellation fee.","translation":"Chào anh Alvarez, Clara gọi từ phòng khám nha khoa Bayside xác nhận lịch lấy cao răng 10:30 sáng mai. Vui lòng đến sớm 15 phút cập nhật thẻ bảo hiểm trên máy tính bảng. Nếu đổi lịch hãy gọi trước 5 giờ chiều nay để tránh phí hủy.","vocabulary":[]}', 95, NOW(), NOW()),
(98, 'SINGLE_CHOICE', 'Part 4 G2 Q3: How can the listener avoid a cancellation fee?', 3, '{"text":"How can the listener avoid a cancellation fee?","options":[{"key":"A","text":"(A) By emailing his insurance provider"},{"key":"B","text":"(B) By calling before 5:00 P.M. today"},{"key":"C","text":"(C) By paying online in advance"},{"key":"D","text":"(D) By sending a family member"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 2: Voicemail from a dental clinic regarding appointment.', 4, '{"clue":"Gọi điện báo đổi lịch trước 5 giờ chiều hôm nay.","analysis":"Gọi điện báo đổi lịch trước 5 giờ chiều hôm nay.","transcript":"Hello, Mr. Alvarez. This is Clara calling from Bayside Dental Associates to confirm your routine cleaning tomorrow, Wednesday, at 10:30 A.M. Because we recently upgraded our patient intake system, please arrive fifteen minutes early to update your insurance card on our tablet kiosk. If you need to reschedule, call us before 5:00 P.M. today to avoid a cancellation fee.","translation":"Chào anh Alvarez, Clara gọi từ phòng khám nha khoa Bayside xác nhận lịch lấy cao răng 10:30 sáng mai. Vui lòng đến sớm 15 phút cập nhật thẻ bảo hiểm trên máy tính bảng. Nếu đổi lịch hãy gọi trước 5 giờ chiều nay để tránh phí hủy.","vocabulary":[]}', 95, NOW(), NOW()),
(99, 'SINGLE_CHOICE', 'Part 4 Talk 3: Department store closing announcement', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 3: Department store closing announcement).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 2, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 3.', 4, '{"transcript":"Good evening, shoppers. Welcome to Heritage Department Store. Please note that our store will be closing in fifteen minutes at 9:00 P.M. All clearance footwear on the third floor is an additional twenty percent off at checkout tonight. Kindly bring your selections to the central cashiers on the ground floor, as upper-level registers are now closed.","translation":"Kính chào quý khách tại Heritage Department Store. Cửa hàng sẽ đóng cửa sau 15 phút nữa lúc 9 giờ tối. Toàn bộ giày giảm giá tầng 3 được giảm thêm 20% tối nay. Vui lòng thanh toán tại quầy trung tâm tầng trệt vì các quầy tầng trên đã đóng.","analysis":"Kính chào quý khách tại Heritage Department Store. Cửa hàng sẽ đóng cửa sau 15 phút nữa lúc 9 giờ tối. Toàn bộ giày giảm giá tầng 3 được giảm thêm 20% tối nay. Vui lòng thanh toán tại quầy trung tâm tầng trệt vì các quầy tầng trên đã đóng.","vocabulary":[]}', NULL, NOW(), NOW()),
(100, 'SINGLE_CHOICE', 'Part 4 G3 Q1: At what time does the store close?', 1, '{"text":"At what time does the store close?","options":[{"key":"A","text":"(A) 8:45 P.M."},{"key":"B","text":"(B) 9:00 P.M."},{"key":"C","text":"(C) 9:15 P.M."},{"key":"D","text":"(D) 10:00 P.M."}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 3: Department store closing announcement.', 4, '{"clue":"Cửa hàng đóng cửa lúc 9:00 P.M.","analysis":"Cửa hàng đóng cửa lúc 9:00 P.M.","transcript":"Good evening, shoppers. Welcome to Heritage Department Store. Please note that our store will be closing in fifteen minutes at 9:00 P.M. All clearance footwear on the third floor is an additional twenty percent off at checkout tonight. Kindly bring your selections to the central cashiers on the ground floor, as upper-level registers are now closed.","translation":"Kính chào quý khách tại Heritage Department Store. Cửa hàng sẽ đóng cửa sau 15 phút nữa lúc 9 giờ tối. Toàn bộ giày giảm giá tầng 3 được giảm thêm 20% tối nay. Vui lòng thanh toán tại quầy trung tâm tầng trệt vì các quầy tầng trên đã đóng.","vocabulary":[]}', 99, NOW(), NOW()),
(101, 'SINGLE_CHOICE', 'Part 4 G3 Q2: What promotion is currently offered on the third floor?', 2, '{"text":"What promotion is currently offered on the third floor?","options":[{"key":"A","text":"(A) Buy one coat, get one free"},{"key":"B","text":"(B) An extra 20% off clearance footwear"},{"key":"C","text":"(C) Free gift wrapping"},{"key":"D","text":"(D) Double loyalty points"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 3: Department store closing announcement.', 4, '{"clue":"Giày thanh lý tầng 3 được giảm thêm 20%.","analysis":"Giày thanh lý tầng 3 được giảm thêm 20%.","transcript":"Good evening, shoppers. Welcome to Heritage Department Store. Please note that our store will be closing in fifteen minutes at 9:00 P.M. All clearance footwear on the third floor is an additional twenty percent off at checkout tonight. Kindly bring your selections to the central cashiers on the ground floor, as upper-level registers are now closed.","translation":"Kính chào quý khách tại Heritage Department Store. Cửa hàng sẽ đóng cửa sau 15 phút nữa lúc 9 giờ tối. Toàn bộ giày giảm giá tầng 3 được giảm thêm 20% tối nay. Vui lòng thanh toán tại quầy trung tâm tầng trệt vì các quầy tầng trên đã đóng.","vocabulary":[]}', 99, NOW(), NOW()),
(102, 'SINGLE_CHOICE', 'Part 4 G3 Q3: Where should shoppers pay for their items?', 3, '{"text":"Where should shoppers pay for their items?","options":[{"key":"A","text":"(A) At the third-floor register"},{"key":"B","text":"(B) At the central cashiers on the ground floor"},{"key":"C","text":"(C) At the customer service desk"},{"key":"D","text":"(D) Using the mobile app only"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 3: Department store closing announcement.', 4, '{"clue":"Các quầy tầng trên đã đóng, khách xuống thanh toán ở tầng trệt.","analysis":"Các quầy tầng trên đã đóng, khách xuống thanh toán ở tầng trệt.","transcript":"Good evening, shoppers. Welcome to Heritage Department Store. Please note that our store will be closing in fifteen minutes at 9:00 P.M. All clearance footwear on the third floor is an additional twenty percent off at checkout tonight. Kindly bring your selections to the central cashiers on the ground floor, as upper-level registers are now closed.","translation":"Kính chào quý khách tại Heritage Department Store. Cửa hàng sẽ đóng cửa sau 15 phút nữa lúc 9 giờ tối. Toàn bộ giày giảm giá tầng 3 được giảm thêm 20% tối nay. Vui lòng thanh toán tại quầy trung tâm tầng trệt vì các quầy tầng trên đã đóng.","vocabulary":[]}', 99, NOW(), NOW()),
(103, 'SINGLE_CHOICE', 'Part 4 Talk 4: Radio traffic and commuter rail report', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 4: Radio traffic and commuter rail report).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 3, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 4.', 4, '{"transcript":"This is your 8:00 A.M. Metro Traffic Update. Heavy congestion is building southbound on Highway 101 near Exit 14 after a delivery van broke down in the right lane. Tow crews expect to clear the lane within thirty minutes. Commuters heading downtown are advised to take the Blue Line express train, which is running on schedule with extra carriages added for rush hour.","translation":"Bản tin giao thông 8 giờ sáng: Quốc lộ 101 hướng Nam gần lối ra 14 đang ùn tắc nặng do xe tải giao hàng hỏng ở làn phải. Đội cứu hộ dự kiến giải tỏa sau 30 phút. Người đi làm vào trung tâm nên đi tàu nhanh tuyến Blue Line đang tăng cường toa.","analysis":"Bản tin giao thông 8 giờ sáng: Quốc lộ 101 hướng Nam gần lối ra 14 đang ùn tắc nặng do xe tải giao hàng hỏng ở làn phải. Đội cứu hộ dự kiến giải tỏa sau 30 phút. Người đi làm vào trung tâm nên đi tàu nhanh tuyến Blue Line đang tăng cường toa.","vocabulary":[]}', NULL, NOW(), NOW()),
(104, 'SINGLE_CHOICE', 'Part 4 G4 Q1: What caused the congestion on Highway 101?', 1, '{"text":"What caused the congestion on Highway 101?","options":[{"key":"A","text":"(A) Road resurfacing"},{"key":"B","text":"(B) A broken-down delivery van"},{"key":"C","text":"(C) A marathon race"},{"key":"D","text":"(D) Flooding near a tunnel"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 4: Radio traffic and commuter rail report.', 4, '{"clue":"Một xe tải giao hàng bị hỏng ở làn bên phải.","analysis":"Một xe tải giao hàng bị hỏng ở làn bên phải.","transcript":"This is your 8:00 A.M. Metro Traffic Update. Heavy congestion is building southbound on Highway 101 near Exit 14 after a delivery van broke down in the right lane. Tow crews expect to clear the lane within thirty minutes. Commuters heading downtown are advised to take the Blue Line express train, which is running on schedule with extra carriages added for rush hour.","translation":"Bản tin giao thông 8 giờ sáng: Quốc lộ 101 hướng Nam gần lối ra 14 đang ùn tắc nặng do xe tải giao hàng hỏng ở làn phải. Đội cứu hộ dự kiến giải tỏa sau 30 phút. Người đi làm vào trung tâm nên đi tàu nhanh tuyến Blue Line đang tăng cường toa.","vocabulary":[]}', 103, NOW(), NOW()),
(105, 'SINGLE_CHOICE', 'Part 4 G4 Q2: How soon should the right lane reopen?', 2, '{"text":"How soon should the right lane reopen?","options":[{"key":"A","text":"(A) In ten minutes"},{"key":"B","text":"(B) In thirty minutes"},{"key":"C","text":"(C) In two hours"},{"key":"D","text":"(D) Tomorrow morning"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 4: Radio traffic and commuter rail report.', 4, '{"clue":"Đội cứu hộ dự kiến dọn xong trong vòng 30 phút.","analysis":"Đội cứu hộ dự kiến dọn xong trong vòng 30 phút.","transcript":"This is your 8:00 A.M. Metro Traffic Update. Heavy congestion is building southbound on Highway 101 near Exit 14 after a delivery van broke down in the right lane. Tow crews expect to clear the lane within thirty minutes. Commuters heading downtown are advised to take the Blue Line express train, which is running on schedule with extra carriages added for rush hour.","translation":"Bản tin giao thông 8 giờ sáng: Quốc lộ 101 hướng Nam gần lối ra 14 đang ùn tắc nặng do xe tải giao hàng hỏng ở làn phải. Đội cứu hộ dự kiến giải tỏa sau 30 phút. Người đi làm vào trung tâm nên đi tàu nhanh tuyến Blue Line đang tăng cường toa.","vocabulary":[]}', 103, NOW(), NOW()),
(106, 'SINGLE_CHOICE', 'Part 4 G4 Q3: What alternative does the announcer recommend?', 3, '{"text":"What alternative does the announcer recommend?","options":[{"key":"A","text":"(A) Taking Highway 280"},{"key":"B","text":"(B) Riding the Blue Line express train"},{"key":"C","text":"(C) Using the river ferry"},{"key":"D","text":"(D) Working remotely"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 4: Radio traffic and commuter rail report.', 4, '{"clue":"Khuyên đi tàu nhanh Blue Line đang chạy đúng giờ và có thêm toa.","analysis":"Khuyên đi tàu nhanh Blue Line đang chạy đúng giờ và có thêm toa.","transcript":"This is your 8:00 A.M. Metro Traffic Update. Heavy congestion is building southbound on Highway 101 near Exit 14 after a delivery van broke down in the right lane. Tow crews expect to clear the lane within thirty minutes. Commuters heading downtown are advised to take the Blue Line express train, which is running on schedule with extra carriages added for rush hour.","translation":"Bản tin giao thông 8 giờ sáng: Quốc lộ 101 hướng Nam gần lối ra 14 đang ùn tắc nặng do xe tải giao hàng hỏng ở làn phải. Đội cứu hộ dự kiến giải tỏa sau 30 phút. Người đi làm vào trung tâm nên đi tàu nhanh tuyến Blue Line đang tăng cường toa.","vocabulary":[]}', 103, NOW(), NOW()),
(107, 'SINGLE_CHOICE', 'Part 4 Talk 5: Factory tour safety briefing', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 5: Factory tour safety briefing).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 3, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 5.', 4, '{"transcript":"Welcome to SolarEdge Assembly Plant. Before we step onto the production floor, please put on the protective eyewear and reflective vests placed on the bench behind you. Photography is strictly prohibited inside the robotics bay to protect proprietary manufacturing designs. However, you are welcome to take photos in the main exhibition hall at the end of our forty-five-minute tour.","translation":"Chào mừng đến nhà máy lắp ráp SolarEdge. Trước khi vào xưởng sản xuất, vui lòng đeo kính bảo hộ và áo phản quang. Cấm tuyệt đối chụp ảnh trong khu robot để bảo mật công nghệ, nhưng có thể chụp ảnh tại sảnh trưng bày cuối chuyến tham quan 45 phút.","analysis":"Chào mừng đến nhà máy lắp ráp SolarEdge. Trước khi vào xưởng sản xuất, vui lòng đeo kính bảo hộ và áo phản quang. Cấm tuyệt đối chụp ảnh trong khu robot để bảo mật công nghệ, nhưng có thể chụp ảnh tại sảnh trưng bày cuối chuyến tham quan 45 phút.","vocabulary":[]}', NULL, NOW(), NOW()),
(108, 'SINGLE_CHOICE', 'Part 4 G5 Q1: What must visitors wear before entering the production floor?', 1, '{"text":"What must visitors wear before entering the production floor?","options":[{"key":"A","text":"(A) Earplugs and gloves"},{"key":"B","text":"(B) Protective eyewear and reflective vests"},{"key":"C","text":"(C) Steel-toed boots"},{"key":"D","text":"(D) Visitor lanyards only"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 5: Factory tour safety briefing.', 4, '{"clue":"Yêu cầu đeo kính bảo hộ và áo gile phản quang.","analysis":"Yêu cầu đeo kính bảo hộ và áo gile phản quang.","transcript":"Welcome to SolarEdge Assembly Plant. Before we step onto the production floor, please put on the protective eyewear and reflective vests placed on the bench behind you. Photography is strictly prohibited inside the robotics bay to protect proprietary manufacturing designs. However, you are welcome to take photos in the main exhibition hall at the end of our forty-five-minute tour.","translation":"Chào mừng đến nhà máy lắp ráp SolarEdge. Trước khi vào xưởng sản xuất, vui lòng đeo kính bảo hộ và áo phản quang. Cấm tuyệt đối chụp ảnh trong khu robot để bảo mật công nghệ, nhưng có thể chụp ảnh tại sảnh trưng bày cuối chuyến tham quan 45 phút.","vocabulary":[]}', 107, NOW(), NOW()),
(109, 'SINGLE_CHOICE', 'Part 4 G5 Q2: Why is photography forbidden in the robotics bay?', 2, '{"text":"Why is photography forbidden in the robotics bay?","options":[{"key":"A","text":"(A) Flash disturbs sensors"},{"key":"B","text":"(B) To protect proprietary designs"},{"key":"C","text":"(C) Lighting is insufficient"},{"key":"D","text":"(D) Workers requested privacy"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 5: Factory tour safety briefing.', 4, '{"clue":"Để bảo vệ bản quyền thiết kế sản xuất độc quyền.","analysis":"Để bảo vệ bản quyền thiết kế sản xuất độc quyền.","transcript":"Welcome to SolarEdge Assembly Plant. Before we step onto the production floor, please put on the protective eyewear and reflective vests placed on the bench behind you. Photography is strictly prohibited inside the robotics bay to protect proprietary manufacturing designs. However, you are welcome to take photos in the main exhibition hall at the end of our forty-five-minute tour.","translation":"Chào mừng đến nhà máy lắp ráp SolarEdge. Trước khi vào xưởng sản xuất, vui lòng đeo kính bảo hộ và áo phản quang. Cấm tuyệt đối chụp ảnh trong khu robot để bảo mật công nghệ, nhưng có thể chụp ảnh tại sảnh trưng bày cuối chuyến tham quan 45 phút.","vocabulary":[]}', 107, NOW(), NOW()),
(110, 'SINGLE_CHOICE', 'Part 4 G5 Q3: Where are visitors allowed to take pictures?', 3, '{"text":"Where are visitors allowed to take pictures?","options":[{"key":"A","text":"(A) In the main exhibition hall"},{"key":"B","text":"(B) Near the loading dock"},{"key":"C","text":"(C) Inside the quality lab"},{"key":"D","text":"(D) On the assembly line"}]}', '{"selected":"A","key":"A"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 5: Factory tour safety briefing.', 4, '{"clue":"Được phép chụp ảnh tại sảnh trưng bày chính (''main exhibition hall'').","analysis":"Được phép chụp ảnh tại sảnh trưng bày chính (''main exhibition hall'').","transcript":"Welcome to SolarEdge Assembly Plant. Before we step onto the production floor, please put on the protective eyewear and reflective vests placed on the bench behind you. Photography is strictly prohibited inside the robotics bay to protect proprietary manufacturing designs. However, you are welcome to take photos in the main exhibition hall at the end of our forty-five-minute tour.","translation":"Chào mừng đến nhà máy lắp ráp SolarEdge. Trước khi vào xưởng sản xuất, vui lòng đeo kính bảo hộ và áo phản quang. Cấm tuyệt đối chụp ảnh trong khu robot để bảo mật công nghệ, nhưng có thể chụp ảnh tại sảnh trưng bày cuối chuyến tham quan 45 phút.","vocabulary":[]}', 107, NOW(), NOW()),
(111, 'SINGLE_CHOICE', 'Part 4 Talk 6: Voicemail from an IT vendor about software license', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 6: Voicemail from an IT vendor about software license).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 3, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 6.', 4, '{"transcript":"Hi Ms. Park, this is Owen from CloudSync Solutions. I''m calling because your organization''s annual 150-seat enterprise subscription is scheduled to auto-renew on July 1. I noticed your team recently added twenty new remote staff, so I wanted to let you know we can lock in last year''s per-seat discount if you upgrade your license tier before June 25. Call me back at extension 412.","translation":"Chào cô Park, Owen từ CloudSync Solutions gọi báo gói bản quyền 150 người dùng sẽ tự gia hạn ngày 1/7. Nếu nâng cấp thêm 20 suất trước 25/6 sẽ được giữ nguyên mức chiết khấu năm ngoái.","analysis":"Chào cô Park, Owen từ CloudSync Solutions gọi báo gói bản quyền 150 người dùng sẽ tự gia hạn ngày 1/7. Nếu nâng cấp thêm 20 suất trước 25/6 sẽ được giữ nguyên mức chiết khấu năm ngoái.","vocabulary":[]}', NULL, NOW(), NOW()),
(112, 'SINGLE_CHOICE', 'Part 4 G6 Q1: When is the current subscription set to renew?', 1, '{"text":"When is the current subscription set to renew?","options":[{"key":"A","text":"(A) June 25"},{"key":"B","text":"(B) July 1"},{"key":"C","text":"(C) July 15"},{"key":"D","text":"(D) August 1"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 6: Voicemail from an IT vendor about software license.', 4, '{"clue":"Gói hiện tại tự động gia hạn vào ngày 1 tháng 7.","analysis":"Gói hiện tại tự động gia hạn vào ngày 1 tháng 7.","transcript":"Hi Ms. Park, this is Owen from CloudSync Solutions. I''m calling because your organization''s annual 150-seat enterprise subscription is scheduled to auto-renew on July 1. I noticed your team recently added twenty new remote staff, so I wanted to let you know we can lock in last year''s per-seat discount if you upgrade your license tier before June 25. Call me back at extension 412.","translation":"Chào cô Park, Owen từ CloudSync Solutions gọi báo gói bản quyền 150 người dùng sẽ tự gia hạn ngày 1/7. Nếu nâng cấp thêm 20 suất trước 25/6 sẽ được giữ nguyên mức chiết khấu năm ngoái.","vocabulary":[]}', 111, NOW(), NOW()),
(113, 'SINGLE_CHOICE', 'Part 4 G6 Q2: Why is Owen contacting Ms. Park?', 2, '{"text":"Why is Owen contacting Ms. Park?","options":[{"key":"A","text":"(A) To report a security breach"},{"key":"B","text":"(B) To offer a discount on upgrading license seats"},{"key":"C","text":"(C) To schedule server downtime"},{"key":"D","text":"(D) To collect an unpaid invoice"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 6: Voicemail from an IT vendor about software license.', 4, '{"clue":"Anh gọi để giữ giá chiết khấu khi nâng cấp thêm suất bản quyền.","analysis":"Anh gọi để giữ giá chiết khấu khi nâng cấp thêm suất bản quyền.","transcript":"Hi Ms. Park, this is Owen from CloudSync Solutions. I''m calling because your organization''s annual 150-seat enterprise subscription is scheduled to auto-renew on July 1. I noticed your team recently added twenty new remote staff, so I wanted to let you know we can lock in last year''s per-seat discount if you upgrade your license tier before June 25. Call me back at extension 412.","translation":"Chào cô Park, Owen từ CloudSync Solutions gọi báo gói bản quyền 150 người dùng sẽ tự gia hạn ngày 1/7. Nếu nâng cấp thêm 20 suất trước 25/6 sẽ được giữ nguyên mức chiết khấu năm ngoái.","vocabulary":[]}', 111, NOW(), NOW()),
(114, 'SINGLE_CHOICE', 'Part 4 G6 Q3: What is the deadline to receive last year''s discount?', 3, '{"text":"What is the deadline to receive last year''s discount?","options":[{"key":"A","text":"(A) June 15"},{"key":"B","text":"(B) June 25"},{"key":"C","text":"(C) July 1"},{"key":"D","text":"(D) July 10"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 6: Voicemail from an IT vendor about software license.', 4, '{"clue":"Hạn chót nâng cấp để giữ giá ưu đãi là trước ngày 25/6.","analysis":"Hạn chót nâng cấp để giữ giá ưu đãi là trước ngày 25/6.","transcript":"Hi Ms. Park, this is Owen from CloudSync Solutions. I''m calling because your organization''s annual 150-seat enterprise subscription is scheduled to auto-renew on July 1. I noticed your team recently added twenty new remote staff, so I wanted to let you know we can lock in last year''s per-seat discount if you upgrade your license tier before June 25. Call me back at extension 412.","translation":"Chào cô Park, Owen từ CloudSync Solutions gọi báo gói bản quyền 150 người dùng sẽ tự gia hạn ngày 1/7. Nếu nâng cấp thêm 20 suất trước 25/6 sẽ được giữ nguyên mức chiết khấu năm ngoái.","vocabulary":[]}', 111, NOW(), NOW()),
(115, 'SINGLE_CHOICE', 'Part 4 Talk 7: Company all-hands announcement on new hybrid policy', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 7: Company all-hands announcement on new hybrid policy).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 3, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 7.', 4, '{"transcript":"Good morning, everyone. Thank you for joining today''s quarterly town hall. Beginning next month, our company will officially adopt a flexible hybrid schedule requiring just two anchor days in the office—Tuesdays and Wednesdays—while allowing remote work on the remaining days. Managers will share team desk assignments this Friday. Additionally, each employee will receive a $400 stipend to upgrade their home office setup.","translation":"Chào toàn thể nhân viên. Từ tháng tới công ty áp dụng lịch làm việc kết hợp linh hoạt: chỉ cần lên văn phòng 2 ngày cố định là thứ Ba và thứ Tư, các ngày còn lại làm từ xa. Mỗi nhân viên được trợ cấp 400 đô nâng cấp góc làm việc tại nhà.","analysis":"Chào toàn thể nhân viên. Từ tháng tới công ty áp dụng lịch làm việc kết hợp linh hoạt: chỉ cần lên văn phòng 2 ngày cố định là thứ Ba và thứ Tư, các ngày còn lại làm từ xa. Mỗi nhân viên được trợ cấp 400 đô nâng cấp góc làm việc tại nhà.","vocabulary":[]}', NULL, NOW(), NOW()),
(116, 'SINGLE_CHOICE', 'Part 4 G7 Q1: Which days will employees be required to work in the office?', 1, '{"text":"Which days will employees be required to work in the office?","options":[{"key":"A","text":"(A) Mondays and Fridays"},{"key":"B","text":"(B) Tuesdays and Wednesdays"},{"key":"C","text":"(C) Wednesdays and Thursdays"},{"key":"D","text":"(D) Mondays through Wednesdays"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 7: Company all-hands announcement on new hybrid policy.', 4, '{"clue":"Hai ngày cố định tại văn phòng là thứ Ba và thứ Tư.","analysis":"Hai ngày cố định tại văn phòng là thứ Ba và thứ Tư.","transcript":"Good morning, everyone. Thank you for joining today''s quarterly town hall. Beginning next month, our company will officially adopt a flexible hybrid schedule requiring just two anchor days in the office—Tuesdays and Wednesdays—while allowing remote work on the remaining days. Managers will share team desk assignments this Friday. Additionally, each employee will receive a $400 stipend to upgrade their home office setup.","translation":"Chào toàn thể nhân viên. Từ tháng tới công ty áp dụng lịch làm việc kết hợp linh hoạt: chỉ cần lên văn phòng 2 ngày cố định là thứ Ba và thứ Tư, các ngày còn lại làm từ xa. Mỗi nhân viên được trợ cấp 400 đô nâng cấp góc làm việc tại nhà.","vocabulary":[]}', 115, NOW(), NOW()),
(117, 'SINGLE_CHOICE', 'Part 4 G7 Q2: When will desk assignments be announced?', 2, '{"text":"When will desk assignments be announced?","options":[{"key":"A","text":"(A) Today"},{"key":"B","text":"(B) This Friday"},{"key":"C","text":"(C) Next Monday"},{"key":"D","text":"(D) Next month"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 7: Company all-hands announcement on new hybrid policy.', 4, '{"clue":"Quản lý sẽ chia sẻ sơ đồ chỗ ngồi vào thứ Sáu tuần này.","analysis":"Quản lý sẽ chia sẻ sơ đồ chỗ ngồi vào thứ Sáu tuần này.","transcript":"Good morning, everyone. Thank you for joining today''s quarterly town hall. Beginning next month, our company will officially adopt a flexible hybrid schedule requiring just two anchor days in the office—Tuesdays and Wednesdays—while allowing remote work on the remaining days. Managers will share team desk assignments this Friday. Additionally, each employee will receive a $400 stipend to upgrade their home office setup.","translation":"Chào toàn thể nhân viên. Từ tháng tới công ty áp dụng lịch làm việc kết hợp linh hoạt: chỉ cần lên văn phòng 2 ngày cố định là thứ Ba và thứ Tư, các ngày còn lại làm từ xa. Mỗi nhân viên được trợ cấp 400 đô nâng cấp góc làm việc tại nhà.","vocabulary":[]}', 115, NOW(), NOW()),
(118, 'SINGLE_CHOICE', 'Part 4 G7 Q3: What financial benefit is being provided?', 3, '{"text":"What financial benefit is being provided?","options":[{"key":"A","text":"(A) Free commuter rail passes"},{"key":"B","text":"(B) A $400 home office stipend"},{"key":"C","text":"(C) A 10% annual bonus"},{"key":"D","text":"(D) Gym membership reimbursement"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 7: Company all-hands announcement on new hybrid policy.', 4, '{"clue":"Khoản hỗ trợ 400 đô nâng cấp thiết bị làm việc tại nhà.","analysis":"Khoản hỗ trợ 400 đô nâng cấp thiết bị làm việc tại nhà.","transcript":"Good morning, everyone. Thank you for joining today''s quarterly town hall. Beginning next month, our company will officially adopt a flexible hybrid schedule requiring just two anchor days in the office—Tuesdays and Wednesdays—while allowing remote work on the remaining days. Managers will share team desk assignments this Friday. Additionally, each employee will receive a $400 stipend to upgrade their home office setup.","translation":"Chào toàn thể nhân viên. Từ tháng tới công ty áp dụng lịch làm việc kết hợp linh hoạt: chỉ cần lên văn phòng 2 ngày cố định là thứ Ba và thứ Tư, các ngày còn lại làm từ xa. Mỗi nhân viên được trợ cấp 400 đô nâng cấp góc làm việc tại nhà.","vocabulary":[]}', 115, NOW(), NOW()),
(119, 'SINGLE_CHOICE', 'Part 4 Talk 8: Museum guided audio tour introduction', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 8: Museum guided audio tour introduction).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 3, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 8.', 4, '{"transcript":"Welcome to the Maritime Heritage Museum''s audio guide. You are now standing in Gallery One, featuring nineteenth-century wooden trading vessels built along this harbor. Press the green button on your keypad at any time to pause the narration, or enter a three-digit exhibit code to hear detailed stories about individual artifacts. Restrooms and the harbor-view cafe are located on the mezzanine level.","translation":"Chào mừng đến hệ thống thuyết minh Bảo tàng Hàng hải. Quý khách đang ở Phòng 1 trưng bày tàu buôn gỗ thế kỷ 19. Bấm nút xanh để tạm dừng hoặc nhập mã 3 chữ số để nghe chi tiết từng hiện vật. Quán cà phê nhìn ra cảng ở tầng lửng.","analysis":"Chào mừng đến hệ thống thuyết minh Bảo tàng Hàng hải. Quý khách đang ở Phòng 1 trưng bày tàu buôn gỗ thế kỷ 19. Bấm nút xanh để tạm dừng hoặc nhập mã 3 chữ số để nghe chi tiết từng hiện vật. Quán cà phê nhìn ra cảng ở tầng lửng.","vocabulary":[]}', NULL, NOW(), NOW()),
(120, 'SINGLE_CHOICE', 'Part 4 G8 Q1: What is displayed in Gallery One?', 1, '{"text":"What is displayed in Gallery One?","options":[{"key":"A","text":"(A) Modern cruise liners"},{"key":"B","text":"(B) Nineteenth-century wooden trading ships"},{"key":"C","text":"(C) Underwater photography"},{"key":"D","text":"(D) Naval uniforms"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 8: Museum guided audio tour introduction.', 4, '{"clue":"Phòng 1 trưng bày các tàu thương mại bằng gỗ thế kỷ 19.","analysis":"Phòng 1 trưng bày các tàu thương mại bằng gỗ thế kỷ 19.","transcript":"Welcome to the Maritime Heritage Museum''s audio guide. You are now standing in Gallery One, featuring nineteenth-century wooden trading vessels built along this harbor. Press the green button on your keypad at any time to pause the narration, or enter a three-digit exhibit code to hear detailed stories about individual artifacts. Restrooms and the harbor-view cafe are located on the mezzanine level.","translation":"Chào mừng đến hệ thống thuyết minh Bảo tàng Hàng hải. Quý khách đang ở Phòng 1 trưng bày tàu buôn gỗ thế kỷ 19. Bấm nút xanh để tạm dừng hoặc nhập mã 3 chữ số để nghe chi tiết từng hiện vật. Quán cà phê nhìn ra cảng ở tầng lửng.","vocabulary":[]}', 119, NOW(), NOW());
INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(121, 'SINGLE_CHOICE', 'Part 4 G8 Q2: How can visitors hear details about a specific artifact?', 2, '{"text":"How can visitors hear details about a specific artifact?","options":[{"key":"A","text":"(A) By scanning a QR poster"},{"key":"B","text":"(B) By entering a three-digit exhibit code"},{"key":"C","text":"(C) By asking a docent"},{"key":"D","text":"(D) By pressing the red button"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 8: Museum guided audio tour introduction.', 4, '{"clue":"Nhập mã hiện vật gồm 3 chữ số trên bàn phím.","analysis":"Nhập mã hiện vật gồm 3 chữ số trên bàn phím.","transcript":"Welcome to the Maritime Heritage Museum''s audio guide. You are now standing in Gallery One, featuring nineteenth-century wooden trading vessels built along this harbor. Press the green button on your keypad at any time to pause the narration, or enter a three-digit exhibit code to hear detailed stories about individual artifacts. Restrooms and the harbor-view cafe are located on the mezzanine level.","translation":"Chào mừng đến hệ thống thuyết minh Bảo tàng Hàng hải. Quý khách đang ở Phòng 1 trưng bày tàu buôn gỗ thế kỷ 19. Bấm nút xanh để tạm dừng hoặc nhập mã 3 chữ số để nghe chi tiết từng hiện vật. Quán cà phê nhìn ra cảng ở tầng lửng.","vocabulary":[]}', 119, NOW(), NOW()),
(122, 'SINGLE_CHOICE', 'Part 4 G8 Q3: Where is the harbor-view cafe located?', 3, '{"text":"Where is the harbor-view cafe located?","options":[{"key":"A","text":"(A) In the basement"},{"key":"B","text":"(B) On the mezzanine level"},{"key":"C","text":"(C) Next to the gift shop"},{"key":"D","text":"(D) On the rooftop"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 8: Museum guided audio tour introduction.', 4, '{"clue":"Nhà vệ sinh và quán cà phê nằm ở tầng lửng (''mezzanine level'').","analysis":"Nhà vệ sinh và quán cà phê nằm ở tầng lửng (''mezzanine level'').","transcript":"Welcome to the Maritime Heritage Museum''s audio guide. You are now standing in Gallery One, featuring nineteenth-century wooden trading vessels built along this harbor. Press the green button on your keypad at any time to pause the narration, or enter a three-digit exhibit code to hear detailed stories about individual artifacts. Restrooms and the harbor-view cafe are located on the mezzanine level.","translation":"Chào mừng đến hệ thống thuyết minh Bảo tàng Hàng hải. Quý khách đang ở Phòng 1 trưng bày tàu buôn gỗ thế kỷ 19. Bấm nút xanh để tạm dừng hoặc nhập mã 3 chữ số để nghe chi tiết từng hiện vật. Quán cà phê nhìn ra cảng ở tầng lửng.","vocabulary":[]}', 119, NOW(), NOW()),
(123, 'SINGLE_CHOICE', 'Part 4 Talk 9: Business news report on renewable energy merger', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 9: Business news report on renewable energy merger).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 4, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 9.', 4, '{"transcript":"In business news this evening, Verdant Power Corp. announced plans to acquire coastal turbine manufacturer WindCraft Industries in a deal valued at $1.2 billion. Industry analysts say the merger will cut offshore installation costs by nearly eighteen percent over the next three years. Both companies will retain their existing engineering headquarters, and shareholders are expected to vote on the agreement in November.","translation":"Tin kinh tế: Verdant Power công bố thương vụ mua lại hãng sản xuất tua-bin WindCraft trị giá 1,2 tỷ đô la. Các chuyên gia nhận định sáp nhập giúp giảm 18% chi phí lắp đặt ngoài khơi trong 3 năm tới. Cổ đông sẽ bỏ phiếu vào tháng 11.","analysis":"Tin kinh tế: Verdant Power công bố thương vụ mua lại hãng sản xuất tua-bin WindCraft trị giá 1,2 tỷ đô la. Các chuyên gia nhận định sáp nhập giúp giảm 18% chi phí lắp đặt ngoài khơi trong 3 năm tới. Cổ đông sẽ bỏ phiếu vào tháng 11.","vocabulary":[]}', NULL, NOW(), NOW()),
(124, 'SINGLE_CHOICE', 'Part 4 G9 Q1: What is the main topic of the news report?', 1, '{"text":"What is the main topic of the news report?","options":[{"key":"A","text":"(A) A government energy tax"},{"key":"B","text":"(B) A corporate acquisition in renewable energy"},{"key":"C","text":"(C) A new solar battery invention"},{"key":"D","text":"(D) Factory layoffs"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 9: Business news report on renewable energy merger.', 4, '{"clue":"Bản tin về thương vụ Verdant Power mua lại WindCraft Industries.","analysis":"Bản tin về thương vụ Verdant Power mua lại WindCraft Industries.","transcript":"In business news this evening, Verdant Power Corp. announced plans to acquire coastal turbine manufacturer WindCraft Industries in a deal valued at $1.2 billion. Industry analysts say the merger will cut offshore installation costs by nearly eighteen percent over the next three years. Both companies will retain their existing engineering headquarters, and shareholders are expected to vote on the agreement in November.","translation":"Tin kinh tế: Verdant Power công bố thương vụ mua lại hãng sản xuất tua-bin WindCraft trị giá 1,2 tỷ đô la. Các chuyên gia nhận định sáp nhập giúp giảm 18% chi phí lắp đặt ngoài khơi trong 3 năm tới. Cổ đông sẽ bỏ phiếu vào tháng 11.","vocabulary":[]}', 123, NOW(), NOW()),
(125, 'SINGLE_CHOICE', 'Part 4 G9 Q2: What advantage do analysts expect from the deal?', 2, '{"text":"What advantage do analysts expect from the deal?","options":[{"key":"A","text":"(A) Lower offshore installation costs"},{"key":"B","text":"(B) Faster permit approvals"},{"key":"C","text":"(C) Higher electricity tariffs"},{"key":"D","text":"(D) Expansion into aviation"}]}', '{"selected":"A","key":"A"}', 3, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 9: Business news report on renewable energy merger.', 4, '{"clue":"Giảm gần 18% chi phí lắp đặt điện gió ngoài khơi.","analysis":"Giảm gần 18% chi phí lắp đặt điện gió ngoài khơi.","transcript":"In business news this evening, Verdant Power Corp. announced plans to acquire coastal turbine manufacturer WindCraft Industries in a deal valued at $1.2 billion. Industry analysts say the merger will cut offshore installation costs by nearly eighteen percent over the next three years. Both companies will retain their existing engineering headquarters, and shareholders are expected to vote on the agreement in November.","translation":"Tin kinh tế: Verdant Power công bố thương vụ mua lại hãng sản xuất tua-bin WindCraft trị giá 1,2 tỷ đô la. Các chuyên gia nhận định sáp nhập giúp giảm 18% chi phí lắp đặt ngoài khơi trong 3 năm tới. Cổ đông sẽ bỏ phiếu vào tháng 11.","vocabulary":[]}', 123, NOW(), NOW()),
(126, 'SINGLE_CHOICE', 'Part 4 G9 Q3: What is scheduled to happen in November?', 3, '{"text":"What is scheduled to happen in November?","options":[{"key":"A","text":"(A) Construction of a new factory"},{"key":"B","text":"(B) A shareholder vote on the deal"},{"key":"C","text":"(C) Release of quarterly earnings"},{"key":"D","text":"(D) Closing of old headquarters"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 9: Business news report on renewable energy merger.', 4, '{"clue":"Cổ đông sẽ tiến hành bỏ phiếu thông qua thương vụ vào tháng 11.","analysis":"Cổ đông sẽ tiến hành bỏ phiếu thông qua thương vụ vào tháng 11.","transcript":"In business news this evening, Verdant Power Corp. announced plans to acquire coastal turbine manufacturer WindCraft Industries in a deal valued at $1.2 billion. Industry analysts say the merger will cut offshore installation costs by nearly eighteen percent over the next three years. Both companies will retain their existing engineering headquarters, and shareholders are expected to vote on the agreement in November.","translation":"Tin kinh tế: Verdant Power công bố thương vụ mua lại hãng sản xuất tua-bin WindCraft trị giá 1,2 tỷ đô la. Các chuyên gia nhận định sáp nhập giúp giảm 18% chi phí lắp đặt ngoài khơi trong 3 năm tới. Cổ đông sẽ bỏ phiếu vào tháng 11.","vocabulary":[]}', 123, NOW(), NOW()),
(127, 'SINGLE_CHOICE', 'Part 4 Talk 10: Voicemail from a logistics coordinator about customs clearance', NULL, '{"text":"Questions refer to the following short talk (Part 4 Talk 10: Voicemail from a logistics coordinator about customs clearance).","audioUrl":"https://res.cloudinary.com/wgsdldlg/video/upload/v1795594871/leby/at1fbwguzu8enopjcso9.mp3","context":"Listen to the talk or announcement and answer the three questions."}', '{"info":"Parent talk stimulus"}', 4, 'LISTENING', 'Bài nói ngắn TOEIC Part 4 số 10.', 4, '{"transcript":"Hi Mr. Tanaka, this is Rachel from Global Freight Logistics. Good news—your shipment of precision optical lenses cleared Singapore customs an hour ago after we submitted the revised certificate of origin. Our refrigerated courier van is scheduled to deliver the crates to your Jurong lab tomorrow between 9:00 and 11:00 A.M. Please ensure a lab supervisor is present to sign the chain-of-custody form.","translation":"Chào anh Tanaka, Rachel từ Global Freight Logistics báo lô thấu kính quang học đã thông quan tại Singapore sau khi nộp giấy chứng nhận xuất xứ sửa đổi. Xe giao lạnh sẽ giao đến phòng lab Jurong từ 9-11 giờ sáng mai, cần giám sát ký biên bản.","analysis":"Chào anh Tanaka, Rachel từ Global Freight Logistics báo lô thấu kính quang học đã thông quan tại Singapore sau khi nộp giấy chứng nhận xuất xứ sửa đổi. Xe giao lạnh sẽ giao đến phòng lab Jurong từ 9-11 giờ sáng mai, cần giám sát ký biên bản.","vocabulary":[]}', NULL, NOW(), NOW()),
(128, 'SINGLE_CHOICE', 'Part 4 G10 Q1: What allowed the shipment to clear customs?', 1, '{"text":"What allowed the shipment to clear customs?","options":[{"key":"A","text":"(A) Paying an express tariff"},{"key":"B","text":"(B) Submitting a revised certificate of origin"},{"key":"C","text":"(C) Repacking the crates"},{"key":"D","text":"(D) Providing a lab license"}]}', '{"selected":"B","key":"B"}', 3, 'LISTENING', 'Câu hỏi con số 1 của Part 4 Talk 10: Voicemail from a logistics coordinator about customs clearance.', 4, '{"clue":"Nộp bản chứng nhận xuất xứ (''revised certificate of origin'') đã chỉnh sửa.","analysis":"Nộp bản chứng nhận xuất xứ (''revised certificate of origin'') đã chỉnh sửa.","transcript":"Hi Mr. Tanaka, this is Rachel from Global Freight Logistics. Good news—your shipment of precision optical lenses cleared Singapore customs an hour ago after we submitted the revised certificate of origin. Our refrigerated courier van is scheduled to deliver the crates to your Jurong lab tomorrow between 9:00 and 11:00 A.M. Please ensure a lab supervisor is present to sign the chain-of-custody form.","translation":"Chào anh Tanaka, Rachel từ Global Freight Logistics báo lô thấu kính quang học đã thông quan tại Singapore sau khi nộp giấy chứng nhận xuất xứ sửa đổi. Xe giao lạnh sẽ giao đến phòng lab Jurong từ 9-11 giờ sáng mai, cần giám sát ký biên bản.","vocabulary":[]}', 127, NOW(), NOW()),
(129, 'SINGLE_CHOICE', 'Part 4 G10 Q2: When is the delivery expected at the Jurong lab?', 2, '{"text":"When is the delivery expected at the Jurong lab?","options":[{"key":"A","text":"(A) This afternoon"},{"key":"B","text":"(B) Tomorrow between 9:00 and 11:00 A.M."},{"key":"C","text":"(C) Tomorrow afternoon"},{"key":"D","text":"(D) Next Monday morning"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 2 của Part 4 Talk 10: Voicemail from a logistics coordinator about customs clearance.', 4, '{"clue":"Sáng mai trong khung giờ 9:00 đến 11:00.","analysis":"Sáng mai trong khung giờ 9:00 đến 11:00.","transcript":"Hi Mr. Tanaka, this is Rachel from Global Freight Logistics. Good news—your shipment of precision optical lenses cleared Singapore customs an hour ago after we submitted the revised certificate of origin. Our refrigerated courier van is scheduled to deliver the crates to your Jurong lab tomorrow between 9:00 and 11:00 A.M. Please ensure a lab supervisor is present to sign the chain-of-custody form.","translation":"Chào anh Tanaka, Rachel từ Global Freight Logistics báo lô thấu kính quang học đã thông quan tại Singapore sau khi nộp giấy chứng nhận xuất xứ sửa đổi. Xe giao lạnh sẽ giao đến phòng lab Jurong từ 9-11 giờ sáng mai, cần giám sát ký biên bản.","vocabulary":[]}', 127, NOW(), NOW()),
(130, 'SINGLE_CHOICE', 'Part 4 G10 Q3: What is required upon delivery?', 3, '{"text":"What is required upon delivery?","options":[{"key":"A","text":"(A) Cash payment on arrival"},{"key":"B","text":"(B) A lab supervisor''s signature"},{"key":"C","text":"(C) A forklift operator"},{"key":"D","text":"(D) Temperature sensor calibration"}]}', '{"selected":"B","key":"B"}', 2, 'LISTENING', 'Câu hỏi con số 3 của Part 4 Talk 10: Voicemail from a logistics coordinator about customs clearance.', 4, '{"clue":"Cần giám sát phòng lab có mặt ký biên bản bàn giao.","analysis":"Cần giám sát phòng lab có mặt ký biên bản bàn giao.","transcript":"Hi Mr. Tanaka, this is Rachel from Global Freight Logistics. Good news—your shipment of precision optical lenses cleared Singapore customs an hour ago after we submitted the revised certificate of origin. Our refrigerated courier van is scheduled to deliver the crates to your Jurong lab tomorrow between 9:00 and 11:00 A.M. Please ensure a lab supervisor is present to sign the chain-of-custody form.","translation":"Chào anh Tanaka, Rachel từ Global Freight Logistics báo lô thấu kính quang học đã thông quan tại Singapore sau khi nộp giấy chứng nhận xuất xứ sửa đổi. Xe giao lạnh sẽ giao đến phòng lab Jurong từ 9-11 giờ sáng mai, cần giám sát ký biên bản.","vocabulary":[]}', 127, NOW(), NOW()),
(131, 'SINGLE_CHOICE', 'Part 5: Adverb modifying past participle ''praised''', NULL, '{"text":"The newly appointed director was _______ praised by the board for her restructuring plan.","options":[{"key":"A","text":"high"},{"key":"B","text":"highly"},{"key":"C","text":"height"},{"key":"D","text":"heighten"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The newly appointed director was _______ praised by the board for her restructuring plan.","translation":"Giám đốc mới bổ nhiệm được ban giám đốc khen ngợi hết lời.","clue":"Giữa trợ động từ ''was'' và phân từ ''praised'' cần trạng từ ''highly''.","analysis":"Giữa trợ động từ ''was'' và phân từ ''praised'' cần trạng từ ''highly''.","vocabulary":[]}', NULL, NOW(), NOW()),
(132, 'SINGLE_CHOICE', 'Part 5: Noun phrase after possessive ''company''s''', NULL, '{"text":"The software company''s rapid _______ into European markets exceeded analyst forecasts.","options":[{"key":"A","text":"expand"},{"key":"B","text":"expansive"},{"key":"C","text":"expansion"},{"key":"D","text":"expanded"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The software company''s rapid _______ into European markets exceeded analyst forecasts.","translation":"Sự mở rộng nhanh chóng sang thị trường châu Âu vượt dự báo.","clue":"Sau sở hữu cách ''company''s'' và tính từ ''rapid'' bắt buộc dùng danh từ ''expansion''.","analysis":"Sau sở hữu cách ''company''s'' và tính từ ''rapid'' bắt buộc dùng danh từ ''expansion''.","vocabulary":[]}', NULL, NOW(), NOW()),
(133, 'SINGLE_CHOICE', 'Part 5: Adjective modifying noun ''procedures''', NULL, '{"text":"All laboratory technicians must follow _______ safety procedures when handling chemicals.","options":[{"key":"A","text":"strict"},{"key":"B","text":"strictly"},{"key":"C","text":"strictness"},{"key":"D","text":"stricterly"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"All laboratory technicians must follow _______ safety procedures when handling chemicals.","translation":"Kỹ thuật viên phải tuân thủ các quy trình an toàn nghiêm ngặt.","clue":"Trước cụm danh từ ''safety procedures'' cần tính từ ''strict''.","analysis":"Trước cụm danh từ ''safety procedures'' cần tính từ ''strict''.","vocabulary":[]}', NULL, NOW(), NOW()),
(134, 'SINGLE_CHOICE', 'Part 5: Adverb modifying main verb ''reviewed''', NULL, '{"text":"The legal team _______ reviewed every clause of the merger agreement before signing.","options":[{"key":"A","text":"thorough"},{"key":"B","text":"thoroughness"},{"key":"C","text":"thoroughly"},{"key":"D","text":"more thorough"}]}', '{"selected":"C","key":"C"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The legal team _______ reviewed every clause of the merger agreement before signing.","translation":"Đội pháp lý rà soát kỹ lưỡng từng điều khoản hợp đồng sáp nhập.","clue":"Bổ nghĩa cho động từ hành động ''reviewed'' cần trạng từ ''thoroughly''.","analysis":"Bổ nghĩa cho động từ hành động ''reviewed'' cần trạng từ ''thoroughly''.","vocabulary":[]}', NULL, NOW(), NOW()),
(135, 'SINGLE_CHOICE', 'Part 5: Noun as object of preposition ''for''', NULL, '{"text":"Thank you for your continued _______ to delivering outstanding customer support.","options":[{"key":"A","text":"dedicate"},{"key":"B","text":"dedicated"},{"key":"C","text":"dedication"},{"key":"D","text":"dedicating"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Thank you for your continued _______ to delivering outstanding customer support.","translation":"Cảm ơn sự tận tâm liên tục của bạn trong dịch vụ khách hàng.","clue":"Sau tính từ ''continued'' cần danh từ ''dedication''.","analysis":"Sau tính từ ''continued'' cần danh từ ''dedication''.","vocabulary":[]}', NULL, NOW(), NOW()),
(136, 'SINGLE_CHOICE', 'Part 5: Adjective after linking verb ''remained''', NULL, '{"text":"Despite supply chain disruptions, quarterly operating margins remained _______.","options":[{"key":"A","text":"stability"},{"key":"B","text":"stabilize"},{"key":"C","text":"stable"},{"key":"D","text":"stably"}]}', '{"selected":"C","key":"C"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Despite supply chain disruptions, quarterly operating margins remained _______.","translation":"Bất chấp gián đoạn chuỗi cung ứng, biên lợi nhuận vẫn ổn định.","clue":"Động từ nối ''remain'' đi kèm tính từ ''stable''.","analysis":"Động từ nối ''remain'' đi kèm tính từ ''stable''.","vocabulary":[]}', NULL, NOW(), NOW()),
(137, 'SINGLE_CHOICE', 'Part 5: Adverb modifying adjective ''reliable''', NULL, '{"text":"Our upgraded fiber-optic network has proven _______ reliable during peak hours.","options":[{"key":"A","text":"remark"},{"key":"B","text":"remarkable"},{"key":"C","text":"remarkably"},{"key":"D","text":"remarked"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Our upgraded fiber-optic network has proven _______ reliable during peak hours.","translation":"Mạng cáp quang nâng cấp chứng tỏ độ tin cậy đáng kinh ngạc.","clue":"Trước tính từ ''reliable'' cần trạng từ ''remarkably''.","analysis":"Trước tính từ ''reliable'' cần trạng từ ''remarkably''.","vocabulary":[]}', NULL, NOW(), NOW()),
(138, 'SINGLE_CHOICE', 'Part 5: Noun subject before verb ''requires''', NULL, '{"text":"_______ of the annual compliance audit requires signatures from two senior partners.","options":[{"key":"A","text":"Complete"},{"key":"B","text":"Completed"},{"key":"C","text":"Completion"},{"key":"D","text":"Completely"}]}', '{"selected":"C","key":"C"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"_______ of the annual compliance audit requires signatures from two senior partners.","translation":"Việc hoàn tất kiểm toán tuân thủ hàng năm cần chữ ký hai đối tác cấp cao.","clue":"Chủ ngữ đứng trước giới từ ''of'' cần danh từ ''Completion''.","analysis":"Chủ ngữ đứng trước giới từ ''of'' cần danh từ ''Completion''.","vocabulary":[]}', NULL, NOW(), NOW()),
(139, 'SINGLE_CHOICE', 'Part 5: Adjective modifying ''recommendations''', NULL, '{"text":"The consultant offered several _______ recommendations to reduce warehouse energy costs.","options":[{"key":"A","text":"construct"},{"key":"B","text":"constructive"},{"key":"C","text":"constructively"},{"key":"D","text":"construction"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The consultant offered several _______ recommendations to reduce warehouse energy costs.","translation":"Chuyên gia tư vấn đưa ra nhiều đề xuất mang tính xây dựng.","clue":"Sau lượng từ ''several'' và trước danh từ ''recommendations'' cần tính từ ''constructive''.","analysis":"Sau lượng từ ''several'' và trước danh từ ''recommendations'' cần tính từ ''constructive''.","vocabulary":[]}', NULL, NOW(), NOW()),
(140, 'SINGLE_CHOICE', 'Part 5: Adverb modifying ''scheduled''', NULL, '{"text":"The keynote address was _______ scheduled for Tuesday but moved to Wednesday afternoon.","options":[{"key":"A","text":"origin"},{"key":"B","text":"original"},{"key":"C","text":"originally"},{"key":"D","text":"originate"}]}', '{"selected":"C","key":"C"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The keynote address was _______ scheduled for Tuesday but moved to Wednesday afternoon.","translation":"Bài phát biểu chính ban đầu được lên lịch vào thứ Ba.","clue":"Bổ nghĩa cho phân từ ''scheduled'' cần trạng từ ''originally''.","analysis":"Bổ nghĩa cho phân từ ''scheduled'' cần trạng từ ''originally''.","vocabulary":[]}', NULL, NOW(), NOW()),
(141, 'SINGLE_CHOICE', 'Part 5: Noun after article ''an''', NULL, '{"text":"Please submit an _______ of projected travel expenses before booking international flights.","options":[{"key":"A","text":"estimate"},{"key":"B","text":"estimated"},{"key":"C","text":"estimating"},{"key":"D","text":"estimable"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Please submit an _______ of projected travel expenses before booking international flights.","translation":"Vui lòng nộp bản dự toán chi phí công tác trước khi đặt vé.","clue":"Sau mạo từ ''an'' và trước ''of'' cần danh từ ''estimate''.","analysis":"Sau mạo từ ''an'' và trước ''of'' cần danh từ ''estimate''.","vocabulary":[]}', NULL, NOW(), NOW()),
(142, 'SINGLE_CHOICE', 'Part 5: Adjective in compound noun phrase', NULL, '{"text":"Applicants with _______ experience in cloud security will be given priority.","options":[{"key":"A","text":"demonstrate"},{"key":"B","text":"demonstrated"},{"key":"C","text":"demonstration"},{"key":"D","text":"demonstrably"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Applicants with _______ experience in cloud security will be given priority.","translation":"Ứng viên có kinh nghiệm đã được chứng minh về bảo mật đám mây sẽ được ưu tiên.","clue":"Quá khứ phân từ đóng vai trò tính từ ''demonstrated experience'' (kinh nghiệm thực chứng).","analysis":"Quá khứ phân từ đóng vai trò tính từ ''demonstrated experience'' (kinh nghiệm thực chứng).","vocabulary":[]}', NULL, NOW(), NOW()),
(143, 'SINGLE_CHOICE', 'Part 5: Future Perfect with ''By the time''', NULL, '{"text":"By the time the new logistics center opens next spring, engineers _______ the database.","options":[{"key":"A","text":"will have migrated"},{"key":"B","text":"have migrated"},{"key":"C","text":"migrated"},{"key":"D","text":"are migrating"}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"By the time the new logistics center opens next spring, engineers _______ the database.","translation":"Trước khi trung tâm hậu cần mới mở cửa, kỹ sư sẽ hoàn tất chuyển đổi dữ liệu.","clue":"Cấu trúc ''By the time + Hiện tại đơn, S + will have + V3'' (Tương lai hoàn thành).","analysis":"Cấu trúc ''By the time + Hiện tại đơn, S + will have + V3'' (Tương lai hoàn thành).","vocabulary":[]}', NULL, NOW(), NOW()),
(144, 'SINGLE_CHOICE', 'Part 5: Present Perfect with ''since''', NULL, '{"text":"Since joining the firm in 2021, Ms. Ortiz _______ three major enterprise accounts.","options":[{"key":"A","text":"manages"},{"key":"B","text":"has managed"},{"key":"C","text":"is managing"},{"key":"D","text":"will manage"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Since joining the firm in 2021, Ms. Ortiz _______ three major enterprise accounts.","translation":"Kể từ khi gia nhập công ty năm 2021, cô Ortiz đã phụ trách 3 khách hàng lớn.","clue":"Dấu hiệu ''Since + mốc quá khứ'' bắt buộc chia thì Hiện tại hoàn thành ''has managed''.","analysis":"Dấu hiệu ''Since + mốc quá khứ'' bắt buộc chia thì Hiện tại hoàn thành ''has managed''.","vocabulary":[]}', NULL, NOW(), NOW()),
(145, 'SINGLE_CHOICE', 'Part 5: Passive voice in Simple Past', NULL, '{"text":"All outdated workstations in the accounting wing _______ over the weekend.","options":[{"key":"A","text":"replaced"},{"key":"B","text":"were replaced"},{"key":"C","text":"have replacing"},{"key":"D","text":"are replace"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"All outdated workstations in the accounting wing _______ over the weekend.","translation":"Toàn bộ máy trạm cũ ở khu kế toán đã được thay thế cuối tuần qua.","clue":"Chủ ngữ vật ''workstations'' + mốc quá khứ ''over the weekend'' -> bị động Quá khứ đơn.","analysis":"Chủ ngữ vật ''workstations'' + mốc quá khứ ''over the weekend'' -> bị động Quá khứ đơn.","vocabulary":[]}', NULL, NOW(), NOW()),
(146, 'SINGLE_CHOICE', 'Part 5: Subject-Verb agreement with prepositional phrase', NULL, '{"text":"The list of approved hardware vendors _______ updated at the start of each fiscal year.","options":[{"key":"A","text":"are"},{"key":"B","text":"were"},{"key":"C","text":"is"},{"key":"D","text":"have been"}]}', '{"selected":"C","key":"C"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The list of approved hardware vendors _______ updated at the start of each fiscal year.","translation":"Danh sách nhà cung cấp phần cứng được cập nhật vào đầu mỗi năm tài chính.","clue":"Chủ ngữ chính là ''The list'' (số ít) + thói quen định kỳ -> dùng ''is''.","analysis":"Chủ ngữ chính là ''The list'' (số ít) + thói quen định kỳ -> dùng ''is''.","vocabulary":[]}', NULL, NOW(), NOW()),
(147, 'SINGLE_CHOICE', 'Part 5: Past Continuous interrupted by Simple Past', NULL, '{"text":"The team _______ the final presentation when the conference room projector failed.","options":[{"key":"A","text":"rehearsed"},{"key":"B","text":"was rehearsing"},{"key":"C","text":"has rehearsed"},{"key":"D","text":"will rehearse"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The team _______ the final presentation when the conference room projector failed.","translation":"Nhóm đang diễn tập bài thuyết trình thì máy chiếu bị hỏng.","clue":"Hành động đang diễn ra trong quá khứ bị cắt ngang dùng Quá khứ tiếp diễn ''was rehearsing''.","analysis":"Hành động đang diễn ra trong quá khứ bị cắt ngang dùng Quá khứ tiếp diễn ''was rehearsing''.","vocabulary":[]}', NULL, NOW(), NOW()),
(148, 'SINGLE_CHOICE', 'Part 5: Modal passive ''must be submitted''', NULL, '{"text":"Reimbursement claims for client dinners must _______ within fourteen days of the event.","options":[{"key":"A","text":"submit"},{"key":"B","text":"be submitted"},{"key":"C","text":"submitting"},{"key":"D","text":"have submit"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Reimbursement claims for client dinners must _______ within fourteen days of the event.","translation":"Yêu cầu hoàn ứng tiếp khách phải được nộp trong vòng 14 ngày.","clue":"Chủ ngữ vật ''claims'' cần dạng bị động sau động từ khuyết thiếu: ''must be + V3''.","analysis":"Chủ ngữ vật ''claims'' cần dạng bị động sau động từ khuyết thiếu: ''must be + V3''.","vocabulary":[]}', NULL, NOW(), NOW()),
(149, 'SINGLE_CHOICE', 'Part 5: Conditional Type 1 with ''Should''', NULL, '{"text":"Should any shipment _______ damaged upon arrival, notify our claims desk immediately.","options":[{"key":"A","text":"arrive"},{"key":"B","text":"arrives"},{"key":"C","text":"arrived"},{"key":"D","text":"arriving"}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Should any shipment _______ damaged upon arrival, notify our claims desk immediately.","translation":"Nếu bất kỳ lô hàng nào đến nơi bị hư hại, hãy báo ngay bộ phận khiếu nại.","clue":"Đảo ngữ câu điều kiện loại 1: ''Should + S + V(nguyên thể)''.","analysis":"Đảo ngữ câu điều kiện loại 1: ''Should + S + V(nguyên thể)''.","vocabulary":[]}', NULL, NOW(), NOW()),
(150, 'SINGLE_CHOICE', 'Part 5: Past Perfect before past reference', NULL, '{"text":"Before the merger took effect, both airlines _______ separate loyalty programs.","options":[{"key":"A","text":"operate"},{"key":"B","text":"had operated"},{"key":"C","text":"are operating"},{"key":"D","text":"will operate"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Before the merger took effect, both airlines _______ separate loyalty programs.","translation":"Trước khi sáp nhập có hiệu lực, cả hai hãng bay đều vận hành chương trình khách hàng riêng.","clue":"Hành động xảy ra trước một mốc quá khứ (''took effect'') dùng Quá khứ hoàn thành ''had operated''.","analysis":"Hành động xảy ra trước một mốc quá khứ (''took effect'') dùng Quá khứ hoàn thành ''had operated''.","vocabulary":[]}', NULL, NOW(), NOW()),
(151, 'SINGLE_CHOICE', 'Part 5: Gerund after ''look forward to''', NULL, '{"text":"We look forward to _______ your team at the Tokyo Trade Expo next month.","options":[{"key":"A","text":"meet"},{"key":"B","text":"meeting"},{"key":"C","text":"met"},{"key":"D","text":"have met"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"We look forward to _______ your team at the Tokyo Trade Expo next month.","translation":"Chúng tôi mong chờ được gặp đội ngũ của bạn tại triển lãm Tokyo tháng tới.","clue":"Cụm cố định ''look forward to + V-ing''.","analysis":"Cụm cố định ''look forward to + V-ing''.","vocabulary":[]}', NULL, NOW(), NOW()),
(152, 'SINGLE_CHOICE', 'Part 5: Subjunctive ''recommended that''', NULL, '{"text":"The external auditor recommended that the company _______ its cash reserves quarterly.","options":[{"key":"A","text":"reviews"},{"key":"B","text":"reviewed"},{"key":"C","text":"review"},{"key":"D","text":"reviewing"}]}', '{"selected":"C","key":"C"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The external auditor recommended that the company _______ its cash reserves quarterly.","translation":"Kiểm toán độc lập khuyến nghị công ty rà soát quỹ dự phòng hàng quý.","clue":"Thức giả định ''recommend that + S + V(nguyên thể không to)''.","analysis":"Thức giả định ''recommend that + S + V(nguyên thể không to)''.","vocabulary":[]}', NULL, NOW(), NOW()),
(153, 'SINGLE_CHOICE', 'Part 5: Future Simple with ''next quarter''', NULL, '{"text":"Apex Logistics _______ two additional electric delivery vans early next quarter.","options":[{"key":"A","text":"will acquire"},{"key":"B","text":"acquired"},{"key":"C","text":"has acquired"},{"key":"D","text":"was acquiring"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Apex Logistics _______ two additional electric delivery vans early next quarter.","translation":"Apex Logistics sẽ mua thêm hai xe tải giao hàng chạy điện đầu quý tới.","clue":"Dấu hiệu tương lai ''early next quarter'' dùng Tương lai đơn ''will acquire''.","analysis":"Dấu hiệu tương lai ''early next quarter'' dùng Tương lai đơn ''will acquire''.","vocabulary":[]}', NULL, NOW(), NOW()),
(154, 'SINGLE_CHOICE', 'Part 5: Present Perfect Passive', NULL, '{"text":"Over five hundred employees _______ in the new cybersecurity awareness workshop so far.","options":[{"key":"A","text":"enrolled"},{"key":"B","text":"have been enrolled"},{"key":"C","text":"were enrolling"},{"key":"D","text":"enroll"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Over five hundred employees _______ in the new cybersecurity awareness workshop so far.","translation":"Đến nay hơn 500 nhân viên đã được ghi danh vào khóa đào tạo an ninh mạng.","clue":"Cụm ''so far'' + nghĩa bị động -> Hiện tại hoàn thành bị động ''have been enrolled''.","analysis":"Cụm ''so far'' + nghĩa bị động -> Hiện tại hoàn thành bị động ''have been enrolled''.","vocabulary":[]}', NULL, NOW(), NOW()),
(155, 'SINGLE_CHOICE', 'Part 5: Collocation ''adhere to protocols''', NULL, '{"text":"All factory employees are mandated to _______ to the updated safety protocols.","options":[{"key":"A","text":"adhere"},{"key":"B","text":"comply"},{"key":"C","text":"follow"},{"key":"D","text":"observe"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"All factory employees are mandated to _______ to the updated safety protocols.","translation":"Nhân viên nhà máy bắt buộc tuân thủ các quy trình an toàn cập nhật.","clue":"Chỉ ''adhere'' đi với giới từ ''to'' (''comply with'', ''follow/observe'' không có ''to'').","analysis":"Chỉ ''adhere'' đi với giới từ ''to'' (''comply with'', ''follow/observe'' không có ''to'').","vocabulary":[]}', NULL, NOW(), NOW()),
(156, 'SINGLE_CHOICE', 'Part 5: Business noun ''itinerary''', NULL, '{"text":"Please review the attached travel _______ and confirm your preferred flight times.","options":[{"key":"A","text":"itinerary"},{"key":"B","text":"inventory"},{"key":"C","text":"warranty"},{"key":"D","text":"subsidy"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Please review the attached travel _______ and confirm your preferred flight times.","translation":"Vui lòng xem lại lịch trình công tác đính kèm và xác nhận giờ bay.","clue":"''Travel itinerary'' là cụm từ chuyên ngành chỉ lịch trình chuyến đi.","analysis":"''Travel itinerary'' là cụm từ chuyên ngành chỉ lịch trình chuyến đi.","vocabulary":[]}', NULL, NOW(), NOW()),
(157, 'SINGLE_CHOICE', 'Part 5: Verb ''conduct a survey''', NULL, '{"text":"The research department will _______ a nationwide customer satisfaction survey in May.","options":[{"key":"A","text":"conduct"},{"key":"B","text":"persuade"},{"key":"C","text":"manufacture"},{"key":"D","text":"compensate"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The research department will _______ a nationwide customer satisfaction survey in May.","translation":"Phòng nghiên cứu sẽ tiến hành khảo sát mức độ hài lòng toàn quốc vào tháng 5.","clue":"Collocation chuẩn TOEIC: ''conduct a survey / study / audit''.","analysis":"Collocation chuẩn TOEIC: ''conduct a survey / study / audit''.","vocabulary":[]}', NULL, NOW(), NOW()),
(158, 'SINGLE_CHOICE', 'Part 5: Preposition ''despite'' vs ''although''', NULL, '{"text":"_______ the unexpected rainfall, the outdoor product showcase attracted record crowds.","options":[{"key":"A","text":"Although"},{"key":"B","text":"Despite"},{"key":"C","text":"Even though"},{"key":"D","text":"Whereas"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"_______ the unexpected rainfall, the outdoor product showcase attracted record crowds.","translation":"Mặc dù trời mưa bất ngờ, buổi giới thiệu sản phẩm ngoài trời vẫn thu hút đông đảo khách.","clue":"Trước cụm danh từ ''the unexpected rainfall'' dùng giới từ ''Despite''.","analysis":"Trước cụm danh từ ''the unexpected rainfall'' dùng giới từ ''Despite''.","vocabulary":[]}', NULL, NOW(), NOW()),
(159, 'SINGLE_CHOICE', 'Part 5: Business adjective ''eligible''', NULL, '{"text":"Full-time staff who complete one year of service are _______ for tuition reimbursement.","options":[{"key":"A","text":"eligible"},{"key":"B","text":"portable"},{"key":"C","text":"adjacent"},{"key":"D","text":"lenient"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Full-time staff who complete one year of service are _______ for tuition reimbursement.","translation":"Nhân viên toàn thời gian làm đủ 1 năm sẽ đủ điều kiện nhận hỗ trợ học phí.","clue":"Cấu trúc cố định ''be eligible for + N'' (đủ điều kiện hưởng quyền lợi).","analysis":"Cấu trúc cố định ''be eligible for + N'' (đủ điều kiện hưởng quyền lợi).","vocabulary":[]}', NULL, NOW(), NOW()),
(160, 'SINGLE_CHOICE', 'Part 5: Verb ''allocate resources''', NULL, '{"text":"Management decided to _______ additional funding to the artificial intelligence division.","options":[{"key":"A","text":"allocate"},{"key":"B","text":"hesitate"},{"key":"C","text":"evacuate"},{"key":"D","text":"accumulate"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Management decided to _______ additional funding to the artificial intelligence division.","translation":"Ban lãnh đạo quyết định phân bổ thêm ngân sách cho khối trí tuệ nhân tạo.","clue":"''Allocate funding/resources to'' nghĩa là phân bổ ngân sách/nguồn lực.","analysis":"''Allocate funding/resources to'' nghĩa là phân bổ ngân sách/nguồn lực.","vocabulary":[]}', NULL, NOW(), NOW());
INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(161, 'SINGLE_CHOICE', 'Part 5: Noun ''consensus''', NULL, '{"text":"After three hours of debate, the committee finally reached a _______ on the pricing model.","options":[{"key":"A","text":"consensus"},{"key":"B","text":"criterion"},{"key":"C","text":"deficit"},{"key":"D","text":"turnover"}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"After three hours of debate, the committee finally reached a _______ on the pricing model.","translation":"Sau 3 giờ thảo luận, ủy ban cuối cùng đạt được sự đồng thuận về mô hình giá.","clue":"Collocation ''reach a consensus'' (đạt được sự đồng thuận).","analysis":"Collocation ''reach a consensus'' (đạt được sự đồng thuận).","vocabulary":[]}', NULL, NOW(), NOW()),
(162, 'SINGLE_CHOICE', 'Part 5: Conjunction ''provided that''', NULL, '{"text":"Returns are accepted for a full refund _______ the merchandise remains in original packaging.","options":[{"key":"A","text":"provided that"},{"key":"B","text":"in case of"},{"key":"C","text":"prior to"},{"key":"D","text":"regardless of"}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Returns are accepted for a full refund _______ the merchandise remains in original packaging.","translation":"Hàng trả lại được hoàn tiền đủ với điều kiện còn nguyên bao bì.","clue":"''Provided that + mệnh đề'' = với điều kiện là.","analysis":"''Provided that + mệnh đề'' = với điều kiện là.","vocabulary":[]}', NULL, NOW(), NOW()),
(163, 'SINGLE_CHOICE', 'Part 5: Verb ''streamline operations''', NULL, '{"text":"The new enterprise resource platform was introduced to _______ payroll processing.","options":[{"key":"A","text":"streamline"},{"key":"B","text":"obstruct"},{"key":"C","text":"resemble"},{"key":"D","text":"withhold"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The new enterprise resource platform was introduced to _______ payroll processing.","translation":"Nền tảng quản trị mới được triển khai nhằm tinh gọn quy trình tính lương.","clue":"''Streamline operations/processing'' = tinh gọn, tối ưu quy trình.","analysis":"''Streamline operations/processing'' = tinh gọn, tối ưu quy trình.","vocabulary":[]}', NULL, NOW(), NOW()),
(164, 'SINGLE_CHOICE', 'Part 5: Noun ''reimbursement''', NULL, '{"text":"Original itemized receipts must accompany every request for travel _______.","options":[{"key":"A","text":"reimbursement"},{"key":"B","text":"recruitment"},{"key":"C","text":"merchandise"},{"key":"D","text":"endorsement"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"Original itemized receipts must accompany every request for travel _______.","translation":"Hóa đơn chi tiết bản gốc phải đi kèm mọi yêu cầu hoàn ứng công tác.","clue":"''Travel reimbursement'' = thanh toán hoàn ứng chi phí đi lại.","analysis":"''Travel reimbursement'' = thanh toán hoàn ứng chi phí đi lại.","vocabulary":[]}', NULL, NOW(), NOW()),
(165, 'SINGLE_CHOICE', 'Part 5: Adjective ''tentative''', NULL, '{"text":"The schedule for the annual leadership retreat is still _______ and subject to change.","options":[{"key":"A","text":"tentative"},{"key":"B","text":"mandatory"},{"key":"C","text":"unanimous"},{"key":"D","text":"obsolete"}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"The schedule for the annual leadership retreat is still _______ and subject to change.","translation":"Lịch trình kỳ nghỉ lãnh đạo thường niên vẫn đang dự kiến và có thể thay đổi.","clue":"''Tentative'' (dự kiến, tạm thời) khớp ngữ cảnh ''subject to change''.","analysis":"''Tentative'' (dự kiến, tạm thời) khớp ngữ cảnh ''subject to change''.","vocabulary":[]}', NULL, NOW(), NOW()),
(166, 'SINGLE_CHOICE', 'Part 5: Phrase ''in compliance with''', NULL, '{"text":"All imported medical devices must be labeled in strict _______ with regional regulations.","options":[{"key":"A","text":"compliance"},{"key":"B","text":"allowance"},{"key":"C","text":"reluctance"},{"key":"D","text":"persistence"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền từ ngữ pháp/từ vựng TOEIC Part 5.', 5, '{"transcript":"All imported medical devices must be labeled in strict _______ with regional regulations.","translation":"Mọi thiết bị y tế nhập khẩu phải dán nhãn tuân thủ nghiêm quy định khu vực.","clue":"Cụm cố định ''in compliance with'' = tuân thủ theo.","analysis":"Cụm cố định ''in compliance with'' = tuân thủ theo.","vocabulary":[]}', NULL, NOW(), NOW()),
(167, 'SINGLE_CHOICE', 'Part 6 Passage 1: Internal IT security 2FA memorandum', NULL, '{"text":"Questions refer to the following text (Part 6 Passage 1: Internal IT security 2FA memorandum).","content":"MEMORANDUM\\nTo: All Staff Members\\nFrom: IT Security Department\\nSubject: Mandatory Two-Factor Authentication\\n\\nIn light of recent phishing attempts targeting regional servers, IT is implementing mandatory two-factor authentication (2FA) across all accounts. Beginning next Monday, staff will verify their identity via a mobile authenticator app. ----[1]----, access to corporate email will be temporarily restricted.\\n\\n----[2]----. Our technical specialists will host walk-in setup clinics in Room 204 throughout the week. Please bring your ----[3]---- mobile device and employee ID badge. We appreciate your ----[4]---- in keeping company data secure.","passage":"MEMORANDUM\\nTo: All Staff Members\\nFrom: IT Security Department\\nSubject: Mandatory Two-Factor Authentication\\n\\nIn light of recent phishing attempts targeting regional servers, IT is implementing mandatory two-factor authentication (2FA) across all accounts. Beginning next Monday, staff will verify their identity via a mobile authenticator app. ----[1]----, access to corporate email will be temporarily restricted.\\n\\n----[2]----. Our technical specialists will host walk-in setup clinics in Room 204 throughout the week. Please bring your ----[3]---- mobile device and employee ID badge. We appreciate your ----[4]---- in keeping company data secure."}', '{"info":"Parent passage stimulus"}', 3, 'READING', 'Đoạn văn điền từ TOEIC Part 6 số 1.', 6, '{"translation":"Thông báo nội bộ phòng An ninh CNTT về việc bắt buộc bật xác thực hai yếu tố (2FA) từ thứ Hai tới và lịch hỗ trợ trực tiếp tại Phòng 204.","analysis":"Thông báo nội bộ phòng An ninh CNTT về việc bắt buộc bật xác thực hai yếu tố (2FA) từ thứ Hai tới và lịch hỗ trợ trực tiếp tại Phòng 204.","vocabulary":[]}', NULL, NOW(), NOW()),
(168, 'SINGLE_CHOICE', 'Part 6 G1 Q1: Select the best transition for blank [1].', 1, '{"text":"Select the best transition for blank [1].","options":[{"key":"A","text":"Otherwise"},{"key":"B","text":"Furthermore"},{"key":"C","text":"Similarly"},{"key":"D","text":"In conclusion"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 1 của Part 6 Passage 1: Internal IT security 2FA memorandum.', 6, '{"clue":"''Otherwise'' (Nếu không thì) diễn tả hệ quả bị hạn chế quyền truy cập.","analysis":"''Otherwise'' (Nếu không thì) diễn tả hệ quả bị hạn chế quyền truy cập.","translation":"Thông báo nội bộ phòng An ninh CNTT về việc bắt buộc bật xác thực hai yếu tố (2FA) từ thứ Hai tới và lịch hỗ trợ trực tiếp tại Phòng 204.","vocabulary":[]}', 167, NOW(), NOW()),
(169, 'SINGLE_CHOICE', 'Part 6 G1 Q2: Which sentence best fits in blank [2]?', 2, '{"text":"Which sentence best fits in blank [2]?","options":[{"key":"A","text":"Please ensure that you configure your mobile device prior to the deadline."},{"key":"B","text":"The servers will be shut down permanently next weekend."},{"key":"C","text":"All paper files must be shredded before Friday."},{"key":"D","text":"New ergonomic chairs have arrived in Room 204."}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền chỗ trống số 2 của Part 6 Passage 1: Internal IT security 2FA memorandum.', 6, '{"clue":"Câu (A) nối mượt sang ý phòng IT mở buổi hỗ trợ cài đặt suốt tuần.","analysis":"Câu (A) nối mượt sang ý phòng IT mở buổi hỗ trợ cài đặt suốt tuần.","translation":"Thông báo nội bộ phòng An ninh CNTT về việc bắt buộc bật xác thực hai yếu tố (2FA) từ thứ Hai tới và lịch hỗ trợ trực tiếp tại Phòng 204.","vocabulary":[]}', 167, NOW(), NOW()),
(170, 'SINGLE_CHOICE', 'Part 6 G1 Q3: Select the best word for blank [3].', 3, '{"text":"Select the best word for blank [3].","options":[{"key":"A","text":"assigned"},{"key":"B","text":"assigning"},{"key":"C","text":"assignment"},{"key":"D","text":"assigns"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 3 của Part 6 Passage 1: Internal IT security 2FA memorandum.', 6, '{"clue":"Tính từ phân từ ''assigned mobile device'' (thiết bị được cấp phát).","analysis":"Tính từ phân từ ''assigned mobile device'' (thiết bị được cấp phát).","translation":"Thông báo nội bộ phòng An ninh CNTT về việc bắt buộc bật xác thực hai yếu tố (2FA) từ thứ Hai tới và lịch hỗ trợ trực tiếp tại Phòng 204.","vocabulary":[]}', 167, NOW(), NOW()),
(171, 'SINGLE_CHOICE', 'Part 6 G1 Q4: Select the best word for blank [4].', 4, '{"text":"Select the best word for blank [4].","options":[{"key":"A","text":"cooperate"},{"key":"B","text":"cooperative"},{"key":"C","text":"cooperation"},{"key":"D","text":"cooperated"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 4 của Part 6 Passage 1: Internal IT security 2FA memorandum.', 6, '{"clue":"Sau tính từ sở hữu ''your'' cần danh từ ''cooperation''.","analysis":"Sau tính từ sở hữu ''your'' cần danh từ ''cooperation''.","translation":"Thông báo nội bộ phòng An ninh CNTT về việc bắt buộc bật xác thực hai yếu tố (2FA) từ thứ Hai tới và lịch hỗ trợ trực tiếp tại Phòng 204.","vocabulary":[]}', 167, NOW(), NOW()),
(172, 'SINGLE_CHOICE', 'Part 6 Passage 2: Customer notice on eco-friendly packaging upgrade', NULL, '{"text":"Questions refer to the following text (Part 6 Passage 2: Customer notice on eco-friendly packaging upgrade).","content":"Dear Valued Customer,\\n\\nAt GreenLeaf Organics, we are committed to reducing our environmental footprint. Starting October 1, all online grocery deliveries will arrive in 100% compostable insulated liners. ----[1]----, these plant-based liners keep perishable foods cold for up to twenty-four hours.\\n\\n----[2]----. Simply rinse the liner and place it in your municipal compost bin, or leave it on your doorstep for our driver to collect during your next delivery. ----[3]---- this upgrade, our standard delivery fee will remain unchanged. Thank you for helping us build a more ----[4]---- future.","passage":"Dear Valued Customer,\\n\\nAt GreenLeaf Organics, we are committed to reducing our environmental footprint. Starting October 1, all online grocery deliveries will arrive in 100% compostable insulated liners. ----[1]----, these plant-based liners keep perishable foods cold for up to twenty-four hours.\\n\\n----[2]----. Simply rinse the liner and place it in your municipal compost bin, or leave it on your doorstep for our driver to collect during your next delivery. ----[3]---- this upgrade, our standard delivery fee will remain unchanged. Thank you for helping us build a more ----[4]---- future."}', '{"info":"Parent passage stimulus"}', 3, 'READING', 'Đoạn văn điền từ TOEIC Part 6 số 2.', 6, '{"translation":"Thư thông báo khách hàng của GreenLeaf Organics về việc chuyển sang lớp lót cách nhiệt phân hủy sinh học 100% mà không tăng phí giao hàng.","analysis":"Thư thông báo khách hàng của GreenLeaf Organics về việc chuyển sang lớp lót cách nhiệt phân hủy sinh học 100% mà không tăng phí giao hàng.","vocabulary":[]}', NULL, NOW(), NOW()),
(173, 'SINGLE_CHOICE', 'Part 6 G2 Q1: Select the best transition for blank [1].', 1, '{"text":"Select the best transition for blank [1].","options":[{"key":"A","text":"Moreover"},{"key":"B","text":"Nevertheless"},{"key":"C","text":"Instead"},{"key":"D","text":"Otherwise"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 1 của Part 6 Passage 2: Customer notice on eco-friendly packaging upgrade.', 6, '{"clue":"''Moreover'' bổ sung thêm ưu điểm giữ lạnh 24 giờ.","analysis":"''Moreover'' bổ sung thêm ưu điểm giữ lạnh 24 giờ.","translation":"Thư thông báo khách hàng của GreenLeaf Organics về việc chuyển sang lớp lót cách nhiệt phân hủy sinh học 100% mà không tăng phí giao hàng.","vocabulary":[]}', 172, NOW(), NOW()),
(174, 'SINGLE_CHOICE', 'Part 6 G2 Q2: Which sentence best fits in blank [2]?', 2, '{"text":"Which sentence best fits in blank [2]?","options":[{"key":"A","text":"Disposing of the new packaging is quick and effortless."},{"key":"B","text":"Our store hours will expand on Sundays."},{"key":"C","text":"Please call customer support to cancel your membership."},{"key":"D","text":"Frozen desserts are currently out of stock."}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 2 của Part 6 Passage 2: Customer notice on eco-friendly packaging upgrade.', 6, '{"clue":"Câu (A) mở ý cho câu kế tiếp hướng dẫn cách xử lý/thu gom bao bì dễ dàng.","analysis":"Câu (A) mở ý cho câu kế tiếp hướng dẫn cách xử lý/thu gom bao bì dễ dàng.","translation":"Thư thông báo khách hàng của GreenLeaf Organics về việc chuyển sang lớp lót cách nhiệt phân hủy sinh học 100% mà không tăng phí giao hàng.","vocabulary":[]}', 172, NOW(), NOW()),
(175, 'SINGLE_CHOICE', 'Part 6 G2 Q3: Select the best preposition for blank [3].', 3, '{"text":"Select the best preposition for blank [3].","options":[{"key":"A","text":"Despite"},{"key":"B","text":"Although"},{"key":"C","text":"Because"},{"key":"D","text":"Unless"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 3 của Part 6 Passage 2: Customer notice on eco-friendly packaging upgrade.', 6, '{"clue":"Trước cụm danh từ ''this upgrade'' dùng ''Despite'' (Mặc dù nâng cấp nhưng phí giao vẫn giữ nguyên).","analysis":"Trước cụm danh từ ''this upgrade'' dùng ''Despite'' (Mặc dù nâng cấp nhưng phí giao vẫn giữ nguyên).","translation":"Thư thông báo khách hàng của GreenLeaf Organics về việc chuyển sang lớp lót cách nhiệt phân hủy sinh học 100% mà không tăng phí giao hàng.","vocabulary":[]}', 172, NOW(), NOW()),
(176, 'SINGLE_CHOICE', 'Part 6 G2 Q4: Select the best adjective for blank [4].', 4, '{"text":"Select the best adjective for blank [4].","options":[{"key":"A","text":"sustain"},{"key":"B","text":"sustainable"},{"key":"C","text":"sustainably"},{"key":"D","text":"sustainability"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 4 của Part 6 Passage 2: Customer notice on eco-friendly packaging upgrade.', 6, '{"clue":"Bổ nghĩa cho danh từ ''future'' cần tính từ ''sustainable''.","analysis":"Bổ nghĩa cho danh từ ''future'' cần tính từ ''sustainable''.","translation":"Thư thông báo khách hàng của GreenLeaf Organics về việc chuyển sang lớp lót cách nhiệt phân hủy sinh học 100% mà không tăng phí giao hàng.","vocabulary":[]}', 172, NOW(), NOW()),
(177, 'SINGLE_CHOICE', 'Part 6 Passage 3: Announcement of annual staff appreciation banquet', NULL, '{"text":"Questions refer to the following text (Part 6 Passage 3: Announcement of annual staff appreciation banquet).","content":"To: All Regional Employees\\nSubject: Annual Appreciation Banquet\\n\\nWe are delighted to invite you to this year''s Staff Appreciation Banquet on Friday, December 12, at the Waterfront Pavilion. Doors open at 6:00 P.M. with live jazz music and refreshments. ----[1]----, CEO Raymond Wu will present the Excellence in Innovation Awards.\\n\\n----[2]----. Vegetarian, vegan, and gluten-free entrees are available upon request. Please RSVP through the HR portal ----[3]---- November 28 so we can finalize table seating. Guests are encouraged to use the complimentary shuttle departing from headquarters every twenty minutes ----[4]---- parking near the pavilion is limited.","passage":"To: All Regional Employees\\nSubject: Annual Appreciation Banquet\\n\\nWe are delighted to invite you to this year''s Staff Appreciation Banquet on Friday, December 12, at the Waterfront Pavilion. Doors open at 6:00 P.M. with live jazz music and refreshments. ----[1]----, CEO Raymond Wu will present the Excellence in Innovation Awards.\\n\\n----[2]----. Vegetarian, vegan, and gluten-free entrees are available upon request. Please RSVP through the HR portal ----[3]---- November 28 so we can finalize table seating. Guests are encouraged to use the complimentary shuttle departing from headquarters every twenty minutes ----[4]---- parking near the pavilion is limited."}', '{"info":"Parent passage stimulus"}', 3, 'READING', 'Đoạn văn điền từ TOEIC Part 6 số 3.', 6, '{"translation":"Thông báo tiệc tri ân nhân viên thường niên ngày 12/12 tại Waterfront Pavilion kèm lễ trao giải và xe đưa đón miễn phí.","analysis":"Thông báo tiệc tri ân nhân viên thường niên ngày 12/12 tại Waterfront Pavilion kèm lễ trao giải và xe đưa đón miễn phí.","vocabulary":[]}', NULL, NOW(), NOW()),
(178, 'SINGLE_CHOICE', 'Part 6 G3 Q1: Select the best transition for blank [1].', 1, '{"text":"Select the best transition for blank [1].","options":[{"key":"A","text":"Following dinner"},{"key":"B","text":"On the contrary"},{"key":"C","text":"Even so"},{"key":"D","text":"In contrast"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 1 của Part 6 Passage 3: Announcement of annual staff appreciation banquet.', 6, '{"clue":"''Following dinner'' (Sau bữa tối) dẫn dắt trình tự sự kiện hợp lý.","analysis":"''Following dinner'' (Sau bữa tối) dẫn dắt trình tự sự kiện hợp lý.","translation":"Thông báo tiệc tri ân nhân viên thường niên ngày 12/12 tại Waterfront Pavilion kèm lễ trao giải và xe đưa đón miễn phí.","vocabulary":[]}', 177, NOW(), NOW()),
(179, 'SINGLE_CHOICE', 'Part 6 G3 Q2: Which sentence best fits in blank [2]?', 2, '{"text":"Which sentence best fits in blank [2]?","options":[{"key":"A","text":"A three-course seasonal menu has been prepared by local chefs."},{"key":"B","text":"The payroll system will undergo maintenance on Sunday."},{"key":"C","text":"All quarterly sales targets must be uploaded immediately."},{"key":"D","text":"Please wear safety boots during the warehouse tour."}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 2 của Part 6 Passage 3: Announcement of annual staff appreciation banquet.', 6, '{"clue":"Câu (A) giới thiệu thực đơn 3 món, liên kết trực tiếp với các lựa chọn chay/không gluten câu sau.","analysis":"Câu (A) giới thiệu thực đơn 3 món, liên kết trực tiếp với các lựa chọn chay/không gluten câu sau.","translation":"Thông báo tiệc tri ân nhân viên thường niên ngày 12/12 tại Waterfront Pavilion kèm lễ trao giải và xe đưa đón miễn phí.","vocabulary":[]}', 177, NOW(), NOW()),
(180, 'SINGLE_CHOICE', 'Part 6 G3 Q3: Select the best preposition for blank [3].', 3, '{"text":"Select the best preposition for blank [3].","options":[{"key":"A","text":"no later than"},{"key":"B","text":"as long as"},{"key":"C","text":"in addition to"},{"key":"D","text":"instead of"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 3 của Part 6 Passage 3: Announcement of annual staff appreciation banquet.', 6, '{"clue":"''no later than + ngày'' = chậm nhất là ngày 28/11.","analysis":"''no later than + ngày'' = chậm nhất là ngày 28/11.","translation":"Thông báo tiệc tri ân nhân viên thường niên ngày 12/12 tại Waterfront Pavilion kèm lễ trao giải và xe đưa đón miễn phí.","vocabulary":[]}', 177, NOW(), NOW()),
(181, 'SINGLE_CHOICE', 'Part 6 G3 Q4: Select the best conjunction for blank [4].', 4, '{"text":"Select the best conjunction for blank [4].","options":[{"key":"A","text":"because"},{"key":"B","text":"while"},{"key":"C","text":"unless"},{"key":"D","text":"although"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 4 của Part 6 Passage 3: Announcement of annual staff appreciation banquet.', 6, '{"clue":"''because'' giải thích lý do nên đi xe trung chuyển vì bãi đỗ xe hạn chế.","analysis":"''because'' giải thích lý do nên đi xe trung chuyển vì bãi đỗ xe hạn chế.","translation":"Thông báo tiệc tri ân nhân viên thường niên ngày 12/12 tại Waterfront Pavilion kèm lễ trao giải và xe đưa đón miễn phí.","vocabulary":[]}', 177, NOW(), NOW()),
(182, 'SINGLE_CHOICE', 'Part 6 Passage 4: Product recall and free replacement notice', NULL, '{"text":"Questions refer to the following text (Part 6 Passage 4: Product recall and free replacement notice).","content":"IMPORTANT SAFETY NOTICE\\n\\nNovaHome Appliances is issuing a voluntary replacement program for Model K-400 electric kettles manufactured between January and March. Quality inspections revealed that the handle latch may loosen after prolonged use. ----[1]----, no injuries have been reported to date.\\n\\n----[2]----. Visit novahome.com/support and enter the serial number printed on the base of your kettle to request a free upgraded replacement. ----[3]---- your request is verified, a new unit will ship within five business days. We sincerely regret any ----[4]---- this matter may cause.","passage":"IMPORTANT SAFETY NOTICE\\n\\nNovaHome Appliances is issuing a voluntary replacement program for Model K-400 electric kettles manufactured between January and March. Quality inspections revealed that the handle latch may loosen after prolonged use. ----[1]----, no injuries have been reported to date.\\n\\n----[2]----. Visit novahome.com/support and enter the serial number printed on the base of your kettle to request a free upgraded replacement. ----[3]---- your request is verified, a new unit will ship within five business days. We sincerely regret any ----[4]---- this matter may cause."}', '{"info":"Parent passage stimulus"}', 4, 'READING', 'Đoạn văn điền từ TOEIC Part 6 số 4.', 6, '{"translation":"Thông báo thu hồi và đổi mới miễn phí ấm đun siêu tốc NovaHome K-400 do chốt tay cầm có thể bị lỏng sau thời gian dài sử dụng.","analysis":"Thông báo thu hồi và đổi mới miễn phí ấm đun siêu tốc NovaHome K-400 do chốt tay cầm có thể bị lỏng sau thời gian dài sử dụng.","vocabulary":[]}', NULL, NOW(), NOW()),
(183, 'SINGLE_CHOICE', 'Part 6 G4 Q1: Select the best transition for blank [1].', 1, '{"text":"Select the best transition for blank [1].","options":[{"key":"A","text":"Fortunately"},{"key":"B","text":"Therefore"},{"key":"C","text":"Consequently"},{"key":"D","text":"Similarly"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 1 của Part 6 Passage 4: Product recall and free replacement notice.', 6, '{"clue":"''Fortunately'' (May mắn thay) phù hợp thông tin chưa có thương tích nào được ghi nhận.","analysis":"''Fortunately'' (May mắn thay) phù hợp thông tin chưa có thương tích nào được ghi nhận.","translation":"Thông báo thu hồi và đổi mới miễn phí ấm đun siêu tốc NovaHome K-400 do chốt tay cầm có thể bị lỏng sau thời gian dài sử dụng.","vocabulary":[]}', 182, NOW(), NOW()),
(184, 'SINGLE_CHOICE', 'Part 6 G4 Q2: Which sentence best fits in blank [2]?', 2, '{"text":"Which sentence best fits in blank [2]?","options":[{"key":"A","text":"Customers should discontinue using affected units immediately."},{"key":"B","text":"The kettle is available in three metallic colors."},{"key":"C","text":"Our warranty does not cover commercial coffee shops."},{"key":"D","text":"Store coupons expire at the end of the month."}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền chỗ trống số 2 của Part 6 Passage 4: Product recall and free replacement notice.', 6, '{"clue":"Câu (A) khuyến cáo ngừng dùng ngay trước khi hướng dẫn bước đăng ký đổi sản phẩm mới.","analysis":"Câu (A) khuyến cáo ngừng dùng ngay trước khi hướng dẫn bước đăng ký đổi sản phẩm mới.","translation":"Thông báo thu hồi và đổi mới miễn phí ấm đun siêu tốc NovaHome K-400 do chốt tay cầm có thể bị lỏng sau thời gian dài sử dụng.","vocabulary":[]}', 182, NOW(), NOW()),
(185, 'SINGLE_CHOICE', 'Part 6 G4 Q3: Select the best conjunction for blank [3].', 3, '{"text":"Select the best conjunction for blank [3].","options":[{"key":"A","text":"Once"},{"key":"B","text":"Despite"},{"key":"C","text":"Whereas"},{"key":"D","text":"Until"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 3 của Part 6 Passage 4: Product recall and free replacement notice.', 6, '{"clue":"''Once + mệnh đề'' = Ngay khi yêu cầu được xác minh.","analysis":"''Once + mệnh đề'' = Ngay khi yêu cầu được xác minh.","translation":"Thông báo thu hồi và đổi mới miễn phí ấm đun siêu tốc NovaHome K-400 do chốt tay cầm có thể bị lỏng sau thời gian dài sử dụng.","vocabulary":[]}', 182, NOW(), NOW()),
(186, 'SINGLE_CHOICE', 'Part 6 G4 Q4: Select the best noun for blank [4].', 4, '{"text":"Select the best noun for blank [4].","options":[{"key":"A","text":"inconvenient"},{"key":"B","text":"inconvenience"},{"key":"C","text":"inconveniently"},{"key":"D","text":"convenient"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 4 của Part 6 Passage 4: Product recall and free replacement notice.', 6, '{"clue":"Cụm quen thuộc ''regret any inconvenience'' (rất tiếc vì mọi sự bất tiện).","analysis":"Cụm quen thuộc ''regret any inconvenience'' (rất tiếc vì mọi sự bất tiện).","translation":"Thông báo thu hồi và đổi mới miễn phí ấm đun siêu tốc NovaHome K-400 do chốt tay cầm có thể bị lỏng sau thời gian dài sử dụng.","vocabulary":[]}', 182, NOW(), NOW()),
(187, 'SINGLE_CHOICE', 'Part 6 Passage 5: Newsletter announcing coworking hub expansion', NULL, '{"text":"Questions refer to the following text (Part 6 Passage 5: Newsletter announcing coworking hub expansion).","content":"WorkSpace Collective Newsletter\\n\\nWe are thrilled to announce that our downtown coworking hub is expanding onto the entire seventh floor this August! The additional 12,000 square feet will feature six soundproof podcast booths, four boardrooms, and a sunlit quiet library. ----[1]----, current members will enjoy early-bird access to reserve dedicated private offices.\\n\\n----[2]----. Tours of the renovated space begin Monday, July 20, between 10:00 A.M. and 4:00 P.M. Members who refer a new colleague before August 15 will ----[3]---- a $150 credit toward next month''s dues. We look forward to ----[4]---- your growing business in our upgraded space.","passage":"WorkSpace Collective Newsletter\\n\\nWe are thrilled to announce that our downtown coworking hub is expanding onto the entire seventh floor this August! The additional 12,000 square feet will feature six soundproof podcast booths, four boardrooms, and a sunlit quiet library. ----[1]----, current members will enjoy early-bird access to reserve dedicated private offices.\\n\\n----[2]----. Tours of the renovated space begin Monday, July 20, between 10:00 A.M. and 4:00 P.M. Members who refer a new colleague before August 15 will ----[3]---- a $150 credit toward next month''s dues. We look forward to ----[4]---- your growing business in our upgraded space."}', '{"info":"Parent passage stimulus"}', 4, 'READING', 'Đoạn văn điền từ TOEIC Part 6 số 5.', 6, '{"translation":"Bản tin thông báo mở rộng không gian làm việc chung WorkSpace Collective lên toàn bộ tầng 7 kèm ưu đãi giới thiệu thành viên mới.","analysis":"Bản tin thông báo mở rộng không gian làm việc chung WorkSpace Collective lên toàn bộ tầng 7 kèm ưu đãi giới thiệu thành viên mới.","vocabulary":[]}', NULL, NOW(), NOW()),
(188, 'SINGLE_CHOICE', 'Part 6 G5 Q1: Select the best transition for blank [1].', 1, '{"text":"Select the best transition for blank [1].","options":[{"key":"A","text":"In addition"},{"key":"B","text":"On the other hand"},{"key":"C","text":"Nonetheless"},{"key":"D","text":"As a result"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 1 của Part 6 Passage 5: Newsletter announcing coworking hub expansion.', 6, '{"clue":"''In addition'' bổ sung thêm quyền lợi cho hội viên hiện tại.","analysis":"''In addition'' bổ sung thêm quyền lợi cho hội viên hiện tại.","translation":"Bản tin thông báo mở rộng không gian làm việc chung WorkSpace Collective lên toàn bộ tầng 7 kèm ưu đãi giới thiệu thành viên mới.","vocabulary":[]}', 187, NOW(), NOW()),
(189, 'SINGLE_CHOICE', 'Part 6 G5 Q2: Which sentence best fits in blank [2]?', 2, '{"text":"Which sentence best fits in blank [2]?","options":[{"key":"A","text":"Interested teams can preview the floor plan and book a walkthrough online."},{"key":"B","text":"The building lobby closes promptly at 6:00 P.M."},{"key":"C","text":"Coffee beans are roasted daily in our basement."},{"key":"D","text":"Please return borrowed HDMI adapters to reception."}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi điền chỗ trống số 2 của Part 6 Passage 5: Newsletter announcing coworking hub expansion.', 6, '{"clue":"Câu (A) dẫn trực tiếp sang lịch tham quan ''Tours of the renovated space begin Monday''.","analysis":"Câu (A) dẫn trực tiếp sang lịch tham quan ''Tours of the renovated space begin Monday''.","translation":"Bản tin thông báo mở rộng không gian làm việc chung WorkSpace Collective lên toàn bộ tầng 7 kèm ưu đãi giới thiệu thành viên mới.","vocabulary":[]}', 187, NOW(), NOW()),
(190, 'SINGLE_CHOICE', 'Part 6 G5 Q3: Select the best verb for blank [3].', 3, '{"text":"Select the best verb for blank [3].","options":[{"key":"A","text":"receive"},{"key":"B","text":"received"},{"key":"C","text":"receiving"},{"key":"D","text":"reception"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi điền chỗ trống số 3 của Part 6 Passage 5: Newsletter announcing coworking hub expansion.', 6, '{"clue":"Sau ''will'' dùng động từ nguyên thể ''receive''.","analysis":"Sau ''will'' dùng động từ nguyên thể ''receive''.","translation":"Bản tin thông báo mở rộng không gian làm việc chung WorkSpace Collective lên toàn bộ tầng 7 kèm ưu đãi giới thiệu thành viên mới.","vocabulary":[]}', 187, NOW(), NOW()),
(191, 'SINGLE_CHOICE', 'Part 6 G5 Q4: Select the best verb form for blank [4].', 4, '{"text":"Select the best verb form for blank [4].","options":[{"key":"A","text":"support"},{"key":"B","text":"supporting"},{"key":"C","text":"supported"},{"key":"D","text":"supporter"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi điền chỗ trống số 4 của Part 6 Passage 5: Newsletter announcing coworking hub expansion.', 6, '{"clue":"Cấu trúc ''look forward to + V-ing'' -> ''supporting''.","analysis":"Cấu trúc ''look forward to + V-ing'' -> ''supporting''.","translation":"Bản tin thông báo mở rộng không gian làm việc chung WorkSpace Collective lên toàn bộ tầng 7 kèm ưu đãi giới thiệu thành viên mới.","vocabulary":[]}', 187, NOW(), NOW()),
(192, 'SINGLE_CHOICE', 'Part 7 Passage 1: Job vacancy for Regional Logistics Director', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 1: Job vacancy for Regional Logistics Director).","content":"GLOBAL TRANSIT LOGISTICS CORP.\\nPosition: Director of Regional Logistics | Location: Da Nang Harbor Complex\\n\\nResponsibilities: Oversee maritime and overland freight across Southeast Asia, manage 60 dispatch coordinators, and negotiate carrier contracts with international shipping lines.\\n\\nQualifications:\\n- Bachelor''s degree in Supply Chain Management or related field\\n- Minimum 8 years of progressive logistics management experience\\n- Proficiency with SAP S/4HANA software\\n- Fluent English and Vietnamese\\n\\nBenefits: Competitive salary, biannual performance bonuses, health insurance, and relocation package for non-local hires. Apply to recruitment@globaltransit.com by November 30.","passage":"GLOBAL TRANSIT LOGISTICS CORP.\\nPosition: Director of Regional Logistics | Location: Da Nang Harbor Complex\\n\\nResponsibilities: Oversee maritime and overland freight across Southeast Asia, manage 60 dispatch coordinators, and negotiate carrier contracts with international shipping lines.\\n\\nQualifications:\\n- Bachelor''s degree in Supply Chain Management or related field\\n- Minimum 8 years of progressive logistics management experience\\n- Proficiency with SAP S/4HANA software\\n- Fluent English and Vietnamese\\n\\nBenefits: Competitive salary, biannual performance bonuses, health insurance, and relocation package for non-local hires. Apply to recruitment@globaltransit.com by November 30."}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 1.', 7, '{"translation":"Bản tin tuyển dụng Giám đốc Hậu cần Khu vực tại Đà Nẵng yêu cầu tối thiểu 8 năm kinh nghiệm và thành thạo SAP S/4HANA.","analysis":"Bản tin tuyển dụng Giám đốc Hậu cần Khu vực tại Đà Nẵng yêu cầu tối thiểu 8 năm kinh nghiệm và thành thạo SAP S/4HANA.","vocabulary":[]}', NULL, NOW(), NOW()),
(193, 'SINGLE_CHOICE', 'Part 7 G1 Q1: What is one primary duty of the position?', 1, '{"text":"What is one primary duty of the position?","options":[{"key":"A","text":"Designing corporate software"},{"key":"B","text":"Negotiating carrier contracts with shipping lines"},{"key":"C","text":"Conducting border customs inspections"},{"key":"D","text":"Purchasing cargo ships"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 1: Job vacancy for Regional Logistics Director.', 7, '{"clue":"Nêu trực tiếp ''negotiate carrier contracts with international shipping lines''.","analysis":"Nêu trực tiếp ''negotiate carrier contracts with international shipping lines''.","translation":"Bản tin tuyển dụng Giám đốc Hậu cần Khu vực tại Đà Nẵng yêu cầu tối thiểu 8 năm kinh nghiệm và thành thạo SAP S/4HANA.","vocabulary":[]}', 192, NOW(), NOW()),
(194, 'SINGLE_CHOICE', 'Part 7 G1 Q2: What is a mandatory requirement for applicants?', 2, '{"text":"What is a mandatory requirement for applicants?","options":[{"key":"A","text":"At least 8 years of logistics management experience"},{"key":"B","text":"A Master''s degree in Maritime Law"},{"key":"C","text":"Current residency in Da Nang"},{"key":"D","text":"Fluency in three languages"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 1: Job vacancy for Regional Logistics Director.', 7, '{"clue":"Mục Qualifications yêu cầu tối thiểu 8 năm kinh nghiệm quản lý hậu cần.","analysis":"Mục Qualifications yêu cầu tối thiểu 8 năm kinh nghiệm quản lý hậu cần.","translation":"Bản tin tuyển dụng Giám đốc Hậu cần Khu vực tại Đà Nẵng yêu cầu tối thiểu 8 năm kinh nghiệm và thành thạo SAP S/4HANA.","vocabulary":[]}', 192, NOW(), NOW()),
(195, 'SINGLE_CHOICE', 'Part 7 G1 Q3: What is offered to candidates relocating from other cities?', 3, '{"text":"What is offered to candidates relocating from other cities?","options":[{"key":"A","text":"A company vehicle"},{"key":"B","text":"A relocation package"},{"key":"C","text":"Quarterly stock options"},{"key":"D","text":"Flexible remote hours"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 1: Job vacancy for Regional Logistics Director.', 7, '{"clue":"Mục Benefits nêu rõ ''relocation package for non-local hires''.","analysis":"Mục Benefits nêu rõ ''relocation package for non-local hires''.","translation":"Bản tin tuyển dụng Giám đốc Hậu cần Khu vực tại Đà Nẵng yêu cầu tối thiểu 8 năm kinh nghiệm và thành thạo SAP S/4HANA.","vocabulary":[]}', 192, NOW(), NOW()),
(196, 'SINGLE_CHOICE', 'Part 7 Passage 2: Email regarding software license migration', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 2: Email regarding software license migration).","content":"From: Sofia Lindholm <s.lindholm@nordicsoft.com>\\nTo: All Engineering Staff\\nDate: April 8\\nSubject: Transition to CloudRepo Enterprise\\n\\nTeam,\\nNext Saturday, April 18, from 1:00 A.M. to 5:00 A.M., DevOps will migrate all source repositories from GitBox to CloudRepo Enterprise. During this four-hour window, code pushes will be disabled. Please commit and merge all urgent pull requests by 6:00 P.M. on Friday, April 17. After migration, sign in using your existing single sign-on credentials; no password reset is needed. A quick-start guide is posted on the engineering wiki.","passage":"From: Sofia Lindholm <s.lindholm@nordicsoft.com>\\nTo: All Engineering Staff\\nDate: April 8\\nSubject: Transition to CloudRepo Enterprise\\n\\nTeam,\\nNext Saturday, April 18, from 1:00 A.M. to 5:00 A.M., DevOps will migrate all source repositories from GitBox to CloudRepo Enterprise. During this four-hour window, code pushes will be disabled. Please commit and merge all urgent pull requests by 6:00 P.M. on Friday, April 17. After migration, sign in using your existing single sign-on credentials; no password reset is needed. A quick-start guide is posted on the engineering wiki."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 2.', 7, '{"translation":"Email thông báo chuyển đổi kho mã nguồn sang CloudRepo Enterprise rạng sáng 18/4, yêu cầu hoàn tất merge trước 18h thứ Sáu 17/4.","analysis":"Email thông báo chuyển đổi kho mã nguồn sang CloudRepo Enterprise rạng sáng 18/4, yêu cầu hoàn tất merge trước 18h thứ Sáu 17/4.","vocabulary":[]}', NULL, NOW(), NOW()),
(197, 'SINGLE_CHOICE', 'Part 7 G2 Q1: When will code pushes be temporarily disabled?', 1, '{"text":"When will code pushes be temporarily disabled?","options":[{"key":"A","text":"Friday evening"},{"key":"B","text":"Saturday from 1:00 A.M. to 5:00 A.M."},{"key":"C","text":"Sunday afternoon"},{"key":"D","text":"Monday morning"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 2: Email regarding software license migration.', 7, '{"clue":"Khung giờ bảo trì chuyển đổi là 1:00 A.M. đến 5:00 A.M. thứ Bảy 18/4.","analysis":"Khung giờ bảo trì chuyển đổi là 1:00 A.M. đến 5:00 A.M. thứ Bảy 18/4.","translation":"Email thông báo chuyển đổi kho mã nguồn sang CloudRepo Enterprise rạng sáng 18/4, yêu cầu hoàn tất merge trước 18h thứ Sáu 17/4.","vocabulary":[]}', 196, NOW(), NOW()),
(198, 'SINGLE_CHOICE', 'Part 7 G2 Q2: What are engineers asked to do before 6:00 P.M. on Friday?', 2, '{"text":"What are engineers asked to do before 6:00 P.M. on Friday?","options":[{"key":"A","text":"Reset their passwords"},{"key":"B","text":"Commit and merge urgent pull requests"},{"key":"C","text":"Uninstall GitBox"},{"key":"D","text":"Back up laptops to USB drives"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 2: Email regarding software license migration.', 7, '{"clue":"Yêu cầu commit và merge toàn bộ PR khẩn cấp trước 6 giờ chiều thứ Sáu.","analysis":"Yêu cầu commit và merge toàn bộ PR khẩn cấp trước 6 giờ chiều thứ Sáu.","translation":"Email thông báo chuyển đổi kho mã nguồn sang CloudRepo Enterprise rạng sáng 18/4, yêu cầu hoàn tất merge trước 18h thứ Sáu 17/4.","vocabulary":[]}', 196, NOW(), NOW()),
(199, 'SINGLE_CHOICE', 'Part 7 G2 Q3: How will staff access CloudRepo after the migration?', 3, '{"text":"How will staff access CloudRepo after the migration?","options":[{"key":"A","text":"Using a temporary PIN"},{"key":"B","text":"Using existing single sign-on credentials"},{"key":"C","text":"By requesting an admin invite"},{"key":"D","text":"With a new email address"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 2: Email regarding software license migration.', 7, '{"clue":"Đăng nhập bằng tài khoản SSO hiện có, không cần đặt lại mật khẩu.","analysis":"Đăng nhập bằng tài khoản SSO hiện có, không cần đặt lại mật khẩu.","translation":"Email thông báo chuyển đổi kho mã nguồn sang CloudRepo Enterprise rạng sáng 18/4, yêu cầu hoàn tất merge trước 18h thứ Sáu 17/4.","vocabulary":[]}', 196, NOW(), NOW()),
(200, 'SINGLE_CHOICE', 'Part 7 Passage 3: Press release on electric bus fleet launch', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 3: Press release on electric bus fleet launch).","content":"PRESS RELEASE — Metro Transit Authority\\n\\nMetro Transit Authority today unveiled thirty zero-emission electric buses that will begin operating on Downtown Routes 5 and 12 starting May 1. Built by GreenMotion Vehicles, each bus runs 280 kilometers on a single overnight charge and features USB-C charging ports at every seat. The $18 million investment was partially funded by a federal clean-air grant. Metro Transit plans to convert 75% of its entire fleet to electric vehicles by 2030.","passage":"PRESS RELEASE — Metro Transit Authority\\n\\nMetro Transit Authority today unveiled thirty zero-emission electric buses that will begin operating on Downtown Routes 5 and 12 starting May 1. Built by GreenMotion Vehicles, each bus runs 280 kilometers on a single overnight charge and features USB-C charging ports at every seat. The $18 million investment was partially funded by a federal clean-air grant. Metro Transit plans to convert 75% of its entire fleet to electric vehicles by 2030."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 3.', 7, '{"translation":"Thông cáo báo chí ra mắt 30 xe buýt điện không phát thải chạy tuyến 5 và 12 từ ngày 1/5, đi được 280 km mỗi lần sạc.","analysis":"Thông cáo báo chí ra mắt 30 xe buýt điện không phát thải chạy tuyến 5 và 12 từ ngày 1/5, đi được 280 km mỗi lần sạc.","vocabulary":[]}', NULL, NOW(), NOW());
INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(201, 'SINGLE_CHOICE', 'Part 7 G3 Q1: Where will the new electric buses operate first?', 1, '{"text":"Where will the new electric buses operate first?","options":[{"key":"A","text":"On Airport Express lines"},{"key":"B","text":"On Downtown Routes 5 and 12"},{"key":"C","text":"Across all suburban routes"},{"key":"D","text":"Only on weekends"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 3: Press release on electric bus fleet launch.', 7, '{"clue":"Bắt đầu vận hành trên tuyến trung tâm số 5 và số 12 từ 1/5.","analysis":"Bắt đầu vận hành trên tuyến trung tâm số 5 và số 12 từ 1/5.","translation":"Thông cáo báo chí ra mắt 30 xe buýt điện không phát thải chạy tuyến 5 và 12 từ ngày 1/5, đi được 280 km mỗi lần sạc.","vocabulary":[]}', 200, NOW(), NOW()),
(202, 'SINGLE_CHOICE', 'Part 7 G3 Q2: How far can each bus travel on one charge?', 2, '{"text":"How far can each bus travel on one charge?","options":[{"key":"A","text":"75 kilometers"},{"key":"B","text":"120 kilometers"},{"key":"C","text":"280 kilometers"},{"key":"D","text":"400 kilometers"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 3: Press release on electric bus fleet launch.', 7, '{"clue":"Mỗi lần sạc qua đêm chạy được 280 km.","analysis":"Mỗi lần sạc qua đêm chạy được 280 km.","translation":"Thông cáo báo chí ra mắt 30 xe buýt điện không phát thải chạy tuyến 5 và 12 từ ngày 1/5, đi được 280 km mỗi lần sạc.","vocabulary":[]}', 200, NOW(), NOW()),
(203, 'SINGLE_CHOICE', 'Part 7 G3 Q3: What is Metro Transit''s goal for 2030?', 3, '{"text":"What is Metro Transit''s goal for 2030?","options":[{"key":"A","text":"Lowering ticket fares"},{"key":"B","text":"Converting 75% of its fleet to electric"},{"key":"C","text":"Building its own bus factory"},{"key":"D","text":"Opening twelve new depots"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 3: Press release on electric bus fleet launch.', 7, '{"clue":"Mục tiêu đến năm 2030 chuyển đổi 75% đội xe sang xe điện.","analysis":"Mục tiêu đến năm 2030 chuyển đổi 75% đội xe sang xe điện.","translation":"Thông cáo báo chí ra mắt 30 xe buýt điện không phát thải chạy tuyến 5 và 12 từ ngày 1/5, đi được 280 km mỗi lần sạc.","vocabulary":[]}', 200, NOW(), NOW()),
(204, 'SINGLE_CHOICE', 'Part 7 Passage 4: Client invoice and payment reminder notice', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 4: Client invoice and payment reminder notice).","content":"HARBORVIEW PRINTING & DESIGN\\nInvoice #4491 | Issue Date: March 2 | Due Date: April 1\\nClient: Silverline Realty Group\\n\\nItems:\\n- 2,000 Full-Color Property Brochures: $1,400\\n- 15 Vinyl Open-House Banners: $675\\n- Rush Graphic Layout Adjustment: $225\\nSubtotal: $2,300 | Loyalty Discount (10%): -$230 | Total Due: $2,070\\n\\nNote: Payments made by bank transfer incur no surcharge. Credit card payments over $1,500 carry a 2.5% processing fee. Invoices unpaid after April 10 incur a 1.5% monthly late fee.","passage":"HARBORVIEW PRINTING & DESIGN\\nInvoice #4491 | Issue Date: March 2 | Due Date: April 1\\nClient: Silverline Realty Group\\n\\nItems:\\n- 2,000 Full-Color Property Brochures: $1,400\\n- 15 Vinyl Open-House Banners: $675\\n- Rush Graphic Layout Adjustment: $225\\nSubtotal: $2,300 | Loyalty Discount (10%): -$230 | Total Due: $2,070\\n\\nNote: Payments made by bank transfer incur no surcharge. Credit card payments over $1,500 carry a 2.5% processing fee. Invoices unpaid after April 10 incur a 1.5% monthly late fee."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 4.', 7, '{"translation":"Hóa đơn in ấn #4491 gửi Silverline Realty tổng thanh toán sau giảm 10% là 2.070 đô la, hạn chót 1/4.","analysis":"Hóa đơn in ấn #4491 gửi Silverline Realty tổng thanh toán sau giảm 10% là 2.070 đô la, hạn chót 1/4.","vocabulary":[]}', NULL, NOW(), NOW()),
(205, 'SINGLE_CHOICE', 'Part 7 G4 Q1: What is the final amount Silverline Realty owes?', 1, '{"text":"What is the final amount Silverline Realty owes?","options":[{"key":"A","text":"$2,300"},{"key":"B","text":"$2,070"},{"key":"C","text":"$1,400"},{"key":"D","text":"$2,150"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 4: Client invoice and payment reminder notice.', 7, '{"clue":"Tổng cộng sau chiết khấu khách hàng thân thiết 10% là $2,070.","analysis":"Tổng cộng sau chiết khấu khách hàng thân thiết 10% là $2,070.","translation":"Hóa đơn in ấn #4491 gửi Silverline Realty tổng thanh toán sau giảm 10% là 2.070 đô la, hạn chót 1/4.","vocabulary":[]}', 204, NOW(), NOW()),
(206, 'SINGLE_CHOICE', 'Part 7 G4 Q2: How can the client avoid a 2.5% processing fee?', 2, '{"text":"How can the client avoid a 2.5% processing fee?","options":[{"key":"A","text":"By paying by bank transfer"},{"key":"B","text":"By ordering fewer banners"},{"key":"C","text":"By paying before March 15"},{"key":"D","text":"By picking up brochures in person"}]}', '{"selected":"A","key":"A"}', 3, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 4: Client invoice and payment reminder notice.', 7, '{"clue":"Thanh toán qua chuyển khoản ngân hàng không mất phụ phí.","analysis":"Thanh toán qua chuyển khoản ngân hàng không mất phụ phí.","translation":"Hóa đơn in ấn #4491 gửi Silverline Realty tổng thanh toán sau giảm 10% là 2.070 đô la, hạn chót 1/4.","vocabulary":[]}', 204, NOW(), NOW()),
(207, 'SINGLE_CHOICE', 'Part 7 G4 Q3: When does a late fee begin to apply?', 3, '{"text":"When does a late fee begin to apply?","options":[{"key":"A","text":"After March 2"},{"key":"B","text":"After April 1"},{"key":"C","text":"After April 10"},{"key":"D","text":"After May 1"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 4: Client invoice and payment reminder notice.', 7, '{"clue":"Phí trễ hạn 1.5%/tháng áp dụng cho hóa đơn chưa trả sau ngày 10/4.","analysis":"Phí trễ hạn 1.5%/tháng áp dụng cho hóa đơn chưa trả sau ngày 10/4.","translation":"Hóa đơn in ấn #4491 gửi Silverline Realty tổng thanh toán sau giảm 10% là 2.070 đô la, hạn chót 1/4.","vocabulary":[]}', 204, NOW(), NOW()),
(208, 'SINGLE_CHOICE', 'Part 7 Passage 5: Text message chain between event planners', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 5: Text message chain between event planners).","content":"Text Message Thread — Summit Gala Team\\n[9:14 AM] Maya: Just got to the Grand Ballroom. The florist delivered 20 centerpieces instead of 25!\\n[9:16 AM] Owen: Oh no! Did you call Blossom Studio?\\n[9:18 AM] Maya: Yes, they apologized and are rushing five more arrangements over by 11:30 AM. Good thing guests don''t arrive until 6:00 PM.\\n[9:20 AM] Owen: Whew. Meanwhile, I''m picking up the printed seating charts from QuickPrint and will meet you at the main entrance at 10:15 AM.","passage":"Text Message Thread — Summit Gala Team\\n[9:14 AM] Maya: Just got to the Grand Ballroom. The florist delivered 20 centerpieces instead of 25!\\n[9:16 AM] Owen: Oh no! Did you call Blossom Studio?\\n[9:18 AM] Maya: Yes, they apologized and are rushing five more arrangements over by 11:30 AM. Good thing guests don''t arrive until 6:00 PM.\\n[9:20 AM] Owen: Whew. Meanwhile, I''m picking up the printed seating charts from QuickPrint and will meet you at the main entrance at 10:15 AM."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 5.', 7, '{"translation":"Chuỗi tin nhắn giữa hai nhân viên tổ chức sự kiện xử lý việc tiệm hoa giao thiếu 5 lẵng hoa bàn tiệc.","analysis":"Chuỗi tin nhắn giữa hai nhân viên tổ chức sự kiện xử lý việc tiệm hoa giao thiếu 5 lẵng hoa bàn tiệc.","vocabulary":[]}', NULL, NOW(), NOW()),
(209, 'SINGLE_CHOICE', 'Part 7 G5 Q1: What problem did Maya discover at the ballroom?', 1, '{"text":"What problem did Maya discover at the ballroom?","options":[{"key":"A","text":"The sound system was broken"},{"key":"B","text":"Five flower centerpieces were missing"},{"key":"C","text":"The seating charts had typos"},{"key":"D","text":"The ballroom was locked"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 5: Text message chain between event planners.', 7, '{"clue":"Tiệm hoa chỉ giao 20 lẵng thay vì 25 lẵng như đặt.","analysis":"Tiệm hoa chỉ giao 20 lẵng thay vì 25 lẵng như đặt.","translation":"Chuỗi tin nhắn giữa hai nhân viên tổ chức sự kiện xử lý việc tiệm hoa giao thiếu 5 lẵng hoa bàn tiệc.","vocabulary":[]}', 208, NOW(), NOW()),
(210, 'SINGLE_CHOICE', 'Part 7 G5 Q2: By what time will the remaining flowers arrive?', 2, '{"text":"By what time will the remaining flowers arrive?","options":[{"key":"A","text":"10:15 A.M."},{"key":"B","text":"11:30 A.M."},{"key":"C","text":"1:00 P.M."},{"key":"D","text":"6:00 P.M."}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 5: Text message chain between event planners.', 7, '{"clue":"Blossom Studio đang giao gấp 5 lẵng còn lại trước 11:30 sáng.","analysis":"Blossom Studio đang giao gấp 5 lẵng còn lại trước 11:30 sáng.","translation":"Chuỗi tin nhắn giữa hai nhân viên tổ chức sự kiện xử lý việc tiệm hoa giao thiếu 5 lẵng hoa bàn tiệc.","vocabulary":[]}', 208, NOW(), NOW()),
(211, 'SINGLE_CHOICE', 'Part 7 G5 Q3: What is Owen bringing to the venue?', 3, '{"text":"What is Owen bringing to the venue?","options":[{"key":"A","text":"Guest name badges"},{"key":"B","text":"Printed seating charts"},{"key":"C","text":"Extra tablecloths"},{"key":"D","text":"Stage microphones"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 5: Text message chain between event planners.', 7, '{"clue":"Owen đang lấy sơ đồ chỗ ngồi đã in tại QuickPrint.","analysis":"Owen đang lấy sơ đồ chỗ ngồi đã in tại QuickPrint.","translation":"Chuỗi tin nhắn giữa hai nhân viên tổ chức sự kiện xử lý việc tiệm hoa giao thiếu 5 lẵng hoa bàn tiệc.","vocabulary":[]}', 208, NOW(), NOW()),
(212, 'SINGLE_CHOICE', 'Part 7 Passage 6: Hotel guest welcome letter and spa schedule', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 6: Hotel guest welcome letter and spa schedule).","content":"Welcome to Cedar Ridge Resort!\\n\\nThank you for choosing Cedar Ridge for your stay. Complimentary breakfast is served daily in the Pine Terrace Restaurant from 6:30 A.M. to 10:00 A.M. Our heated outdoor pool remains open until 10:00 P.M., and complimentary towels are provided poolside. Guests booking a 60-minute massage at the Mountain Spa before noon Monday through Thursday receive a 15% weekday discount. Dial extension 0 anytime for concierge assistance.","passage":"Welcome to Cedar Ridge Resort!\\n\\nThank you for choosing Cedar Ridge for your stay. Complimentary breakfast is served daily in the Pine Terrace Restaurant from 6:30 A.M. to 10:00 A.M. Our heated outdoor pool remains open until 10:00 P.M., and complimentary towels are provided poolside. Guests booking a 60-minute massage at the Mountain Spa before noon Monday through Thursday receive a 15% weekday discount. Dial extension 0 anytime for concierge assistance."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 6.', 7, '{"translation":"Thư chào mừng khách tại Cedar Ridge Resort nêu giờ ăn sáng miễn phí, giờ hồ bơi và ưu đãi giảm 15% spa ngày thường trước trưa.","analysis":"Thư chào mừng khách tại Cedar Ridge Resort nêu giờ ăn sáng miễn phí, giờ hồ bơi và ưu đãi giảm 15% spa ngày thường trước trưa.","vocabulary":[]}', NULL, NOW(), NOW()),
(213, 'SINGLE_CHOICE', 'Part 7 G6 Q1: Until what time is complimentary breakfast served?', 1, '{"text":"Until what time is complimentary breakfast served?","options":[{"key":"A","text":"9:00 A.M."},{"key":"B","text":"10:00 A.M."},{"key":"C","text":"11:00 A.M."},{"key":"D","text":"12:00 P.M."}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 6: Hotel guest welcome letter and spa schedule.', 7, '{"clue":"Ăn sáng phục vụ từ 6:30 đến 10:00 sáng.","analysis":"Ăn sáng phục vụ từ 6:30 đến 10:00 sáng.","translation":"Thư chào mừng khách tại Cedar Ridge Resort nêu giờ ăn sáng miễn phí, giờ hồ bơi và ưu đãi giảm 15% spa ngày thường trước trưa.","vocabulary":[]}', 212, NOW(), NOW()),
(214, 'SINGLE_CHOICE', 'Part 7 G6 Q2: Who qualifies for the 15% spa discount?', 2, '{"text":"Who qualifies for the 15% spa discount?","options":[{"key":"A","text":"Weekend guests"},{"key":"B","text":"Guests booking a 60-minute morning massage Mon-Thu"},{"key":"C","text":"Members of a corporate group"},{"key":"D","text":"Guests staying over five nights"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 6: Hotel guest welcome letter and spa schedule.', 7, '{"clue":"Áp dụng cho gói massage 60 phút đặt trước 12 giờ trưa từ thứ Hai đến thứ Năm.","analysis":"Áp dụng cho gói massage 60 phút đặt trước 12 giờ trưa từ thứ Hai đến thứ Năm.","translation":"Thư chào mừng khách tại Cedar Ridge Resort nêu giờ ăn sáng miễn phí, giờ hồ bơi và ưu đãi giảm 15% spa ngày thường trước trưa.","vocabulary":[]}', 212, NOW(), NOW()),
(215, 'SINGLE_CHOICE', 'Part 7 G6 Q3: How can guests reach the concierge?', 3, '{"text":"How can guests reach the concierge?","options":[{"key":"A","text":"By dialing extension 0"},{"key":"B","text":"By emailing the spa"},{"key":"C","text":"By visiting the pool deck"},{"key":"D","text":"Through a mobile QR code"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 6: Hotel guest welcome letter and spa schedule.', 7, '{"clue":"Bấm số nội bộ 0 bất cứ lúc nào.","analysis":"Bấm số nội bộ 0 bất cứ lúc nào.","translation":"Thư chào mừng khách tại Cedar Ridge Resort nêu giờ ăn sáng miễn phí, giờ hồ bơi và ưu đãi giảm 15% spa ngày thường trước trưa.","vocabulary":[]}', 212, NOW(), NOW()),
(216, 'SINGLE_CHOICE', 'Part 7 Passage 7: Product review of noise-canceling headphones', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 7: Product review of noise-canceling headphones).","content":"Customer Review — AeroQuiet Pro Headphones (4.5 / 5 Stars)\\nReviewed by Daniel K. — Verified Buyer\\n\\nI travel twice a month for consulting work and bought the AeroQuiet Pro primarily for long flights. The active noise cancellation easily blocks airplane cabin hum, and the 35-hour battery life lasted my entire round trip to London without recharging. My only minor criticism is that the carrying case is slightly bulky for slim laptop sleeves. Still, for $249, the comfort and call clarity during Zoom meetings make them well worth the price.","passage":"Customer Review — AeroQuiet Pro Headphones (4.5 / 5 Stars)\\nReviewed by Daniel K. — Verified Buyer\\n\\nI travel twice a month for consulting work and bought the AeroQuiet Pro primarily for long flights. The active noise cancellation easily blocks airplane cabin hum, and the 35-hour battery life lasted my entire round trip to London without recharging. My only minor criticism is that the carrying case is slightly bulky for slim laptop sleeves. Still, for $249, the comfort and call clarity during Zoom meetings make them well worth the price."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 7.', 7, '{"translation":"Đánh giá tai nghe chống ồn AeroQuiet Pro: pin 35 giờ đủ chuyến bay khứ hồi London, điểm trừ nhỏ là hộp đựng hơi cồng kềnh.","analysis":"Đánh giá tai nghe chống ồn AeroQuiet Pro: pin 35 giờ đủ chuyến bay khứ hồi London, điểm trừ nhỏ là hộp đựng hơi cồng kềnh.","vocabulary":[]}', NULL, NOW(), NOW()),
(217, 'SINGLE_CHOICE', 'Part 7 G7 Q1: Why did Daniel purchase the headphones?', 1, '{"text":"Why did Daniel purchase the headphones?","options":[{"key":"A","text":"For studio music mixing"},{"key":"B","text":"Mainly for frequent business flights"},{"key":"C","text":"For marathon training"},{"key":"D","text":"As a gift for a client"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 7: Product review of noise-canceling headphones.', 7, '{"clue":"Anh đi công tác 2 lần/tháng và mua chủ yếu cho các chuyến bay dài.","analysis":"Anh đi công tác 2 lần/tháng và mua chủ yếu cho các chuyến bay dài.","translation":"Đánh giá tai nghe chống ồn AeroQuiet Pro: pin 35 giờ đủ chuyến bay khứ hồi London, điểm trừ nhỏ là hộp đựng hơi cồng kềnh.","vocabulary":[]}', 216, NOW(), NOW()),
(218, 'SINGLE_CHOICE', 'Part 7 G7 Q2: What feature impressed Daniel during his London trip?', 2, '{"text":"What feature impressed Daniel during his London trip?","options":[{"key":"A","text":"Waterproof coating"},{"key":"B","text":"35-hour battery life"},{"key":"C","text":"Foldable ear cushions"},{"key":"D","text":"Wireless charging pad"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 7: Product review of noise-canceling headphones.', 7, '{"clue":"Pin 35 giờ chạy trọn chuyến bay khứ hồi không cần sạc lại.","analysis":"Pin 35 giờ chạy trọn chuyến bay khứ hồi không cần sạc lại.","translation":"Đánh giá tai nghe chống ồn AeroQuiet Pro: pin 35 giờ đủ chuyến bay khứ hồi London, điểm trừ nhỏ là hộp đựng hơi cồng kềnh.","vocabulary":[]}', 216, NOW(), NOW()),
(219, 'SINGLE_CHOICE', 'Part 7 G7 Q3: What minor drawback does Daniel mention?', 3, '{"text":"What minor drawback does Daniel mention?","options":[{"key":"A","text":"Weak microphone clarity"},{"key":"B","text":"A slightly bulky carrying case"},{"key":"C","text":"Uncomfortable headband"},{"key":"D","text":"Slow Bluetooth pairing"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 7: Product review of noise-canceling headphones.', 7, '{"clue":"Hộp đựng hơi cồng kềnh khi bỏ vào túi laptop mỏng.","analysis":"Hộp đựng hơi cồng kềnh khi bỏ vào túi laptop mỏng.","translation":"Đánh giá tai nghe chống ồn AeroQuiet Pro: pin 35 giờ đủ chuyến bay khứ hồi London, điểm trừ nhỏ là hộp đựng hơi cồng kềnh.","vocabulary":[]}', 216, NOW(), NOW()),
(220, 'SINGLE_CHOICE', 'Part 7 Passage 8: Company memo on parking garage resurfacing', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 8: Company memo on parking garage resurfacing).","content":"MEMORANDUM — Building Operations\\nDate: August 3 | Subject: Level B2 Parking Resurfacing\\n\\nPlease be advised that Level B2 of the underground parking garage will be closed from Monday, August 10, through Wednesday, August 12, for epoxy floor resurfacing. All vehicles must be removed from Level B2 by 8:00 P.M. on Sunday, August 9. During this three-day period, employees with B2 permits may park at no cost in the overflow surface lot across Oak Street by showing their building badge to the attendant.","passage":"MEMORANDUM — Building Operations\\nDate: August 3 | Subject: Level B2 Parking Resurfacing\\n\\nPlease be advised that Level B2 of the underground parking garage will be closed from Monday, August 10, through Wednesday, August 12, for epoxy floor resurfacing. All vehicles must be removed from Level B2 by 8:00 P.M. on Sunday, August 9. During this three-day period, employees with B2 permits may park at no cost in the overflow surface lot across Oak Street by showing their building badge to the attendant."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 8.', 7, '{"translation":"Thông báo đóng cửa tầng hầm B2 từ 10-12/8 để phủ sàn epoxy, nhân viên có thẻ B2 được đỗ miễn phí tại bãi ngoài trời bên kia đường Oak.","analysis":"Thông báo đóng cửa tầng hầm B2 từ 10-12/8 để phủ sàn epoxy, nhân viên có thẻ B2 được đỗ miễn phí tại bãi ngoài trời bên kia đường Oak.","vocabulary":[]}', NULL, NOW(), NOW()),
(221, 'SINGLE_CHOICE', 'Part 7 G8 Q1: How long will Level B2 be closed?', 1, '{"text":"How long will Level B2 be closed?","options":[{"key":"A","text":"One day"},{"key":"B","text":"Three days"},{"key":"C","text":"One week"},{"key":"D","text":"Two weeks"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 8: Company memo on parking garage resurfacing.', 7, '{"clue":"Đóng cửa từ thứ Hai 10/8 đến hết thứ Tư 12/8 (3 ngày).","analysis":"Đóng cửa từ thứ Hai 10/8 đến hết thứ Tư 12/8 (3 ngày).","translation":"Thông báo đóng cửa tầng hầm B2 từ 10-12/8 để phủ sàn epoxy, nhân viên có thẻ B2 được đỗ miễn phí tại bãi ngoài trời bên kia đường Oak.","vocabulary":[]}', 220, NOW(), NOW()),
(222, 'SINGLE_CHOICE', 'Part 7 G8 Q2: By when must cars be moved out of Level B2?', 2, '{"text":"By when must cars be moved out of Level B2?","options":[{"key":"A","text":"Friday at 5:00 P.M."},{"key":"B","text":"Sunday at 8:00 P.M."},{"key":"C","text":"Monday at 7:00 A.M."},{"key":"D","text":"Wednesday at 6:00 P.M."}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 8: Company memo on parking garage resurfacing.', 7, '{"clue":"Yêu cầu di dời xe trước 8:00 tối Chủ nhật ngày 9/8.","analysis":"Yêu cầu di dời xe trước 8:00 tối Chủ nhật ngày 9/8.","translation":"Thông báo đóng cửa tầng hầm B2 từ 10-12/8 để phủ sàn epoxy, nhân viên có thẻ B2 được đỗ miễn phí tại bãi ngoài trời bên kia đường Oak.","vocabulary":[]}', 220, NOW(), NOW()),
(223, 'SINGLE_CHOICE', 'Part 7 G8 Q3: What must B2 permit holders show at the overflow lot?', 3, '{"text":"What must B2 permit holders show at the overflow lot?","options":[{"key":"A","text":"Their driver''s license"},{"key":"B","text":"Their building badge"},{"key":"C","text":"A printed email"},{"key":"D","text":"A parking receipt"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 8: Company memo on parking garage resurfacing.', 7, '{"clue":"Xuất trình thẻ tòa nhà (''building badge'') cho nhân viên trông xe.","analysis":"Xuất trình thẻ tòa nhà (''building badge'') cho nhân viên trông xe.","translation":"Thông báo đóng cửa tầng hầm B2 từ 10-12/8 để phủ sàn epoxy, nhân viên có thẻ B2 được đỗ miễn phí tại bãi ngoài trời bên kia đường Oak.","vocabulary":[]}', 220, NOW(), NOW()),
(224, 'SINGLE_CHOICE', 'Part 7 Passage 9: Advertisement for executive leadership certificate', NULL, '{"text":"Questions refer to the following passage (Part 7 Passage 9: Advertisement for executive leadership certificate).","content":"WESTCOAST BUSINESS INSTITUTE\\nCertificate in Strategic Digital Leadership (6-Week Online Program)\\n\\nDesigned for mid-career managers transitioning into executive roles, this live online program covers financial modeling, AI-driven operations, and cross-functional team leadership. Classes meet Tuesdays and Thursdays from 6:30 P.M. to 8:30 P.M. PST, with recorded replays available for 90 days. Tuition is $1,850; however, companies enrolling three or more managers receive a 20% corporate group discount. Next cohort begins September 15.","passage":"WESTCOAST BUSINESS INSTITUTE\\nCertificate in Strategic Digital Leadership (6-Week Online Program)\\n\\nDesigned for mid-career managers transitioning into executive roles, this live online program covers financial modeling, AI-driven operations, and cross-functional team leadership. Classes meet Tuesdays and Thursdays from 6:30 P.M. to 8:30 P.M. PST, with recorded replays available for 90 days. Tuition is $1,850; however, companies enrolling three or more managers receive a 20% corporate group discount. Next cohort begins September 15."}', '{"info":"Parent reading passage stimulus"}', 3, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 9.', 7, '{"translation":"Quảng cáo khóa chứng chỉ Lãnh đạo số chiến lược 6 tuần trực tuyến của Westcoast Business Institute, giảm 20% cho nhóm doanh nghiệp từ 3 người.","analysis":"Quảng cáo khóa chứng chỉ Lãnh đạo số chiến lược 6 tuần trực tuyến của Westcoast Business Institute, giảm 20% cho nhóm doanh nghiệp từ 3 người.","vocabulary":[]}', NULL, NOW(), NOW()),
(225, 'SINGLE_CHOICE', 'Part 7 G9 Q1: Who is the primary target audience for this program?', 1, '{"text":"Who is the primary target audience for this program?","options":[{"key":"A","text":"Undergraduate students"},{"key":"B","text":"Mid-career managers moving to executive roles"},{"key":"C","text":"Software interns"},{"key":"D","text":"Retired executives"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Passage 9: Advertisement for executive leadership certificate.', 7, '{"clue":"Thiết kế cho quản lý cấp trung chuyển lên vị trí điều hành.","analysis":"Thiết kế cho quản lý cấp trung chuyển lên vị trí điều hành.","translation":"Quảng cáo khóa chứng chỉ Lãnh đạo số chiến lược 6 tuần trực tuyến của Westcoast Business Institute, giảm 20% cho nhóm doanh nghiệp từ 3 người.","vocabulary":[]}', 224, NOW(), NOW()),
(226, 'SINGLE_CHOICE', 'Part 7 G9 Q2: How long can participants access class recordings?', 2, '{"text":"How long can participants access class recordings?","options":[{"key":"A","text":"For 6 weeks"},{"key":"B","text":"For 30 days"},{"key":"C","text":"For 90 days"},{"key":"D","text":"Indefinitely"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Passage 9: Advertisement for executive leadership certificate.', 7, '{"clue":"Bản ghi xem lại có hiệu lực trong 90 ngày.","analysis":"Bản ghi xem lại có hiệu lực trong 90 ngày.","translation":"Quảng cáo khóa chứng chỉ Lãnh đạo số chiến lược 6 tuần trực tuyến của Westcoast Business Institute, giảm 20% cho nhóm doanh nghiệp từ 3 người.","vocabulary":[]}', 224, NOW(), NOW()),
(227, 'SINGLE_CHOICE', 'Part 7 G9 Q3: How can a company qualify for the 20% discount?', 3, '{"text":"How can a company qualify for the 20% discount?","options":[{"key":"A","text":"By paying in cash"},{"key":"B","text":"By enrolling three or more managers"},{"key":"C","text":"By registering six months early"},{"key":"D","text":"By sponsoring a guest lecture"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Passage 9: Advertisement for executive leadership certificate.', 7, '{"clue":"Doanh nghiệp đăng ký từ 3 quản lý trở lên được giảm 20%.","analysis":"Doanh nghiệp đăng ký từ 3 quản lý trở lên được giảm 20%.","translation":"Quảng cáo khóa chứng chỉ Lãnh đạo số chiến lược 6 tuần trực tuyến của Westcoast Business Institute, giảm 20% cho nhóm doanh nghiệp từ 3 người.","vocabulary":[]}', 224, NOW(), NOW()),
(228, 'SINGLE_CHOICE', 'Part 7 Double Passage 10: Conference schedule & speaker email', NULL, '{"text":"Questions refer to the following passage (Part 7 Double Passage 10: Conference schedule & speaker email).","content":"[DOCUMENT 1 — SCHEDULE: Pacific FinTech Summit, Oct 22]\\n09:00 A.M. Opening Keynote — Dr. Alan Cho (Hall A)\\n10:30 A.M. Cross-Border Payments Panel — Priya Nair (Room 201)\\n01:30 P.M. Fraud Detection with AI — Marco Rossi (Hall A)\\n03:00 P.M. Regulatory Compliance Workshop — Linda Park (Room 204)\\n\\n[DOCUMENT 2 — EMAIL]\\nFrom: Marco Rossi | To: Summit Organizers | Date: Oct 19\\nMy morning train from Milan was canceled, so I won''t land until 1:45 P.M. on October 22. Could we swap my Hall A session with Linda Park''s 3:00 P.M. slot? Linda already confirmed by phone that she can present at 1:30 P.M. instead.","passage":"[DOCUMENT 1 — SCHEDULE: Pacific FinTech Summit, Oct 22]\\n09:00 A.M. Opening Keynote — Dr. Alan Cho (Hall A)\\n10:30 A.M. Cross-Border Payments Panel — Priya Nair (Room 201)\\n01:30 P.M. Fraud Detection with AI — Marco Rossi (Hall A)\\n03:00 P.M. Regulatory Compliance Workshop — Linda Park (Room 204)\\n\\n[DOCUMENT 2 — EMAIL]\\nFrom: Marco Rossi | To: Summit Organizers | Date: Oct 19\\nMy morning train from Milan was canceled, so I won''t land until 1:45 P.M. on October 22. Could we swap my Hall A session with Linda Park''s 3:00 P.M. slot? Linda already confirmed by phone that she can present at 1:30 P.M. instead."}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 10.', 7, '{"translation":"Đoạn đôi: Lịch hội thảo FinTech ngày 22/10 và email của diễn giả Marco Rossi xin đổi khung giờ 1:30 chiều với Linda Park sang 3:00 chiều.","analysis":"Đoạn đôi: Lịch hội thảo FinTech ngày 22/10 và email của diễn giả Marco Rossi xin đổi khung giờ 1:30 chiều với Linda Park sang 3:00 chiều.","vocabulary":[]}', NULL, NOW(), NOW()),
(229, 'SINGLE_CHOICE', 'Part 7 G10 Q1: What topic will Linda Park present?', 1, '{"text":"What topic will Linda Park present?","options":[{"key":"A","text":"Opening Keynote"},{"key":"B","text":"Cross-Border Payments"},{"key":"C","text":"Fraud Detection with AI"},{"key":"D","text":"Regulatory Compliance Workshop"}]}', '{"selected":"D","key":"D"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Double Passage 10: Conference schedule & speaker email.', 7, '{"clue":"Đối chiếu Văn bản 1: Linda Park phụ trách ''Regulatory Compliance Workshop''.","analysis":"Đối chiếu Văn bản 1: Linda Park phụ trách ''Regulatory Compliance Workshop''.","translation":"Đoạn đôi: Lịch hội thảo FinTech ngày 22/10 và email của diễn giả Marco Rossi xin đổi khung giờ 1:30 chiều với Linda Park sang 3:00 chiều.","vocabulary":[]}', 228, NOW(), NOW()),
(230, 'SINGLE_CHOICE', 'Part 7 G10 Q2: At what time will Marco Rossi most likely give his talk now?', 2, '{"text":"At what time will Marco Rossi most likely give his talk now?","options":[{"key":"A","text":"9:00 A.M."},{"key":"B","text":"10:30 A.M."},{"key":"C","text":"1:30 P.M."},{"key":"D","text":"3:00 P.M."}]}', '{"selected":"D","key":"D"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Double Passage 10: Conference schedule & speaker email.', 7, '{"clue":"Xâu chuỗi 2 văn bản: Marco đổi từ 1:30 P.M. sang khung giờ của Linda Park là 3:00 P.M.","analysis":"Xâu chuỗi 2 văn bản: Marco đổi từ 1:30 P.M. sang khung giờ của Linda Park là 3:00 P.M.","translation":"Đoạn đôi: Lịch hội thảo FinTech ngày 22/10 và email của diễn giả Marco Rossi xin đổi khung giờ 1:30 chiều với Linda Park sang 3:00 chiều.","vocabulary":[]}', 228, NOW(), NOW()),
(231, 'SINGLE_CHOICE', 'Part 7 G10 Q3: Why did Marco need to adjust his presentation time?', 3, '{"text":"Why did Marco need to adjust his presentation time?","options":[{"key":"A","text":"He had a scheduling conflict in Hall A"},{"key":"B","text":"His train cancellation delayed his arrival"},{"key":"C","text":"His slides were not ready"},{"key":"D","text":"Linda Park requested an earlier slot"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Double Passage 10: Conference schedule & speaker email.', 7, '{"clue":"Văn bản 2 nêu rõ tàu từ Milan bị hủy khiến anh hạ cánh lúc 1:45 chiều.","analysis":"Văn bản 2 nêu rõ tàu từ Milan bị hủy khiến anh hạ cánh lúc 1:45 chiều.","translation":"Đoạn đôi: Lịch hội thảo FinTech ngày 22/10 và email của diễn giả Marco Rossi xin đổi khung giờ 1:30 chiều với Linda Park sang 3:00 chiều.","vocabulary":[]}', 228, NOW(), NOW()),
(232, 'SINGLE_CHOICE', 'Part 7 Double Passage 11: Catering menu & corporate order email', NULL, '{"text":"Questions refer to the following passage (Part 7 Double Passage 11: Catering menu & corporate order email).","content":"[DOCUMENT 1 — SAVORY BITES CATERING MENU]\\nPackage A (Executive Boxed Lunch): $18/person (min 15 guests)\\nPackage B (Mediterranean Hot Buffet): $28/person (min 25 guests)\\nPackage C (Artisan Breakfast Spread): $14/person (min 20 guests)\\nAdd-on Coffee & Tea Urn Service: $4/person | Delivery within 10 km: Free (otherwise $45)\\n\\n[DOCUMENT 2 — EMAIL]\\nFrom: Claire Wu (Vanguard Bio, 14 km from kitchen) | To: Savory Bites\\nWe would like to order the Mediterranean Hot Buffet plus Coffee & Tea Service for 30 scientists attending our lab symposium on May 14. Please include 5 vegetarian entrees at no extra cost as discussed.","passage":"[DOCUMENT 1 — SAVORY BITES CATERING MENU]\\nPackage A (Executive Boxed Lunch): $18/person (min 15 guests)\\nPackage B (Mediterranean Hot Buffet): $28/person (min 25 guests)\\nPackage C (Artisan Breakfast Spread): $14/person (min 20 guests)\\nAdd-on Coffee & Tea Urn Service: $4/person | Delivery within 10 km: Free (otherwise $45)\\n\\n[DOCUMENT 2 — EMAIL]\\nFrom: Claire Wu (Vanguard Bio, 14 km from kitchen) | To: Savory Bites\\nWe would like to order the Mediterranean Hot Buffet plus Coffee & Tea Service for 30 scientists attending our lab symposium on May 14. Please include 5 vegetarian entrees at no extra cost as discussed."}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 11.', 7, '{"translation":"Đoạn đôi: Thực đơn đặt tiệc Savory Bites và email đặt gói Mediterranean Buffet + trà cà phê cho 30 khách ở khoảng cách 14 km.","analysis":"Đoạn đôi: Thực đơn đặt tiệc Savory Bites và email đặt gói Mediterranean Buffet + trà cà phê cho 30 khách ở khoảng cách 14 km.","vocabulary":[]}', NULL, NOW(), NOW()),
(233, 'SINGLE_CHOICE', 'Part 7 G11 Q1: Which catering package did Vanguard Bio select?', 1, '{"text":"Which catering package did Vanguard Bio select?","options":[{"key":"A","text":"Package A"},{"key":"B","text":"Package B"},{"key":"C","text":"Package C"},{"key":"D","text":"Breakfast only"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Double Passage 11: Catering menu & corporate order email.', 7, '{"clue":"Đối chiếu Văn bản 1 & 2: Mediterranean Hot Buffet là Package B.","analysis":"Đối chiếu Văn bản 1 & 2: Mediterranean Hot Buffet là Package B.","translation":"Đoạn đôi: Thực đơn đặt tiệc Savory Bites và email đặt gói Mediterranean Buffet + trà cà phê cho 30 khách ở khoảng cách 14 km.","vocabulary":[]}', 232, NOW(), NOW()),
(234, 'SINGLE_CHOICE', 'Part 7 G11 Q2: How much will Vanguard Bio pay for delivery?', 2, '{"text":"How much will Vanguard Bio pay for delivery?","options":[{"key":"A","text":"$0"},{"key":"B","text":"$14"},{"key":"C","text":"$30"},{"key":"D","text":"$45"}]}', '{"selected":"D","key":"D"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Double Passage 11: Catering menu & corporate order email.', 7, '{"clue":"Xâu chuỗi: Văn bản 2 ghi khoảng cách 14 km (> 10 km miễn phí ở Văn bản 1) -> phí giao hàng $45.","analysis":"Xâu chuỗi: Văn bản 2 ghi khoảng cách 14 km (> 10 km miễn phí ở Văn bản 1) -> phí giao hàng $45.","translation":"Đoạn đôi: Thực đơn đặt tiệc Savory Bites và email đặt gói Mediterranean Buffet + trà cà phê cho 30 khách ở khoảng cách 14 km.","vocabulary":[]}', 232, NOW(), NOW()),
(235, 'SINGLE_CHOICE', 'Part 7 G11 Q3: What is the per-person food and beverage rate (excluding delivery)?', 3, '{"text":"What is the per-person food and beverage rate (excluding delivery)?","options":[{"key":"A","text":"$18"},{"key":"B","text":"$28"},{"key":"C","text":"$32"},{"key":"D","text":"$36"}]}', '{"selected":"C","key":"C"}', 4, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Double Passage 11: Catering menu & corporate order email.', 7, '{"clue":"Package B ($28) + Coffee & Tea Service ($4) = $32/người.","analysis":"Package B ($28) + Coffee & Tea Service ($4) = $32/người.","translation":"Đoạn đôi: Thực đơn đặt tiệc Savory Bites và email đặt gói Mediterranean Buffet + trà cà phê cho 30 khách ở khoảng cách 14 km.","vocabulary":[]}', 232, NOW(), NOW()),
(236, 'SINGLE_CHOICE', 'Part 7 Double Passage 12: Shipping rate chart & customer inquiry', NULL, '{"text":"Questions refer to the following passage (Part 7 Double Passage 12: Shipping rate chart & customer inquiry).","content":"[DOCUMENT 1 — SWIFTPOST SHIPPING TIERS]\\nEconomy Ground (5-7 days): $12 | Standard Air (2-3 days): $24 | Priority Overnight (Next Day 10 AM): $48\\nInsurance: Free up to $200 value; $8 flat fee for parcels valued $201-$1,000.\\n\\n[DOCUMENT 2 — SUPPORT CHAT]\\nCustomer (Kenji): I need to send a calibrated medical thermometer worth $650 to our Osaka clinic so it arrives by tomorrow morning at 9:30 A.M.\\nAgent: We can dispatch that via our fastest tier today and add full parcel protection.","passage":"[DOCUMENT 1 — SWIFTPOST SHIPPING TIERS]\\nEconomy Ground (5-7 days): $12 | Standard Air (2-3 days): $24 | Priority Overnight (Next Day 10 AM): $48\\nInsurance: Free up to $200 value; $8 flat fee for parcels valued $201-$1,000.\\n\\n[DOCUMENT 2 — SUPPORT CHAT]\\nCustomer (Kenji): I need to send a calibrated medical thermometer worth $650 to our Osaka clinic so it arrives by tomorrow morning at 9:30 A.M.\\nAgent: We can dispatch that via our fastest tier today and add full parcel protection."}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 12.', 7, '{"translation":"Đoạn đôi: Bảng giá vận chuyển SwiftPost và đoạn chat khách cần gửi thiết bị trị giá 650 đô đến sáng hôm sau.","analysis":"Đoạn đôi: Bảng giá vận chuyển SwiftPost và đoạn chat khách cần gửi thiết bị trị giá 650 đô đến sáng hôm sau.","vocabulary":[]}', NULL, NOW(), NOW()),
(237, 'SINGLE_CHOICE', 'Part 7 G12 Q1: Which shipping tier fits Kenji''s deadline?', 1, '{"text":"Which shipping tier fits Kenji''s deadline?","options":[{"key":"A","text":"Economy Ground"},{"key":"B","text":"Standard Air"},{"key":"C","text":"Priority Overnight"},{"key":"D","text":"International Sea"}]}', '{"selected":"C","key":"C"}', 3, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Double Passage 12: Shipping rate chart & customer inquiry.', 7, '{"clue":"Cần đến sáng hôm sau -> chọn Priority Overnight ($48).","analysis":"Cần đến sáng hôm sau -> chọn Priority Overnight ($48).","translation":"Đoạn đôi: Bảng giá vận chuyển SwiftPost và đoạn chat khách cần gửi thiết bị trị giá 650 đô đến sáng hôm sau.","vocabulary":[]}', 236, NOW(), NOW()),
(238, 'SINGLE_CHOICE', 'Part 7 G12 Q2: How much will insurance cost for Kenji''s parcel?', 2, '{"text":"How much will insurance cost for Kenji''s parcel?","options":[{"key":"A","text":"$0"},{"key":"B","text":"$8"},{"key":"C","text":"$12"},{"key":"D","text":"$24"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Double Passage 12: Shipping rate chart & customer inquiry.', 7, '{"clue":"Giá trị hàng $650 nằm trong khoảng $201-$1,000 -> phí bảo hiểm $8.","analysis":"Giá trị hàng $650 nằm trong khoảng $201-$1,000 -> phí bảo hiểm $8.","translation":"Đoạn đôi: Bảng giá vận chuyển SwiftPost và đoạn chat khách cần gửi thiết bị trị giá 650 đô đến sáng hôm sau.","vocabulary":[]}', 236, NOW(), NOW()),
(239, 'SINGLE_CHOICE', 'Part 7 G12 Q3: What is the total shipping and insurance charge?', 3, '{"text":"What is the total shipping and insurance charge?","options":[{"key":"A","text":"$24"},{"key":"B","text":"$48"},{"key":"C","text":"$56"},{"key":"D","text":"$60"}]}', '{"selected":"C","key":"C"}', 4, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Double Passage 12: Shipping rate chart & customer inquiry.', 7, '{"clue":"Priority Overnight ($48) + bảo hiểm ($8) = $56.","analysis":"Priority Overnight ($48) + bảo hiểm ($8) = $56.","translation":"Đoạn đôi: Bảng giá vận chuyển SwiftPost và đoạn chat khách cần gửi thiết bị trị giá 650 đô đến sáng hôm sau.","vocabulary":[]}', 236, NOW(), NOW()),
(240, 'SINGLE_CHOICE', 'Part 7 Double Passage 13: Office lease policy & tenant request email', NULL, '{"text":"Questions refer to the following passage (Part 7 Double Passage 13: Office lease policy & tenant request email).","content":"[DOCUMENT 1 — HARBOR TOWER TENANT HANDBOOK]\\nFreight Elevator Hours: Mon-Fri 7:00 A.M.-6:00 P.M.; Sat 8:00 A.M.-2:00 P.M.\\nAny equipment delivery exceeding 300 kg requires 48 hours advance written notice to Building Management and a refundable $500 floor-protection deposit.\\n\\n[DOCUMENT 2 — EMAIL]\\nFrom: Victor Morales (Suite 1204) | Sent: Tuesday, June 2, 10:00 A.M.\\nWe are having a 450 kg commercial server rack delivered this Friday morning at 9:00 A.M. Attached is our building insurance certificate, and our accounting team will drop off the required deposit check this afternoon.","passage":"[DOCUMENT 1 — HARBOR TOWER TENANT HANDBOOK]\\nFreight Elevator Hours: Mon-Fri 7:00 A.M.-6:00 P.M.; Sat 8:00 A.M.-2:00 P.M.\\nAny equipment delivery exceeding 300 kg requires 48 hours advance written notice to Building Management and a refundable $500 floor-protection deposit.\\n\\n[DOCUMENT 2 — EMAIL]\\nFrom: Victor Morales (Suite 1204) | Sent: Tuesday, June 2, 10:00 A.M.\\nWe are having a 450 kg commercial server rack delivered this Friday morning at 9:00 A.M. Attached is our building insurance certificate, and our accounting team will drop off the required deposit check this afternoon."}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 13.', 7, '{"translation":"Đoạn đôi: Nội quy vận chuyển thang máy hàng tòa nhà Harbor Tower và email xin phép chuyển tủ máy chủ 450 kg sáng thứ Sáu.","analysis":"Đoạn đôi: Nội quy vận chuyển thang máy hàng tòa nhà Harbor Tower và email xin phép chuyển tủ máy chủ 450 kg sáng thứ Sáu.","vocabulary":[]}', NULL, NOW(), NOW());
INSERT INTO questions (id, type, name, order_no, question_data, correct_answer, difficulty, sections, descriptions, part_id, explanation, parent_id, created_at, updated_at) VALUES
(241, 'SINGLE_CHOICE', 'Part 7 G13 Q1: Why must Suite 1204 submit advance written notice?', 1, '{"text":"Why must Suite 1204 submit advance written notice?","options":[{"key":"A","text":"The delivery occurs on a Sunday"},{"key":"B","text":"The server rack weighs over 300 kg"},{"key":"C","text":"They need after-hours access"},{"key":"D","text":"They are moving out of the tower"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Double Passage 13: Office lease policy & tenant request email.', 7, '{"clue":"Tủ máy chủ nặng 450 kg vượt ngưỡng 300 kg trong quy định.","analysis":"Tủ máy chủ nặng 450 kg vượt ngưỡng 300 kg trong quy định.","translation":"Đoạn đôi: Nội quy vận chuyển thang máy hàng tòa nhà Harbor Tower và email xin phép chuyển tủ máy chủ 450 kg sáng thứ Sáu.","vocabulary":[]}', 240, NOW(), NOW()),
(242, 'SINGLE_CHOICE', 'Part 7 G13 Q2: How much is the deposit check accounting will drop off?', 2, '{"text":"How much is the deposit check accounting will drop off?","options":[{"key":"A","text":"$150"},{"key":"B","text":"$300"},{"key":"C","text":"$450"},{"key":"D","text":"$500"}]}', '{"selected":"D","key":"D"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Double Passage 13: Office lease policy & tenant request email.', 7, '{"clue":"Đối chiếu Văn bản 1: khoản đặt cọc hoàn lại bảo vệ sàn là $500.","analysis":"Đối chiếu Văn bản 1: khoản đặt cọc hoàn lại bảo vệ sàn là $500.","translation":"Đoạn đôi: Nội quy vận chuyển thang máy hàng tòa nhà Harbor Tower và email xin phép chuyển tủ máy chủ 450 kg sáng thứ Sáu.","vocabulary":[]}', 240, NOW(), NOW()),
(243, 'SINGLE_CHOICE', 'Part 7 G13 Q3: Did Victor meet the 48-hour notice requirement?', 3, '{"text":"Did Victor meet the 48-hour notice requirement?","options":[{"key":"A","text":"Yes, he emailed three days before Friday"},{"key":"B","text":"No, he emailed too late"},{"key":"C","text":"No, freight elevators are closed Fridays"},{"key":"D","text":"Only if delivery moves to Saturday"}]}', '{"selected":"A","key":"A"}', 4, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Double Passage 13: Office lease policy & tenant request email.', 7, '{"clue":"Gửi sáng thứ Ba 2/6 cho lịch sáng thứ Sáu 5/6 (hơn 70 giờ > 48 giờ).","analysis":"Gửi sáng thứ Ba 2/6 cho lịch sáng thứ Sáu 5/6 (hơn 70 giờ > 48 giờ).","translation":"Đoạn đôi: Nội quy vận chuyển thang máy hàng tòa nhà Harbor Tower và email xin phép chuyển tủ máy chủ 450 kg sáng thứ Sáu.","vocabulary":[]}', 240, NOW(), NOW()),
(244, 'SINGLE_CHOICE', 'Part 7 Double Passage 14: Training course catalog & HR approval memo', NULL, '{"text":"Questions refer to the following passage (Part 7 Double Passage 14: Training course catalog & HR approval memo).","content":"[DOCUMENT 1 — TECHSKILL ACADEMY FALL SCHEDULE]\\nCourse DA-101: SQL for Business Analysts — $600 (Oct 5-7, Online)\\nCourse PM-204: Agile Product Delivery — $850 (Oct 12-14, In-Person)\\nCourse CY-305: Cloud Security Architecture — $1,100 (Oct 19-21, Online)\\n\\n[DOCUMENT 2 — HR TRAINING APPROVAL]\\nEmployee: Nadia Hassan | Annual Training Allowance Remaining: $900\\nManager Note: Approved for Nadia''s requested October in-person course at TechSkill Academy. Since her allowance covers the full tuition, no employee co-pay is required.","passage":"[DOCUMENT 1 — TECHSKILL ACADEMY FALL SCHEDULE]\\nCourse DA-101: SQL for Business Analysts — $600 (Oct 5-7, Online)\\nCourse PM-204: Agile Product Delivery — $850 (Oct 12-14, In-Person)\\nCourse CY-305: Cloud Security Architecture — $1,100 (Oct 19-21, Online)\\n\\n[DOCUMENT 2 — HR TRAINING APPROVAL]\\nEmployee: Nadia Hassan | Annual Training Allowance Remaining: $900\\nManager Note: Approved for Nadia''s requested October in-person course at TechSkill Academy. Since her allowance covers the full tuition, no employee co-pay is required."}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 14.', 7, '{"translation":"Đoạn đôi: Danh mục khóa học TechSkill Academy và phiếu duyệt đào tạo cho nhân viên Nadia Hassan (hạn mức còn 900 đô, khóa trực tiếp).","analysis":"Đoạn đôi: Danh mục khóa học TechSkill Academy và phiếu duyệt đào tạo cho nhân viên Nadia Hassan (hạn mức còn 900 đô, khóa trực tiếp).","vocabulary":[]}', NULL, NOW(), NOW()),
(245, 'SINGLE_CHOICE', 'Part 7 G14 Q1: Which course was Nadia approved to take?', 1, '{"text":"Which course was Nadia approved to take?","options":[{"key":"A","text":"SQL for Business Analysts"},{"key":"B","text":"Agile Product Delivery"},{"key":"C","text":"Cloud Security Architecture"},{"key":"D","text":"All three courses"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Double Passage 14: Training course catalog & HR approval memo.', 7, '{"clue":"Khóa học duy nhất hình thức trực tiếp (''In-Person'') là PM-204 Agile Product Delivery.","analysis":"Khóa học duy nhất hình thức trực tiếp (''In-Person'') là PM-204 Agile Product Delivery.","translation":"Đoạn đôi: Danh mục khóa học TechSkill Academy và phiếu duyệt đào tạo cho nhân viên Nadia Hassan (hạn mức còn 900 đô, khóa trực tiếp).","vocabulary":[]}', 244, NOW(), NOW()),
(246, 'SINGLE_CHOICE', 'Part 7 G14 Q2: How much training allowance will Nadia have left after this course?', 2, '{"text":"How much training allowance will Nadia have left after this course?","options":[{"key":"A","text":"$0"},{"key":"B","text":"$50"},{"key":"C","text":"$200"},{"key":"D","text":"$300"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Double Passage 14: Training course catalog & HR approval memo.', 7, '{"clue":"Hạn mức còn $900 - học phí PM-204 ($850) = còn lại $50.","analysis":"Hạn mức còn $900 - học phí PM-204 ($850) = còn lại $50.","translation":"Đoạn đôi: Danh mục khóa học TechSkill Academy và phiếu duyệt đào tạo cho nhân viên Nadia Hassan (hạn mức còn 900 đô, khóa trực tiếp).","vocabulary":[]}', 244, NOW(), NOW()),
(247, 'SINGLE_CHOICE', 'Part 7 G14 Q3: When does Nadia''s approved course take place?', 3, '{"text":"When does Nadia''s approved course take place?","options":[{"key":"A","text":"October 5-7"},{"key":"B","text":"October 12-14"},{"key":"C","text":"October 19-21"},{"key":"D","text":"November 1-3"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Double Passage 14: Training course catalog & HR approval memo.', 7, '{"clue":"Khóa PM-204 diễn ra từ ngày 12 đến 14 tháng 10.","analysis":"Khóa PM-204 diễn ra từ ngày 12 đến 14 tháng 10.","translation":"Đoạn đôi: Danh mục khóa học TechSkill Academy và phiếu duyệt đào tạo cho nhân viên Nadia Hassan (hạn mức còn 900 đô, khóa trực tiếp).","vocabulary":[]}', 244, NOW(), NOW()),
(248, 'SINGLE_CHOICE', 'Part 7 Double Passage 15: Warranty terms & repair receipt', NULL, '{"text":"Questions refer to the following passage (Part 7 Double Passage 15: Warranty terms & repair receipt).","content":"[DOCUMENT 1 — VERTEX LAPTOP LIMITED WARRANTY]\\nStandard 1-Year Warranty covers manufacturing defects in display, battery, and motherboard. Accidental liquid spills or cracked screens are excluded unless the customer purchased VertexCare Plus.\\n\\n[DOCUMENT 2 — REPAIR CENTER RECEIPT]\\nCustomer: Thomas Becker | Purchase Date: 7 months ago | Plan: VertexCare Plus\\nReported Issue: Cracked LCD screen from accidental drop\\nParts & Labor: $340 | Plan Coverage: -$290 | Customer Deductible Paid: $50","passage":"[DOCUMENT 1 — VERTEX LAPTOP LIMITED WARRANTY]\\nStandard 1-Year Warranty covers manufacturing defects in display, battery, and motherboard. Accidental liquid spills or cracked screens are excluded unless the customer purchased VertexCare Plus.\\n\\n[DOCUMENT 2 — REPAIR CENTER RECEIPT]\\nCustomer: Thomas Becker | Purchase Date: 7 months ago | Plan: VertexCare Plus\\nReported Issue: Cracked LCD screen from accidental drop\\nParts & Labor: $340 | Plan Coverage: -$290 | Customer Deductible Paid: $50"}', '{"info":"Parent reading passage stimulus"}', 4, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 15.', 7, '{"translation":"Đoạn đôi: Điều khoản bảo hành laptop Vertex và biên nhận sửa màn hình vỡ của khách có gói VertexCare Plus.","analysis":"Đoạn đôi: Điều khoản bảo hành laptop Vertex và biên nhận sửa màn hình vỡ của khách có gói VertexCare Plus.","vocabulary":[]}', NULL, NOW(), NOW()),
(249, 'SINGLE_CHOICE', 'Part 7 G15 Q1: Why was Thomas''s cracked screen covered by the repair center?', 1, '{"text":"Why was Thomas''s cracked screen covered by the repair center?","options":[{"key":"A","text":"It was a manufacturing defect"},{"key":"B","text":"He purchased the VertexCare Plus plan"},{"key":"C","text":"His laptop was under 30 days old"},{"key":"D","text":"The repair center made an exception"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Double Passage 15: Warranty terms & repair receipt.', 7, '{"clue":"Bảo hành chuẩn không bao gồm vỡ màn hình; anh được hỗ trợ nhờ mua gói VertexCare Plus.","analysis":"Bảo hành chuẩn không bao gồm vỡ màn hình; anh được hỗ trợ nhờ mua gói VertexCare Plus.","translation":"Đoạn đôi: Điều khoản bảo hành laptop Vertex và biên nhận sửa màn hình vỡ của khách có gói VertexCare Plus.","vocabulary":[]}', 248, NOW(), NOW()),
(250, 'SINGLE_CHOICE', 'Part 7 G15 Q2: How much did Thomas pay out of pocket?', 2, '{"text":"How much did Thomas pay out of pocket?","options":[{"key":"A","text":"$0"},{"key":"B","text":"$50"},{"key":"C","text":"$290"},{"key":"D","text":"$340"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Double Passage 15: Warranty terms & repair receipt.', 7, '{"clue":"Khách chỉ đóng phần miễn thường (''Customer Deductible Paid'') là $50.","analysis":"Khách chỉ đóng phần miễn thường (''Customer Deductible Paid'') là $50.","translation":"Đoạn đôi: Điều khoản bảo hành laptop Vertex và biên nhận sửa màn hình vỡ của khách có gói VertexCare Plus.","vocabulary":[]}', 248, NOW(), NOW()),
(251, 'SINGLE_CHOICE', 'Part 7 G15 Q3: Which component is covered even under the Standard Warranty?', 3, '{"text":"Which component is covered even under the Standard Warranty?","options":[{"key":"A","text":"Accidental liquid spill"},{"key":"B","text":"Motherboard manufacturing defect"},{"key":"C","text":"Dropped screen crack"},{"key":"D","text":"Lost power adapter"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Double Passage 15: Warranty terms & repair receipt.', 7, '{"clue":"Văn bản 1 nêu bảo hành chuẩn bao phủ lỗi sản xuất của màn hình, pin và bo mạch chủ.","analysis":"Văn bản 1 nêu bảo hành chuẩn bao phủ lỗi sản xuất của màn hình, pin và bo mạch chủ.","translation":"Đoạn đôi: Điều khoản bảo hành laptop Vertex và biên nhận sửa màn hình vỡ của khách có gói VertexCare Plus.","vocabulary":[]}', 248, NOW(), NOW()),
(252, 'SINGLE_CHOICE', 'Part 7 Triple Passage 16: Hotel conference flyer, email & invoice', NULL, '{"text":"Questions refer to the following passage (Part 7 Triple Passage 16: Hotel conference flyer, email & invoice).","content":"[DOC 1 — BAYVIEW HOTEL EVENT PACKAGES]\\nSilver Package: $1,200/day (Room + Wi-Fi + Screen)\\nGold Package: $1,800/day (Room + Wi-Fi + Screen + Morning/Afternoon Coffee Breaks)\\n\\n[DOC 2 — EMAIL FROM CLIENT]\\nTo: Bayview Events | From: Hannah Sato (Kora Pharma)\\nWe''d like to reserve the Gold Package for a two-day medical board meeting on Nov 10-11. Also add one simultaneous translation booth ($350 total).\\n\\n[DOC 3 — FINAL BILLING SUMMARY]\\n2-Day Event Package: $3,600 | Translation Booth: $350 | Early-Booking Credit: -$250 | Balance Due: $3,700","passage":"[DOC 1 — BAYVIEW HOTEL EVENT PACKAGES]\\nSilver Package: $1,200/day (Room + Wi-Fi + Screen)\\nGold Package: $1,800/day (Room + Wi-Fi + Screen + Morning/Afternoon Coffee Breaks)\\n\\n[DOC 2 — EMAIL FROM CLIENT]\\nTo: Bayview Events | From: Hannah Sato (Kora Pharma)\\nWe''d like to reserve the Gold Package for a two-day medical board meeting on Nov 10-11. Also add one simultaneous translation booth ($350 total).\\n\\n[DOC 3 — FINAL BILLING SUMMARY]\\n2-Day Event Package: $3,600 | Translation Booth: $350 | Early-Booking Credit: -$250 | Balance Due: $3,700"}', '{"info":"Parent reading passage stimulus"}', 5, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 16.', 7, '{"translation":"Đoạn ba: Bảng giá gói hội nghị Bayview Hotel, email đặt gói Gold 2 ngày kèm cabin dịch thuật, và bảng tổng kết thanh toán $3,700.","analysis":"Đoạn ba: Bảng giá gói hội nghị Bayview Hotel, email đặt gói Gold 2 ngày kèm cabin dịch thuật, và bảng tổng kết thanh toán $3,700.","vocabulary":[]}', NULL, NOW(), NOW()),
(253, 'SINGLE_CHOICE', 'Part 7 G16 Q1: Why did the 2-day event package total $3,600?', 1, '{"text":"Why did the 2-day event package total $3,600?","options":[{"key":"A","text":"Three days of Silver Package"},{"key":"B","text":"Two days of Gold Package at $1,800/day"},{"key":"C","text":"Includes catering dinner"},{"key":"D","text":"Weekend surcharge applied"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Triple Passage 16: Hotel conference flyer, email & invoice.', 7, '{"clue":"Gói Gold ($1,800/ngày) x 2 ngày = $3,600.","analysis":"Gói Gold ($1,800/ngày) x 2 ngày = $3,600.","translation":"Đoạn ba: Bảng giá gói hội nghị Bayview Hotel, email đặt gói Gold 2 ngày kèm cabin dịch thuật, và bảng tổng kết thanh toán $3,700.","vocabulary":[]}', 252, NOW(), NOW()),
(254, 'SINGLE_CHOICE', 'Part 7 G16 Q2: What extra equipment did Kora Pharma request?', 2, '{"text":"What extra equipment did Kora Pharma request?","options":[{"key":"A","text":"Extra projectors"},{"key":"B","text":"A simultaneous translation booth"},{"key":"C","text":"Wireless microphones"},{"key":"D","text":"Video recording crew"}]}', '{"selected":"B","key":"B"}', 2, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Triple Passage 16: Hotel conference flyer, email & invoice.', 7, '{"clue":"Văn bản 2 yêu cầu thêm cabin phiên dịch song song ($350).","analysis":"Văn bản 2 yêu cầu thêm cabin phiên dịch song song ($350).","translation":"Đoạn ba: Bảng giá gói hội nghị Bayview Hotel, email đặt gói Gold 2 ngày kèm cabin dịch thuật, và bảng tổng kết thanh toán $3,700.","vocabulary":[]}', 252, NOW(), NOW()),
(255, 'SINGLE_CHOICE', 'Part 7 G16 Q3: How much discount did Kora Pharma receive on the final bill?', 3, '{"text":"How much discount did Kora Pharma receive on the final bill?","options":[{"key":"A","text":"$150"},{"key":"B","text":"$250"},{"key":"C","text":"$350"},{"key":"D","text":"$500"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Triple Passage 16: Hotel conference flyer, email & invoice.', 7, '{"clue":"Văn bản 3 ghi nhận ''Early-Booking Credit: -$250''.","analysis":"Văn bản 3 ghi nhận ''Early-Booking Credit: -$250''.","translation":"Đoạn ba: Bảng giá gói hội nghị Bayview Hotel, email đặt gói Gold 2 ngày kèm cabin dịch thuật, và bảng tổng kết thanh toán $3,700.","vocabulary":[]}', 252, NOW(), NOW()),
(256, 'SINGLE_CHOICE', 'Part 7 Triple Passage 17: Supplier catalog, purchase order & delivery note', NULL, '{"text":"Questions refer to the following passage (Part 7 Triple Passage 17: Supplier catalog, purchase order & delivery note).","content":"[DOC 1 — NORDIC OFFICE SUPPLY CATALOG]\\nItem #P-10: Recycled A4 Paper (Box of 5 reams) — $35\\nItem #M-22: Dry-Erase Whiteboard Markers (Pack of 12) — $18\\nItem #B-45: Ergonomic Keyboard Tray — $65\\n\\n[DOC 2 — PURCHASE ORDER #774]\\n10 boxes Item #P-10 | 5 packs Item #M-22 | 4 units Item #B-45\\n\\n[DOC 3 — WAREHOUSE DELIVERY NOTE]\\nDelivered: 10 boxes #P-10, 5 packs #M-22, 2 units #B-45.\\nRemark: Remaining 2 units of #B-45 are backordered and will ship free of charge on Thursday.","passage":"[DOC 1 — NORDIC OFFICE SUPPLY CATALOG]\\nItem #P-10: Recycled A4 Paper (Box of 5 reams) — $35\\nItem #M-22: Dry-Erase Whiteboard Markers (Pack of 12) — $18\\nItem #B-45: Ergonomic Keyboard Tray — $65\\n\\n[DOC 2 — PURCHASE ORDER #774]\\n10 boxes Item #P-10 | 5 packs Item #M-22 | 4 units Item #B-45\\n\\n[DOC 3 — WAREHOUSE DELIVERY NOTE]\\nDelivered: 10 boxes #P-10, 5 packs #M-22, 2 units #B-45.\\nRemark: Remaining 2 units of #B-45 are backordered and will ship free of charge on Thursday."}', '{"info":"Parent reading passage stimulus"}', 5, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 17.', 7, '{"translation":"Đoạn ba: Catalog văn phòng phẩm Nordic, đơn đặt hàng #774 và phiếu giao hàng ghi nhận còn thiếu 2 khay bàn phím #B-45 sẽ giao bù thứ Năm.","analysis":"Đoạn ba: Catalog văn phòng phẩm Nordic, đơn đặt hàng #774 và phiếu giao hàng ghi nhận còn thiếu 2 khay bàn phím #B-45 sẽ giao bù thứ Năm.","vocabulary":[]}', NULL, NOW(), NOW()),
(257, 'SINGLE_CHOICE', 'Part 7 G17 Q1: Which item was partially backordered?', 1, '{"text":"Which item was partially backordered?","options":[{"key":"A","text":"Recycled A4 Paper"},{"key":"B","text":"Whiteboard Markers"},{"key":"C","text":"Ergonomic Keyboard Tray"},{"key":"D","text":"All three items"}]}', '{"selected":"C","key":"C"}', 4, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Triple Passage 17: Supplier catalog, purchase order & delivery note.', 7, '{"clue":"Đối chiếu mã #B-45 ở Văn bản 1 & 3 -> Ergonomic Keyboard Tray giao 2/4 chiếc.","analysis":"Đối chiếu mã #B-45 ở Văn bản 1 & 3 -> Ergonomic Keyboard Tray giao 2/4 chiếc.","translation":"Đoạn ba: Catalog văn phòng phẩm Nordic, đơn đặt hàng #774 và phiếu giao hàng ghi nhận còn thiếu 2 khay bàn phím #B-45 sẽ giao bù thứ Năm.","vocabulary":[]}', 256, NOW(), NOW()),
(258, 'SINGLE_CHOICE', 'Part 7 G17 Q2: What was the total cost of the whiteboard markers ordered?', 2, '{"text":"What was the total cost of the whiteboard markers ordered?","options":[{"key":"A","text":"$35"},{"key":"B","text":"$70"},{"key":"C","text":"$90"},{"key":"D","text":"$180"}]}', '{"selected":"C","key":"C"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Triple Passage 17: Supplier catalog, purchase order & delivery note.', 7, '{"clue":"5 packs #M-22 x $18/pack = $90.","analysis":"5 packs #M-22 x $18/pack = $90.","translation":"Đoạn ba: Catalog văn phòng phẩm Nordic, đơn đặt hàng #774 và phiếu giao hàng ghi nhận còn thiếu 2 khay bàn phím #B-45 sẽ giao bù thứ Năm.","vocabulary":[]}', 256, NOW(), NOW()),
(259, 'SINGLE_CHOICE', 'Part 7 G17 Q3: When will the remaining items be dispatched?', 3, '{"text":"When will the remaining items be dispatched?","options":[{"key":"A","text":"On Tuesday"},{"key":"B","text":"On Wednesday"},{"key":"C","text":"On Thursday"},{"key":"D","text":"Next Monday"}]}', '{"selected":"C","key":"C"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Triple Passage 17: Supplier catalog, purchase order & delivery note.', 7, '{"clue":"2 khay bàn phím còn lại sẽ gửi miễn phí vận chuyển vào thứ Năm.","analysis":"2 khay bàn phím còn lại sẽ gửi miễn phí vận chuyển vào thứ Năm.","translation":"Đoạn ba: Catalog văn phòng phẩm Nordic, đơn đặt hàng #774 và phiếu giao hàng ghi nhận còn thiếu 2 khay bàn phím #B-45 sẽ giao bù thứ Năm.","vocabulary":[]}', 256, NOW(), NOW()),
(260, 'SINGLE_CHOICE', 'Part 7 Triple Passage 18: Airline baggage rule, ticket confirmation & email', NULL, '{"text":"Questions refer to the following passage (Part 7 Triple Passage 18: Airline baggage rule, ticket confirmation & email).","content":"[DOC 1 — SKYLINE AIR BAGGAGE POLICY]\\nEconomy Lite: 1 carry-on only (checked bag $40 each)\\nEconomy Flex: 1 carry-on + 1 checked bag up to 23 kg free\\nBusiness Class: 2 carry-ons + 2 checked bags up to 32 kg free\\n\\n[DOC 2 — E-TICKET CONFIRMATION]\\nPassenger: Minh Nguyen | Fare Class: Economy Flex | Flight: SL-208 Hanoi to Tokyo\\n\\n[DOC 3 — EMAIL FROM PASSENGER]\\nHi Skyline Support, I am bringing one 20 kg suitcase and one 18 kg trade-show display case on Flight SL-208. Since my fare includes only one free checked bag, how can I prepay for the second bag online?","passage":"[DOC 1 — SKYLINE AIR BAGGAGE POLICY]\\nEconomy Lite: 1 carry-on only (checked bag $40 each)\\nEconomy Flex: 1 carry-on + 1 checked bag up to 23 kg free\\nBusiness Class: 2 carry-ons + 2 checked bags up to 32 kg free\\n\\n[DOC 2 — E-TICKET CONFIRMATION]\\nPassenger: Minh Nguyen | Fare Class: Economy Flex | Flight: SL-208 Hanoi to Tokyo\\n\\n[DOC 3 — EMAIL FROM PASSENGER]\\nHi Skyline Support, I am bringing one 20 kg suitcase and one 18 kg trade-show display case on Flight SL-208. Since my fare includes only one free checked bag, how can I prepay for the second bag online?"}', '{"info":"Parent reading passage stimulus"}', 5, 'READING', 'Bài đọc hiểu TOEIC Part 7 số 18.', 7, '{"translation":"Đoạn ba: Quy định hành lý Skyline Air, vé điện tử hạng Economy Flex của Minh Nguyễn, và email hỏi đóng phí ký gửi kiện thứ 2.","analysis":"Đoạn ba: Quy định hành lý Skyline Air, vé điện tử hạng Economy Flex của Minh Nguyễn, và email hỏi đóng phí ký gửi kiện thứ 2.","vocabulary":[]}', NULL, NOW(), NOW()),
(261, 'SINGLE_CHOICE', 'Part 7 G18 Q1: How many free checked bags are included in Minh''s ticket?', 1, '{"text":"How many free checked bags are included in Minh''s ticket?","options":[{"key":"A","text":"None"},{"key":"B","text":"One up to 23 kg"},{"key":"C","text":"Two up to 23 kg"},{"key":"D","text":"Two up to 32 kg"}]}', '{"selected":"B","key":"B"}', 3, 'READING', 'Câu hỏi đọc hiểu số 1 của Part 7 Triple Passage 18: Airline baggage rule, ticket confirmation & email.', 7, '{"clue":"Hạng Economy Flex được miễn phí 1 kiện ký gửi tối đa 23 kg.","analysis":"Hạng Economy Flex được miễn phí 1 kiện ký gửi tối đa 23 kg.","translation":"Đoạn ba: Quy định hành lý Skyline Air, vé điện tử hạng Economy Flex của Minh Nguyễn, và email hỏi đóng phí ký gửi kiện thứ 2.","vocabulary":[]}', 260, NOW(), NOW()),
(262, 'SINGLE_CHOICE', 'Part 7 G18 Q2: Why does Minh need to pay an extra baggage fee?', 2, '{"text":"Why does Minh need to pay an extra baggage fee?","options":[{"key":"A","text":"His suitcase exceeds 23 kg"},{"key":"B","text":"He is checking a second bag (display case)"},{"key":"C","text":"He booked Economy Lite"},{"key":"D","text":"He missed online check-in"}]}', '{"selected":"B","key":"B"}', 4, 'READING', 'Câu hỏi đọc hiểu số 2 của Part 7 Triple Passage 18: Airline baggage rule, ticket confirmation & email.', 7, '{"clue":"Cả 2 kiện đều dưới 23 kg nhưng hạng Economy Flex chỉ miễn phí kiện đầu tiên.","analysis":"Cả 2 kiện đều dưới 23 kg nhưng hạng Economy Flex chỉ miễn phí kiện đầu tiên.","translation":"Đoạn ba: Quy định hành lý Skyline Air, vé điện tử hạng Economy Flex của Minh Nguyễn, và email hỏi đóng phí ký gửi kiện thứ 2.","vocabulary":[]}', 260, NOW(), NOW()),
(263, 'SINGLE_CHOICE', 'Part 7 G18 Q3: What is the weight of the trade-show display case?', 3, '{"text":"What is the weight of the trade-show display case?","options":[{"key":"A","text":"18 kg"},{"key":"B","text":"20 kg"},{"key":"C","text":"23 kg"},{"key":"D","text":"32 kg"}]}', '{"selected":"A","key":"A"}', 2, 'READING', 'Câu hỏi đọc hiểu số 3 của Part 7 Triple Passage 18: Airline baggage rule, ticket confirmation & email.', 7, '{"clue":"Văn bản 3 ghi rõ ''one 18 kg trade-show display case''.","analysis":"Văn bản 3 ghi rõ ''one 18 kg trade-show display case''.","translation":"Đoạn ba: Quy định hành lý Skyline Air, vé điện tử hạng Economy Flex của Minh Nguyễn, và email hỏi đóng phí ký gửi kiện thứ 2.","vocabulary":[]}', 260, NOW(), NOW());
